window.SAA_EXAMS = [{"id":"exam-set-01","file":"set-01.md","num":"問題セット01","title":"第1分野：セキュアなアーキテクチャの設計","questions":[{"n":1,"topic":"アクセス管理","level":2,"body":["EC2インスタンス上で稼働するアプリケーションが、Amazon S3バケットへファイルを書き込んでいます。現在はIAMユーザーのアクセスキーをアプリケーションの設定ファイルに記載しており、セキュリティ監査で是正を求められました。運用負荷を最小限に抑えつつ、この指摘に対応する方法はどれですか。"],"options":[{"l":"A","html":"アクセスキーを設定ファイルから環境変数へ移し、90日ごとに手動でローテーションする"},{"l":"B","html":"アクセスキーをAWS Secrets Managerに保存し、アプリケーション起動時に取得するよう変更する"},{"l":"C","html":"S3へのアクセス権限を持つIAMロールを作成し、インスタンスプロファイルとしてEC2にアタッチしたうえで、設定ファイルからアクセスキーを削除する"},{"l":"D","html":"S3バケットポリシーで、EC2インスタンスのパブリックIPアドレスからのアクセスのみを許可する"}],"answer":["C"],"multi":false,"req":"","key":"AWS上で動くコンピューティング（EC2・Lambda・ECS）に権限を与える手段は<b>IAMロール</b>です。ロールが配布する認証情報は一時的なもので自動的にローテーションされるため、長期のアクセスキーそのものが不要になります。","reasons":[{"l":"A","html":"保管場所が変わっただけで長期認証情報は残り、手動ローテーションという運用負荷も残ります。"},{"l":"B","html":"Secrets Managerは「AWSの外部にある資格情報（DBのパスワードなど）」を管理する仕組みです。IAMロールを使えばアクセスキー自体が不要になるため、取得処理を実装する分だけ余計です。"},{"l":"D","html":"IPアドレスによる制限は認証ではありません。EIPの付け替えやSSRFによる悪用に耐えられず、監査指摘（長期認証情報の埋め込み）への回答にもなっていません。"}],"refs":"<a href=\"#security\" data-go=\"security\">第5章 5.1 AWS IAM</a> ／ <a href=\"#d1\" data-go=\"d1\">第11章 11.1 アクセス管理</a>"},{"n":2,"topic":"クロスアカウント","level":2,"body":["外部のコンサルティング会社に、本番AWSアカウントのリソース構成を読み取り専用で調査してもらうことになりました。相手先は自社のAWSアカウントを保有しています。最も安全な方法はどれですか。"],"options":[{"l":"A","html":"本番アカウントにIAMユーザーを作成し、アクセスキーをメールで共有する"},{"l":"B","html":"読み取り専用ポリシーを付与したIAMロールを作成し、信頼ポリシーで相手のアカウントIDを指定したうえで、<b>外部ID（External ID）</b>の指定を必須にする"},{"l":"C","html":"ルートユーザーの認証情報を一時的に共有し、作業後にパスワードを変更する"},{"l":"D","html":"対象リソースのリソースポリシーで、すべてのプリンシパル（<code>\"Principal\": \"*\"</code>）からの読み取りを許可する"}],"answer":["B"],"multi":false,"req":"","key":"別アカウントへのアクセス提供は<b>ロールの引き受け（AssumeRole）</b>が基本形です。相手が他社（第三者）の場合は<b>外部ID</b>を必須にして、「混乱した代理人（Confused Deputy）問題」を防ぎます。","reasons":[{"l":"A","html":"長期のアクセスキーが社外に渡り、失効管理もできません。"},{"l":"C","html":"ルートユーザーは最初の設定以降は使用せず、共有は論外です。"},{"l":"D","html":"インターネット全体へ公開することになり、要件（特定の相手に限定）を満たしません。"}],"refs":"<a href=\"#security\" data-go=\"security\">第5章 5.1 AWS IAM</a> ／ <a href=\"#d1\" data-go=\"d1\">第11章 11.1 アクセス管理</a>"},{"n":3,"topic":"組織統制","level":3,"body":["ある企業はAWS Organizationsで50個のアカウントを管理しています。データ主権の要件から、承認された3つのリージョン以外ではリソースを作成できないようにしたいと考えています。各メンバーアカウントには管理者権限を持つ開発者が存在し、<b>その開発者自身が制限を解除できてはなりません</b>。適切な方法はどれですか。"],"options":[{"l":"A","html":"各アカウントのIAMポリシーに、未承認リージョンを拒否する条件を追加する"},{"l":"B","html":"AWS Configルールで未承認リージョンのリソースを検出し、通知する"},{"l":"C","html":"各アカウントのIAMユーザーにアクセス許可境界（Permissions Boundary）を設定する"},{"l":"D","html":"Organizationsのサービスコントロールポリシー（SCP）で、未承認リージョンでのアクションを拒否し、対象のOUに適用する"}],"answer":["D"],"multi":false,"req":"","key":"「<b>組織全体</b>に」「<b>メンバーアカウントの管理者でも解除できない</b>」上限を課せるのはSCPだけです。SCPはメンバーアカウントのルートユーザーにも効きます。","reasons":[{"l":"A","html":"アカウント内の管理者が自分でポリシーを編集できるため、制限として成立しません。"},{"l":"B","html":"Configは<b>検出と是正</b>の仕組みであり、作成そのものを<b>予防</b>できません。設問は予防を求めています。"},{"l":"C","html":"アクセス許可境界は個々のIAMエンティティに付ける上限で、アカウント全体・組織全体への強制にはなりません（設定漏れも起こります）。"}],"refs":"<a href=\"#management\" data-go=\"management\">第8章 8.5 AWS Organizations</a> ／ <a href=\"#d1\" data-go=\"d1\">第11章 11.1 アクセス管理</a>"},{"n":4,"topic":"データ保護","level":1,"body":["非公開のS3バケットに保管しているレポートPDFを、取引先の担当者1名に対し、<b>24時間だけ</b>ダウンロードさせたいと考えています。取引先はAWSアカウントを持っていません。最小の手間で実現する方法はどれですか。"],"options":[{"l":"A","html":"対象オブジェクトに対する事前署名URL（Presigned URL）を有効期限付きで発行して渡す"},{"l":"B","html":"バケットポリシーで当該オブジェクトをパブリック読み取り可能にし、24時間後に設定を戻す"},{"l":"C","html":"CloudFrontディストリビューションを作成し、OACでバケットに接続する"},{"l":"D","html":"取引先向けのIAMユーザーを作成し、24時間後に削除する"}],"answer":["A"],"multi":false,"req":"","key":"「<b>特定のオブジェクト</b>を」「<b>期限付きで</b>」「<b>AWSアカウントを持たない相手に</b>」渡す要件は事前署名URLの定番です。","reasons":[{"l":"B","html":"公開期間中は誰でもアクセスでき、設定の戻し忘れという運用事故も招きます。"},{"l":"C","html":"CloudFront＋OACはバケットを非公開のままCDN配信する構成で、1回限りの共有には過剰です（期限付き配布をCloudFrontで行うなら署名付きURL／Cookieを併用します）。"},{"l":"D","html":"AWSアカウントを持たない相手にIAMユーザーを発行する運用は負荷が高く、削除漏れのリスクもあります。"}],"refs":"<a href=\"#storage\" data-go=\"storage\">第2章 2.1 Amazon S3</a> ／ <a href=\"#d1\" data-go=\"d1\">第11章 11.2 データ保護</a>"},{"n":5,"topic":"暗号化","level":2,"body":["本番稼働中のAmazon RDS for MySQLインスタンスが、作成時に暗号化を有効化していなかったことが判明しました。コンプライアンス要件を満たすため、保存データを暗号化する必要があります。適切な手順はどれですか。"],"options":[{"l":"A","html":"RDSコンソールで対象インスタンスの設定を変更し、暗号化を有効にする"},{"l":"B","html":"スナップショットを取得し、そのスナップショットを暗号化を指定してコピーしたうえで復元し、アプリケーションの接続先を新インスタンスへ切り替える"},{"l":"C","html":"マルチAZ配置に変更する。スタンバイ作成時に暗号化が適用される"},{"l":"D","html":"暗号化を有効にしたリードレプリカを同一リージョンに作成し、プライマリへ昇格させる"}],"answer":["B"],"multi":false,"req":"","key":"RDS・EBSとも、<b>暗号化は作成時にしか指定できません</b>。既存リソースの暗号化は「スナップショット → 暗号化を指定してコピー → 復元」が定石です。","reasons":[{"l":"A","html":"稼働中インスタンスの暗号化設定を後から有効化することはできません。"},{"l":"C","html":"マルチAZは可用性のための構成で、暗号化とは無関係です。"},{"l":"D","html":"未暗号化のインスタンスから暗号化されたリードレプリカを作成することはできません。"}],"refs":"<a href=\"#database\" data-go=\"database\">第4章 4.1 Amazon RDS</a> ／ <a href=\"#d1\" data-go=\"d1\">第11章 11.2 データ保護</a>"},{"n":6,"topic":"暗号化","level":2,"body":["大量の小さなオブジェクトをS3に書き込むアプリケーションで、SSE-KMSを使用しています。AWS KMSのリクエスト数が急増して料金が膨らみ、スロットリングも発生し始めました。監査要件があるため、キーの利用履歴は引き続き記録する必要があります。適切な対処はどれですか。"],"options":[{"l":"A","html":"暗号化方式をSSE-S3に変更する"},{"l":"B","html":"暗号化をやめ、バケットポリシーでHTTPS通信のみ許可する"},{"l":"C","html":"カスタマー管理キーを複数作成し、オブジェクトごとに使い分ける"},{"l":"D","html":"S3バケットキー（S3 Bucket Keys）を有効化する"}],"answer":["D"],"multi":false,"req":"","key":"S3バケットキーはバケット単位で短期間有効なキーを生成し、<b>KMSへのリクエスト数を大幅に削減</b>します。SSE-KMSのままなので監査要件も維持できます。","reasons":[{"l":"A","html":"SSE-S3ではCloudTrailにキー利用が記録されず、キーの管理・制御もできないため監査要件を満たせません。"},{"l":"B","html":"保存時の暗号化要件を放棄しており、要件違反です（HTTPSは転送時の保護）。"},{"l":"C","html":"キーを増やしてもリクエスト数の総量は変わらず、管理対象が増えるだけです。"}],"refs":"<a href=\"#storage\" data-go=\"storage\">第2章 2.1 Amazon S3</a> ／ <a href=\"#security\" data-go=\"security\">第5章 5.8 AWS KMS</a>"},{"n":7,"topic":"検出と監視","level":2,"body":["セキュリティチームから次の3つの要望が挙がりました。それぞれに最も適したサービスの組み合わせはどれですか。","1. S3バケット内に個人情報（クレジットカード番号など）が保存されていないか継続的に確認したい","2. EC2インスタンスのOSやライブラリに既知の脆弱性（CVE）がないか継続的に確認したい","3. 通常と異なる地域からのAPI呼び出しや、既知の不正IPとの通信を検知したい"],"options":[{"l":"A","html":"1: Amazon Macie ／ 2: Amazon Inspector ／ 3: Amazon GuardDuty"},{"l":"B","html":"1: Amazon GuardDuty ／ 2: Amazon Macie ／ 3: Amazon Inspector"},{"l":"C","html":"1: AWS Config ／ 2: Amazon Macie ／ 3: AWS CloudTrail"},{"l":"D","html":"1: Amazon Inspector ／ 2: Amazon GuardDuty ／ 3: AWS Security Hub"}],"answer":["A"],"multi":false,"req":"","key":"検出系の役割分担は固定です。<b>Macie＝S3の機密データ発見／Inspector＝脆弱性（CVE）診断／GuardDuty＝不審な振る舞いの検知</b>。","reasons":[{"l":"B","html":"3つのサービスの役割がすべて入れ替わっています。"},{"l":"C","html":"Configは「リソース設定の変更履歴と準拠状況」、CloudTrailは「誰がAPIを呼んだかの記録」であり、機密データの発見や脅威検知そのものは行いません。"},{"l":"D","html":"Security Hubは各種検出結果を<b>集約</b>するサービスで、単独で脅威を検知するものではありません。"}],"refs":"<a href=\"#security\" data-go=\"security\">第5章 5.13 検出系の整理</a> ／ <a href=\"#cmp\" data-go=\"cmp\">付録A セキュリティ・運用管理</a>"},{"n":8,"topic":"多層防御","level":2,"body":["Network Load Balancer（NLB）の背後で稼働するWebアプリケーションに対し、SQLインジェクションとクロスサイトスクリプティングの防御を追加するよう指示されました。適切な構成はどれですか。"],"options":[{"l":"A","html":"NLBの前段にCloudFrontまたはApplication Load Balancerを配置し、そちらにWeb ACLを関連付ける"},{"l":"B","html":"NLBにAWS WAFのWeb ACLを関連付ける"},{"l":"C","html":"AWS Shield Standardを有効化する"},{"l":"D","html":"ネットワークACLで、攻撃元のIPアドレスを拒否する"}],"answer":["A"],"multi":false,"req":"","key":"AWS WAFを関連付けられるのは<b>CloudFront／ALB／API Gateway／AppSync／Cognitoユーザープール</b>です。<b>NLBやEC2には直接付けられない</b>ため、WAFを適用できる層を前段に置きます。","reasons":[{"l":"B","html":"NLBはL4のロードバランサーで、WAF（L7）を関連付けられません。"},{"l":"C","html":"Shieldが守るのはDDoS攻撃であり、SQLインジェクションのようなアプリケーション層の攻撃には対応しません。"},{"l":"D","html":"NACLはIPアドレス単位の遮断で、リクエストの中身を検査できません。攻撃元IPが変わるたびに後追いになります。"}],"refs":"<a href=\"#security\" data-go=\"security\">第5章 5.5 AWS WAF</a> ／ <a href=\"#d1\" data-go=\"d1\">第11章 11.3 多層防御</a>"},{"n":9,"topic":"多層防御","level":2,"body":["プライベートサブネット上のEC2インスタンスに対し、運用担当者がシェル接続して調査を行う必要があります。セキュリティポリシーにより、SSHキーの配布、踏み台ホストの設置、22番ポートの開放はいずれも認められていません。また、誰がいつ接続したかの記録が必要です。適切な方法はどれですか。"],"options":[{"l":"A","html":"クライアントVPNを構築し、VPN経由でSSH接続する"},{"l":"B","html":"パブリックサブネットに踏み台ホストを設置し、セキュリティグループで社内IPからのSSHのみ許可する"},{"l":"C","html":"AWS Systems Manager Session Managerを使用する（SSMエージェントとインスタンスプロファイルを構成し、必要に応じてVPCエンドポイントを配置する）"},{"l":"D","html":"インスタンスにパブリックIPを割り当て、EC2 Instance Connectで接続する"}],"answer":["C"],"multi":false,"req":"","key":"「<b>SSHキー不要・踏み台不要・インバウンドポート開放不要</b>」に「<b>操作ログが残る</b>」が揃えばSession Managerです。接続はSSMのアウトバウンド経路（またはVPCエンドポイント）を通ります。","reasons":[{"l":"A","html":"VPNを経由しても、最終的にSSHキーと22番ポートが必要になります。"},{"l":"B","html":"踏み台の設置と22番ポートの開放という、禁止されている条件そのものです。"},{"l":"D","html":"パブリックIPの割り当てはプライベートサブネットの前提に反し、インバウンド許可も必要になります。"}],"refs":"<a href=\"#management\" data-go=\"management\">第8章 8.4 AWS Systems Manager</a> ／ <a href=\"#d1\" data-go=\"d1\">第11章 11.3 多層防御</a>"},{"n":10,"topic":"責任共有モデル","level":1,"body":["AWSの責任共有モデルにおいて、<b>利用者（顧客）側の責任</b>に含まれるものはどれですか。"],"options":[{"l":"A","html":"RDSが稼働する物理ホストのハードウェア保守"},{"l":"B","html":"IAMポリシーの設計と、保存データを暗号化するかどうかの判断"},{"l":"C","html":"S3の物理ディスクの廃棄・消磁"},{"l":"D","html":"Lambda実行環境の基盤OSへのパッチ適用"}],"answer":["B"],"multi":false,"req":"","key":"マネージドの度合いが上がるほどAWS側の責任は増えますが、<b>データの分類・暗号化の要否・アクセス制御（IAM）は常に利用者の責任</b>です。","reasons":[{"l":"A","html":"物理ハードウェアの保守は「クラウド<b>の</b>セキュリティ」としてAWSの責任です。"},{"l":"C","html":"データセンター内の物理媒体の処分もAWSの責任範囲です。"},{"l":"D","html":"Lambdaは実行環境そのものがマネージドであり、基盤OSのパッチはAWSが行います（EC2であれば利用者の責任になります）。"}],"refs":"<a href=\"#d1\" data-go=\"d1\">第11章 11.4 責任共有モデル</a>"}]},{"id":"exam-set-02","file":"set-02.md","num":"問題セット02","title":"第2分野：弾力性に優れたアーキテクチャの設計","questions":[{"n":1,"topic":"スケーリング","level":2,"body":["Auto Scalingグループ配下のEC2インスタンスで動くWebアプリケーションが、メモリリークにより応答しなくなる事象が発生しています。OSは起動したままでHTTPリクエストに500エラーを返し続けますが、Auto Scalingはインスタンスを置き換えません。ALBのターゲットグループでは当該インスタンスが<code>unhealthy</code>と表示されています。適切な対処はどれですか。"],"options":[{"l":"A","html":"スケーリングポリシーのクールダウン期間を短縮する"},{"l":"B","html":"EC2の詳細モニタリングを有効化し、メトリクスの取得間隔を1分にする"},{"l":"C","html":"Auto Scalingグループのヘルスチェックタイプを「ELB」に変更する"},{"l":"D","html":"ALBのアイドルタイムアウト値を延長する"}],"answer":["C"],"multi":false,"req":"","key":"Auto Scalingの既定のヘルスチェックは<b>EC2ステータスチェックのみ</b>で、「OSは生きているがアプリが異常」という状態を検知できません。<b>ELBヘルスチェックを有効化</b>して初めて、ロードバランサーの判定に基づく置き換えが行われます。","reasons":[{"l":"A","html":"クールダウンは連続したスケーリング動作の間隔であり、異常インスタンスの検知とは無関係です。"},{"l":"B","html":"メトリクスの粒度が上がるだけで、置き換えの判断基準は変わりません。"},{"l":"D","html":"アイドルタイムアウトは接続の維持時間であり、異常の検知・置き換えには影響しません。"}],"refs":"<a href=\"#compute\" data-go=\"compute\">第1章 1.2 EC2 Auto Scaling</a> ／ <a href=\"#d2\" data-go=\"d2\">第12章 12.1 スケーリング戦略</a>"},{"n":2,"topic":"疎結合","level":2,"body":["ECサイトの注文APIが、セール開始直後の数分間にリクエストが急増し、バックエンドのRDSへの書き込みが追いつかずエラーを返しています。注文処理は即時応答が必須ではなく、数十秒以内に完了すれば許容されます。最も適切な設計変更はどれですか。"],"options":[{"l":"A","html":"ALBでスティッキーセッションを有効化する"},{"l":"B","html":"RDSインスタンスを常時、ピーク時に耐えられるサイズへスケールアップする"},{"l":"C","html":"APIとバックエンド処理の間にAmazon SQSキューを挟み、ワーカーはキューの滞留数に応じてAuto Scalingさせる"},{"l":"D","html":"CloudFrontを前段に配置し、注文APIのレスポンスをキャッシュする"}],"answer":["C"],"multi":false,"req":"","key":"「<b>急増を吸収したい</b>」「<b>即時応答は不要</b>」はキューによる<b>バッファリング</b>の典型です。ワーカー数は<code>ApproximateNumberOfMessagesVisible</code>などキューの滞留量を基準にスケールさせます。","reasons":[{"l":"A","html":"スティッキーセッションは同一クライアントを同じターゲットへ固定する仕組みで、書き込み負荷は軽減しません。"},{"l":"B","html":"ピークに合わせた常時スケールアップは、平常時のコストが無駄になります。急増の度合いによっては上限にも当たります。"},{"l":"D","html":"書き込み（注文登録）はキャッシュできません。CloudFrontは読み取り配信の高速化のための仕組みです。"}],"refs":"<a href=\"#integration\" data-go=\"integration\">第6章 6.1 Amazon SQS</a> ／ <a href=\"#d2\" data-go=\"d2\">第12章 12.2 疎結合アーキテクチャ</a>"},{"n":3,"topic":"疎結合","level":3,"body":["Amazon SQS標準キューからメッセージを取得して処理するワーカーで、<b>同じ注文が2回処理される</b>事象が発生しています。処理時間はメッセージによって異なり、長いものでは10分近くかかります。キューの可視性タイムアウトは既定の30秒のままです。根本的な対処はどれですか。"],"options":[{"l":"A","html":"可視性タイムアウトを処理の最大所要時間より長く設定し、長時間処理では<code>ChangeMessageVisibility</code>で延長する。あわせて処理を冪等に実装する"},{"l":"B","html":"ロングポーリングを有効化し、受信待機時間を20秒にする"},{"l":"C","html":"デッドレターキュー（DLQ）を設定し、<code>maxReceiveCount</code>を1にする"},{"l":"D","html":"FIFOキューへ移行する"}],"answer":["A"],"multi":false,"req":"","key":"重複処理の原因は、<b>処理が終わる前に可視性タイムアウトが切れて、同じメッセージが別のワーカーに再配信されること</b>です。タイムアウトを処理時間に合わせるのが直接の対処で、標準キューは「最低1回」の配信であるため冪等な実装も必要です。","reasons":[{"l":"B","html":"ロングポーリングは空受信を減らしてAPIコール料金とレイテンシを改善する設定で、重複の原因には触れていません。"},{"l":"C","html":"DLQは失敗メッセージの隔離先です。<code>maxReceiveCount</code>を1にすると、一度でも再配信されたメッセージが即座に隔離され、正常な処理まで失われます。"},{"l":"D","html":"FIFOキューは順序保証と重複排除を提供しますが、スループット上限（300 TPS）という制約が付きます。可視性タイムアウトが処理時間より短い問題は解決せず、原因への対処になっていません。"}],"refs":"<a href=\"#integration\" data-go=\"integration\">第6章 6.1 Amazon SQS</a>"},{"n":4,"topic":"イベント駆動","level":2,"body":["S3バケットに画像がアップロードされたことを契機に、<b>サムネイル生成</b>と<b>検索インデックスの更新</b>という2つの独立した処理を実行したいと考えています。一方の処理が失敗しても、もう一方に影響せず、それぞれ独立して再試行できる必要があります。適切な構成はどれですか。"],"options":[{"l":"A","html":"S3イベント通知をAmazon SNSトピックへ送り、2つのSQSキューをサブスクライブさせて、それぞれのワーカーが処理する"},{"l":"B","html":"S3イベント通知で単一のLambda関数を起動し、その関数内で両方の処理を順番に実行する"},{"l":"C","html":"S3イベント通知を1つのSQSキューへ送り、2種類のワーカーが同じキューをポーリングする"},{"l":"D","html":"同じイベント種別・同じプレフィックスに対してS3イベント通知を2つ設定し、それぞれ別のLambda関数を起動する"}],"answer":["A"],"multi":false,"req":"","key":"1つのイベントを複数の処理系へ配り、<b>各処理系が独立して再試行できる</b>形が<b>SNSファンアウト（SNS＋複数SQS）</b>です。","reasons":[{"l":"B","html":"1つの関数に両処理を同居させると、片方の失敗がもう片方の再実行を巻き込みます（独立性がありません）。"},{"l":"C","html":"SQSのメッセージは1つのコンシューマーが取得すると他からは見えなくなるため、2種類の処理へ同じメッセージを届けられません。"},{"l":"D","html":"S3イベント通知は、同じイベント種別・同じプレフィックス範囲に対して重複する設定を作成できません。"}],"refs":"<a href=\"#integration\" data-go=\"integration\">第6章 6.2 Amazon SNS</a> ／ <a href=\"#d2\" data-go=\"d2\">第12章 12.4 イベント駆動型アーキテクチャ</a>"},{"n":5,"topic":"災害対策","level":3,"body":["基幹システムのDR要件が「<b>RTO 10分以内、RPO 1分以内</b>」と定められました。コストは要件を満たす範囲で可能な限り低く抑える方針です。最も適切なDR戦略はどれですか。"],"options":[{"l":"A","html":"バックアップ＆リストア"},{"l":"B","html":"パイロットライト"},{"l":"C","html":"マルチサイト（アクティブ/アクティブ）"},{"l":"D","html":"ウォームスタンバイ"}],"answer":["D"],"multi":false,"req":"","key":"<b>要件を満たす戦略のうち、最も安価なものを選ぶ</b>のが原則です。ウォームスタンバイは縮小版の環境が常時稼働しているため、切り替えとスケールアウトで数分、非同期レプリケーションでRPOは数秒〜数分となり、要件を満たします。","reasons":[{"l":"A","html":"被災後に環境を構築するためRTOは数時間〜数日となり、要件を満たしません。"},{"l":"B","html":"コンピュート層が停止状態のため、起動とプロビジョニングに数十分かかり、RTO 10分を満たせません。"},{"l":"C","html":"要件は満たしますが、両リージョンで本番環境を常時稼働させるため最もコストが高く、「可能な限り低く」という方針に反します。"}],"refs":"<a href=\"#d2\" data-go=\"d2\">第12章 12.5 高可用性と耐障害性</a> ／ <a href=\"#foundations\" data-go=\"foundations\">第0章 0.3 RTOとRPOの指標</a>"},{"n":6,"topic":"高可用性","level":2,"body":["Amazon RDS for PostgreSQLで、日中に実行される集計レポートのクエリが重く、通常のトランザクション処理まで遅延しています。現在このDBはマルチAZ配置です。アプリケーションの変更は許容されます。適切な対処はどれですか。"],"options":[{"l":"A","html":"マルチAZ配置のスタンバイインスタンスへレポートクエリを向ける"},{"l":"B","html":"リードレプリカを作成し、レポートクエリの接続先をリードレプリカに変更する"},{"l":"C","html":"インスタンスクラスをより大きなものへ変更する"},{"l":"D","html":"毎朝スナップショットから別インスタンスを復元し、そこへレポートクエリを向ける"}],"answer":["B"],"multi":false,"req":"","key":"<b>読み取りのスケールはリードレプリカ</b>、<b>可用性はマルチAZ</b>という役割分担が頻出の対比です。分析系クエリをレプリカへ逃がせば、本番トランザクションへの影響を切り離せます。","reasons":[{"l":"A","html":"マルチAZのスタンバイインスタンスは<b>読み取りにも使用できません</b>（待機専用）。"},{"l":"C","html":"一時的には改善しますが、負荷の性質が異なる処理が同居する構造は変わらず、コストも増え続けます。"},{"l":"D","html":"復元したインスタンスのデータは取得時点のもので、最新のデータを参照できません。運用も煩雑です。"}],"refs":"<a href=\"#database\" data-go=\"database\">第4章 4.1 Amazon RDS</a> ／ <a href=\"#d3\" data-go=\"d3\">第13章 13.3 データベースとパフォーマンス</a>"},{"n":7,"topic":"ステートレス化","level":2,"body":["Auto Scalingグループで運用しているWebアプリケーションで、スケールインが発生するたびに一部の利用者がログアウトされてしまいます。セッション情報は各EC2インスタンスのローカルディスクに保存されています。根本的な解決策はどれですか。"],"options":[{"l":"A","html":"ALBのスティッキーセッションを有効化する"},{"l":"B","html":"セッション情報をAmazon ElastiCache for RedisまたはAmazon DynamoDBへ外部化する"},{"l":"C","html":"セッション情報の保存先をEBSボリュームに変更する"},{"l":"D","html":"Auto Scalingグループの最小台数を引き上げ、スケールインを起こりにくくする"}],"answer":["B"],"multi":false,"req":"","key":"水平スケーリングの前提は<b>ステートレス</b>であることです。セッションを共有ストアへ外出しすれば、どのインスタンスが終了しても利用者の状態は失われません。","reasons":[{"l":"A","html":"スティッキーセッションは同じインスタンスへ誘導するだけで、そのインスタンスが終了すればセッションは失われます。"},{"l":"C","html":"EBSもインスタンスに紐づくため、終了時に同じ問題が起きます（単一AZの制約もあります）。"},{"l":"D","html":"台数を増やしてもスケールインは発生し、コストが増えるだけで根本原因は残ります。"}],"refs":"<a href=\"#d2\" data-go=\"d2\">第12章 12.1 スケーリング戦略</a> ／ <a href=\"#database\" data-go=\"database\">第4章 4.4 Amazon ElastiCache</a>"},{"n":8,"topic":"高可用性","level":2,"body":["3つのアベイラビリティゾーンにまたがるVPCで、プライベートサブネットのEC2インスタンスがNAT Gateway経由で外部APIを呼び出しています。あるAZでNAT Gatewayに障害が発生したところ、<b>すべてのAZ</b>のインスタンスが外部と通信できなくなりました。再発を防ぐ構成はどれですか。"],"options":[{"l":"A","html":"NAT Gatewayをプライベートサブネットへ移動する"},{"l":"B","html":"NAT GatewayをNATインスタンスに置き換え、Auto Scalingグループで管理する"},{"l":"C","html":"インターネットゲートウェイをAZごとに追加する"},{"l":"D","html":"各AZにNAT Gatewayを配置し、各AZのサブネットのルートテーブルを自AZのNAT Gatewayに向ける"}],"answer":["D"],"multi":false,"req":"","key":"NAT Gatewayは<b>AZ単位のサービス</b>です。1台を全AZで共用すると、そのAZの障害が全体に波及します。<b>AZごとに配置し、ルートテーブルも自AZ向きにする</b>のが定石です。","reasons":[{"l":"A","html":"NAT Gatewayはパブリックサブネットに配置する必要があります。プライベートサブネットに置くと外部へ出られません。"},{"l":"B","html":"NATインスタンスは自前でパッチ・スケール・冗長化を管理する必要があり、可用性の観点でマネージドのNAT Gatewayより不利です。"},{"l":"C","html":"インターネットゲートウェイはVPCに1つで、AZの概念を持たず、AWS側で冗長化されています。増設という概念がありません。"}],"refs":"<a href=\"#network\" data-go=\"network\">第3章 3.1 VPCの基礎</a> ／ <a href=\"#d2\" data-go=\"d2\">第12章 12.5 高可用性と耐障害性</a>"},{"n":9,"topic":"高可用性","level":3,"body":["オンラインゲームのマッチングサーバー（TCP/UDPを使用）を2つのリージョンで運用しています。現在はRoute 53のフェイルオーバールーティングで切り替えていますが、<b>DNSキャッシュの影響で切り替えに数分かかる</b>ことが問題視されています。より短時間で切り替える方法はどれですか。"],"options":[{"l":"A","html":"Route 53のレコードのTTLを0秒に設定する"},{"l":"B","html":"AWS Global Acceleratorを導入し、2つのリージョンのエンドポイントを登録する"},{"l":"C","html":"Amazon CloudFrontを前段に配置し、オリジンフェイルオーバーを設定する"},{"l":"D","html":"ALBのクロスゾーン負荷分散を有効化する"}],"answer":["B"],"multi":false,"req":"","key":"Global Acceleratorは<b>固定のAnycast IP</b>を入口とし、ヘルスチェックに基づいてAWSバックボーン内で転送先を切り替えるため、<b>DNSのTTLに依存せず数十秒で</b>フェイルオーバーできます。TCP/UDPにも対応します。","reasons":[{"l":"A","html":"TTLを短くしてもクライアントやリゾルバのキャッシュ挙動に依存し、確実な短縮にはなりません。クエリ料金と負荷も増えます。"},{"l":"C","html":"CloudFrontはHTTP/HTTPSの配信を対象とするサービスで、TCP/UDPのゲームトラフィックには適しません。"},{"l":"D","html":"クロスゾーン負荷分散はAZ間の分散設定であり、リージョン間の切り替えとは無関係です。"}],"refs":"<a href=\"#network\" data-go=\"network\">第3章 3.6 CloudFrontとGlobal Accelerator</a> ／ <a href=\"#d2\" data-go=\"d2\">第12章 12.5 高可用性と耐障害性</a>"},{"n":10,"topic":"イベント駆動","level":2,"body":["Amazon S3のイベント通知で起動されるLambda関数が、下流サービスの一時障害で失敗しました。障害の復旧後に確認すると、<b>その間のイベントが失われていた</b>ことが判明しました。再発を防ぐ設定はどれですか。"],"options":[{"l":"A","html":"Lambda関数に送信先（Lambda Destinations）のonFailure、またはデッドレターキュー（DLQ）を設定する"},{"l":"B","html":"Lambda関数のタイムアウト値を最大の15分に延長する"},{"l":"C","html":"予約済み同時実行数を引き上げる"},{"l":"D","html":"Lambda関数の呼び出しを同期呼び出しに変更する"}],"answer":["A"],"multi":false,"req":"","key":"S3イベント通知は<b>非同期呼び出し</b>です。非同期呼び出しは自動で2回再試行されますが、それでも失敗したイベントは<b>破棄されます</b>。失われないようにするにはDLQまたはLambda Destinations（onFailure）で受け皿を用意します。","reasons":[{"l":"B","html":"失敗の原因は下流サービスの障害であり、実行時間の不足ではありません。"},{"l":"C","html":"同時実行数はスロットリング対策で、失敗イベントの保全とは別問題です。"},{"l":"D","html":"S3イベント通知の呼び出しモデルは非同期で固定されており、利用者が同期呼び出しへ変更することはできません。"}],"refs":"<a href=\"#compute\" data-go=\"compute\">第1章 1.6 AWS Lambda</a> ／ <a href=\"#d2\" data-go=\"d2\">第12章 12.4 イベント駆動型アーキテクチャ</a>"}]},{"id":"exam-set-03","file":"set-03.md","num":"問題セット03","title":"第3分野：高パフォーマンスなアーキテクチャの設計","questions":[{"n":1,"topic":"データベース性能","level":2,"body":["Amazon DynamoDBをバックエンドに使うモバイルアプリで、商品マスタへの同じ読み取りリクエストが大量に発生しています。現在の応答時間は一桁ミリ秒ですが、<b>マイクロ秒台</b>まで短縮したいという要件が出ました。アプリケーションの改修は最小限に抑えたいと考えています。適切な対処はどれですか。"],"options":[{"l":"A","html":"グローバルセカンダリインデックス（GSI）を追加する"},{"l":"B","html":"Amazon ElastiCache for Memcachedを導入し、アプリケーション側にキャッシュ読み書きのロジックを実装する"},{"l":"C","html":"Amazon DynamoDB Accelerator（DAX）クラスターを導入する"},{"l":"D","html":"読み取りを強い整合性（Strongly Consistent Read）に変更する"}],"answer":["C"],"multi":false,"req":"","key":"<b>DynamoDB専用のインメモリキャッシュがDAX</b>です。DynamoDBと互換のAPIを持つため、アプリケーションの改修が最小限で済み、キャッシュヒット時はマイクロ秒台で応答します。","reasons":[{"l":"A","html":"GSIは別のキーで検索するための仕組みで、同一データの読み取りを高速化するものではありません。"},{"l":"B","html":"実現は可能ですが、キャッシュの読み書きと無効化のロジックをアプリ側に実装する必要があり、「改修は最小限」という要件に反します。"},{"l":"D","html":"強い整合性の読み取りは<b>消費キャパシティが2倍</b>になり、レイテンシも改善しません。"}],"refs":"<a href=\"#database\" data-go=\"database\">第4章 4.3 Amazon DynamoDB</a> ／ <a href=\"#d3\" data-go=\"d3\">第13章 13.3 データベースとパフォーマンス</a>"},{"n":2,"topic":"データベース性能","level":2,"body":["トラフィック増加にともない、AWS LambdaからAmazon RDS for MySQLへの接続が急増し、<code>Too many connections</code>エラーが発生するようになりました。クエリ自体は軽量です。適切な対処はどれですか。"],"options":[{"l":"A","html":"Amazon RDS Proxyを導入し、Lambdaの接続先をプロキシのエンドポイントに変更する"},{"l":"B","html":"リードレプリカを追加し、参照クエリを分散する"},{"l":"C","html":"Lambda関数のメモリ割り当てを増やす"},{"l":"D","html":"Lambda関数の予約済み同時実行数を上限まで引き上げる"}],"answer":["A"],"multi":false,"req":"","key":"Lambdaは同時実行のたびに新しい接続を張るため、<b>接続数の枯渇</b>が起こります。RDS Proxyが接続をプールして再利用するため、DB側の接続数を抑えられます（フェイルオーバー時間の短縮という利点もあります）。","reasons":[{"l":"B","html":"レプリカを増やしても、Lambdaが張る接続の総数が減るわけではありません。書き込みは依然としてプライマリに集中します。"},{"l":"C","html":"メモリ増強はCPU性能に比例しますが、接続数の問題とは無関係です。"},{"l":"D","html":"同時実行数を増やすと接続数はさらに増え、問題が悪化します。"}],"refs":"<a href=\"#database\" data-go=\"database\">第4章 4.1 Amazon RDS</a> ／ <a href=\"#d3\" data-go=\"d3\">第13章 13.3 データベースとパフォーマンス</a>"},{"n":3,"topic":"ストレージ性能","level":2,"body":["大量の並列ジョブが、S3バケットの単一プレフィックス配下（<code>s3://bucket/data/</code>）へ毎秒数千件の書き込みを行った結果、<code>503 Slow Down</code>エラーが返るようになりました。適切な対処はどれですか。"],"options":[{"l":"A","html":"バケットのバージョニングを無効化する"},{"l":"B","html":"S3 Transfer Accelerationを有効化する"},{"l":"C","html":"ストレージクラスをS3 Intelligent-Tieringに変更する"},{"l":"D","html":"オブジェクトキーを複数のプレフィックスへ分散させる（日付やハッシュ値をキーの先頭付近に含める）"}],"answer":["D"],"multi":false,"req":"","key":"S3の性能上限は<b>プレフィックス単位</b>（毎秒3,500 PUT／5,500 GET が目安）です。プレフィックスを分散させれば、その分だけ並列度を上げられます。","reasons":[{"l":"A","html":"バージョニングはリクエストレートの制限とは無関係です。"},{"l":"B","html":"Transfer Accelerationは<b>地理的に遠い場所からの転送</b>をエッジ経由で高速化する機能で、プレフィックス単位のスロットリングには効きません。"},{"l":"C","html":"ストレージクラスは保管コストと取り出し特性の話で、リクエストレートの上限は変わりません。"}],"refs":"<a href=\"#storage\" data-go=\"storage\">第2章 2.1 Amazon S3</a> ／ <a href=\"#d3\" data-go=\"d3\">第13章 13.1 ストレージとパフォーマンス</a>"},{"n":4,"topic":"ストレージ性能","level":2,"body":["ゲノム解析のHPCワークロードで、数百台のEC2インスタンスが<b>数百GB/秒</b>のスループットで同一のデータセットへアクセスする必要があります。元データはS3バケットに保管されており、解析結果もS3へ書き戻します。適切なストレージはどれですか。"],"options":[{"l":"A","html":"Amazon EFS（汎用パフォーマンスモード）"},{"l":"B","html":"Amazon FSx for Lustre（S3バケットとリンクして使用）"},{"l":"C","html":"Amazon EBS io2 Block Express"},{"l":"D","html":"各インスタンスからS3 APIで直接読み書きする"}],"answer":["B"],"multi":false,"req":"","key":"<b>HPC・機械学習・数百GB/秒・S3との連携</b>というキーワードはFSx for Lustreです。S3バケットをリンクしてデータを遅延ロードし、結果を書き戻せます。","reasons":[{"l":"A","html":"EFSは汎用の共有ファイルストレージで、HPC向けの数百GB/秒には設計されていません。"},{"l":"C","html":"EBSは<b>単一インスタンスにアタッチする</b>ブロックストレージで、数百台からの同時共有には使えません。"},{"l":"D","html":"オブジェクトAPIでの直接アクセスは、POSIXファイルシステムを前提とする解析ソフトの要件を満たさず、要求スループットにも届きません。"}],"refs":"<a href=\"#storage\" data-go=\"storage\">第2章 2.4 Amazon FSx</a> ／ <a href=\"#d3\" data-go=\"d3\">第13章 13.1 ストレージとパフォーマンス</a>"},{"n":5,"topic":"コンピューティング性能","level":2,"body":["t3.mediumインスタンスで稼働する分析バッチが、実行開始から数十分後に極端に遅くなる事象が繰り返し発生しています。CloudWatchで確認したところ、CPUクレジット残高がゼロになっていました。処理は常時CPUを高使用率で消費します。適切な対処はどれですか。"],"options":[{"l":"A","html":"Auto Scalingグループの最小台数を増やす"},{"l":"B","html":"メモリ最適化インスタンス（R系）へ変更する"},{"l":"C","html":"EBSボリュームをgp2からgp3へ変更する"},{"l":"D","html":"コンピューティング最適化インスタンス（C系）へ変更する"}],"answer":["D"],"multi":false,"req":"","key":"T系はバースト可能な汎用インスタンスで、<b>継続的に高いCPU使用率が必要なワークロードには不向き</b>です。常時CPUを使う処理はC系へ移します（暫定的にはT系のアンリミテッドモードでも回避できますが、追加料金が発生します）。","reasons":[{"l":"A","html":"台数を増やしても1台あたりのCPUクレジット枯渇は起き続け、コストだけが増えます。"},{"l":"B","html":"ボトルネックはCPUでありメモリではありません。"},{"l":"C","html":"ストレージI/Oではなく、CPUクレジットの枯渇が原因です。"}],"refs":"<a href=\"#compute\" data-go=\"compute\">第1章 1.1 Amazon EC2</a> ／ <a href=\"#d3\" data-go=\"d3\">第13章 13.2 コンピューティングとパフォーマンス</a>"},{"n":6,"topic":"ネットワーク性能","level":2,"body":["東京リージョンでホストしているWebアプリケーション（HTTPS）を、欧州と北米の利用者にも高速に提供したいと考えています。コンテンツは画像などの静的アセットと、APIによる動的レスポンスの両方を含みます。オリジンは東京リージョンのまま維持します。適切な構成はどれですか。"],"options":[{"l":"A","html":"AWS Global Acceleratorを導入する"},{"l":"B","html":"Amazon CloudFrontを導入し、静的アセットをキャッシュしつつ、動的コンテンツもAWSバックボーン経由で配信する"},{"l":"C","html":"各リージョンにEC2インスタンスを立て、Route 53のレイテンシーベースルーティングで振り分ける"},{"l":"D","html":"ALBのクロスゾーン負荷分散を有効化する"}],"answer":["B"],"multi":false,"req":"","key":"HTTP/HTTPSで、<b>静的アセットのキャッシュ</b>が効く構成ではCloudFrontが第一候補です。動的コンテンツもエッジからオリジンまでAWSバックボーンを経由するため高速化されます。","reasons":[{"l":"A","html":"Global Acceleratorは<b>キャッシュを行いません</b>。静的アセットのオフロード効果が得られず、この要件ではCloudFrontに劣ります（TCP/UDPや固定IPが要件のときに選びます）。"},{"l":"C","html":"要件は「オリジンは東京のまま」です。マルチリージョン展開はデータ同期を含めて大掛かりで、前提に反します。"},{"l":"D","html":"クロスゾーン負荷分散はAZ間の均等分散の設定で、地理的なレイテンシとは無関係です。"}],"refs":"<a href=\"#network\" data-go=\"network\">第3章 3.6 CloudFrontとGlobal Accelerator</a> ／ <a href=\"#d3\" data-go=\"d3\">第13章 13.4 ネットワークパフォーマンスの最適化</a>"},{"n":7,"topic":"分析性能とコスト","level":2,"body":["S3に日次で蓄積されるCSV形式のアクセスログ（合計数TB）に対し、Amazon Athenaで日付を絞った集計を実行していますが、クエリが遅く課金額も大きくなっています。最も効果的な改善策はどれですか。"],"options":[{"l":"A","html":"データをParquet形式へ変換し、日付でパーティション分割する"},{"l":"B","html":"Amazon Redshiftクラスターを構築し、全データをロードする"},{"l":"C","html":"Athenaのワーカー数（並列度）を引き上げる"},{"l":"D","html":"対象バケットのストレージクラスをS3 Standard-IAへ変更する"}],"answer":["A"],"multi":false,"req":"","key":"Athenaは<b>スキャンしたデータ量</b>で課金されます。列指向フォーマット（Parquet／ORC）への変換と圧縮、そして<b>パーティション分割</b>でスキャン量そのものを減らすのが、速度とコストの両方に効く定石です。","reasons":[{"l":"B","html":"Redshiftは継続的・大規模なBI向けで、日次のアドホック集計には過剰です。クラスターの運用コストも発生します。"},{"l":"C","html":"Athenaはサーバーレスで、利用者が並列度を設定する仕組みはありません。"},{"l":"D","html":"ストレージクラスの変更は保管コストにしか影響せず、スキャン量もクエリ速度も変わりません。"}],"refs":"<a href=\"#analytics\" data-go=\"analytics\">第7章 7.3 Amazon Athena</a> ／ <a href=\"#d4\" data-go=\"d4\">第14章 14.2 ストレージのコスト最適化</a>"},{"n":8,"topic":"データベース性能","level":3,"body":["Amazon DynamoDBのテーブルで、プロビジョニングされたキャパシティには十分な余裕があるにもかかわらず、特定の時間帯に<code>ProvisionedThroughputExceededException</code>が頻発します。調査の結果、書き込みの大半が同一のパーティションキー値（当日の日付）に集中していました。適切な対処はどれですか。"],"options":[{"l":"A","html":"プロビジョニングされた書き込みキャパシティを2倍に増やす"},{"l":"B","html":"パーティションキーの設計を見直し、カーディナリティを高める（日付にランダムなサフィックスを付与するなどして分散させる）"},{"l":"C","html":"読み取りを強い整合性に変更する"},{"l":"D","html":"ローカルセカンダリインデックス（LSI）を追加する"}],"answer":["B"],"multi":false,"req":"","key":"DynamoDBのキャパシティは<b>パーティションごとに分配</b>されます。特定のキーに書き込みが集中する「ホットパーティション」では、テーブル全体に余裕があってもスロットリングします。<b>キー設計の見直し</b>が根本対処です。","reasons":[{"l":"A","html":"全体のキャパシティを増やしても、偏った1つのパーティションに割り当てられる分は限られるため、根本的な解決になりません。"},{"l":"C","html":"整合性モデルは読み取りの設定であり、書き込みの偏りとは無関係です（消費キャパシティが増えるだけです）。"},{"l":"D","html":"LSIは同一パーティションキー内で別のソートキーを使うための仕組みで、書き込みの集中をむしろ助長します。"}],"refs":"<a href=\"#database\" data-go=\"database\">第4章 4.3 Amazon DynamoDB</a> ／ <a href=\"#d3\" data-go=\"d3\">第13章 13.3 データベースとパフォーマンス</a>"},{"n":9,"topic":"検索性能","level":2,"body":["ECサイトの商品検索が、RDS上で<code>LIKE '%キーワード%'</code>による全件走査を行っているため非常に遅く、表記ゆれにも対応できていません。検索語のハイライトや関連度順の並び替えも求められています。適切なサービスはどれですか。"],"options":[{"l":"A","html":"RDSのリードレプリカ"},{"l":"B","html":"Amazon Athena"},{"l":"C","html":"Amazon OpenSearch Service"},{"l":"D","html":"Amazon ElastiCache for Redis"}],"answer":["C"],"multi":false,"req":"","key":"<b>全文検索・あいまい検索・関連度順</b>という要件はOpenSearch Serviceです（ログのリアルタイム分析にも使われます）。","reasons":[{"l":"A","html":"レプリカを追加しても全件走査というクエリの性質は変わらず、表記ゆれにも対応できません。"},{"l":"B","html":"AthenaはS3上のデータへアドホックにSQLを実行するサービスで、対話的な検索機能の基盤には向きません。"},{"l":"D","html":"ElastiCacheはキーに対する高速な読み書きが得意で、全文検索エンジンではありません。"}],"refs":"<a href=\"#analytics\" data-go=\"analytics\">第7章 7.6 Amazon OpenSearch Service</a> ／ <a href=\"#d3\" data-go=\"d3\">第13章 13.3 データベースとパフォーマンス</a>"},{"n":10,"topic":"ネットワーク性能","level":3,"body":["数値流体解析（CFD）のHPCジョブを、MPIで通信する多数のEC2インスタンス上で実行します。ノード間通信のレイテンシが実行時間を左右するため、これを最小化する必要があります。適切な構成はどれですか。"],"options":[{"l":"A","html":"クラスタープレイスメントグループに配置し、Elastic Fabric Adapter（EFA）を利用する"},{"l":"B","html":"スプレッドプレイスメントグループに配置する"},{"l":"C","html":"インスタンスを複数のアベイラビリティゾーンへ分散配置する"},{"l":"D","html":"AWS Global Acceleratorを経由させる"}],"answer":["A"],"multi":false,"req":"","key":"<b>HPC・MPI・ノード間の低レイテンシ</b>は、クラスタープレイスメントグループ（単一AZ内で近接配置）とEFA（OSカーネルを迂回する高速なノード間通信）の組み合わせです。","reasons":[{"l":"B","html":"スプレッドは少数の重要インスタンスを<b>別々のハードウェアへ分散</b>する配置で、可用性のための選択です。レイテンシはむしろ不利になります。"},{"l":"C","html":"AZ分散は可用性を高めますが、AZ間の物理距離のぶんレイテンシが増えます。"},{"l":"D","html":"Global Acceleratorはインターネット経由の利用者アクセスを高速化するサービスで、VPC内のノード間通信には関与しません。"}],"refs":"<a href=\"#compute\" data-go=\"compute\">第1章 1.1 Amazon EC2</a> ／ <a href=\"#d3\" data-go=\"d3\">第13章 13.4 ネットワークパフォーマンスの最適化</a>"}]},{"id":"exam-set-04","file":"set-04.md","num":"問題セット04","title":"第4分野：コストを最適化したアーキテクチャの設計","questions":[{"n":1,"topic":"ストレージのコスト","level":2,"body":["医療系の企業が、診断画像をS3に保存しています。アップロードから30日間は頻繁に参照されますが、その後はほとんど参照されません。ただし監査対応のため、<b>まれに発生する照会には数分以内に取り出せる</b>必要があり、データは7年間保持しなければなりません。最もコスト効率の高い構成はどれですか。"],"options":[{"l":"A","html":"すべてのオブジェクトをS3 Standardのまま保持し、7年後に削除する"},{"l":"B","html":"ライフサイクルポリシーで、30日後にS3 Glacier Deep Archiveへ移行し、7年後に失効させる"},{"l":"C","html":"ライフサイクルポリシーで、30日後にS3 Standard-IA、90日後にS3 Glacier Flexible Retrievalへ移行し、7年後に失効させる"},{"l":"D","html":"ライフサイクルポリシーで、30日後にS3 One Zone-IAへ移行して7年間保持する"}],"answer":["C"],"multi":false,"req":"","key":"取り出し要件が「<b>数分以内</b>」なので、Glacier Flexible Retrievalの迅速取り出し（1〜5分）で満たせます。段階的に安いクラスへ落とすのがライフサイクルの基本形です。","reasons":[{"l":"A","html":"最も高価なクラスのまま7年間保持することになり、コスト最適化になっていません。"},{"l":"B","html":"Deep Archiveの取り出しは標準12時間・大容量48時間で、「数分以内」を満たせません。"},{"l":"D","html":"One Zone-IAは単一AZ保管のため、AZ障害でデータが失われます。監査対応の長期保管には適しません。"}],"refs":"<a href=\"#storage\" data-go=\"storage\">第2章 2.1 Amazon S3</a> ／ <a href=\"#d4\" data-go=\"d4\">第14章 14.2 ストレージのコスト最適化</a>"},{"n":2,"topic":"コンピューティングのコスト","level":2,"body":["動画変換のバッチ処理を、EC2インスタンス群で毎晩実行しています。処理は<b>中断されても最初からやり直せる</b>設計で、完了までの時間には余裕があります。コストを最小化する方法はどれですか。"],"options":[{"l":"A","html":"スポットインスタンスを利用する（中断通知を受けたら処理を退避する）"},{"l":"B","html":"オンデマンドインスタンスで3年間のリザーブドインスタンスを購入する"},{"l":"C","html":"Savings Plansを1年分購入する"},{"l":"D","html":"Dedicated Hostを利用する"}],"answer":["A"],"multi":false,"req":"","key":"「<b>中断されても良い</b>」「時間に余裕がある」はスポットインスタンスの適用条件です。最大90%の割引が得られます。","reasons":[{"l":"B","html":"RIは「常時稼働するワークロード」に対する前払い割引です。夜間のみの実行では稼働率が低く、割引を活かせません。"},{"l":"C","html":"Savings Plansも継続利用へのコミットメントで、中断可能なバッチには過剰です（ベース負荷があるならスポットと併用します）。"},{"l":"D","html":"Dedicated Hostは物理サーバーの専有で、ライセンス持ち込み等が目的です。最も高価な選択肢です。"}],"refs":"<a href=\"#compute\" data-go=\"compute\">第1章 1.1 Amazon EC2</a> ／ <a href=\"#d4\" data-go=\"d4\">第14章 14.3 コンピューティングのコスト最適化</a>"},{"n":3,"topic":"ネットワークのコスト","level":3,"body":["プライベートサブネットの数百台のEC2インスタンスが、S3バケットへ毎日数TBのログを書き込んでいます。請求を確認すると、NAT Gatewayのデータ処理料金が突出していました。この費用を削減する方法はどれですか。"],"options":[{"l":"A","html":"S3用のゲートウェイ型VPCエンドポイントを作成し、ルートテーブルに追加する"},{"l":"B","html":"S3用のインターフェース型VPCエンドポイント（PrivateLink）を作成する"},{"l":"C","html":"NAT Gatewayの台数を1台に集約する"},{"l":"D","html":"EC2インスタンスにパブリックIPを割り当て、IGW経由で直接S3へ書き込む"}],"answer":["A"],"multi":false,"req":"","key":"S3とDynamoDB向けの<b>ゲートウェイ型エンドポイントは追加料金が無料</b>で、通信がNAT Gatewayを経由しなくなるため、処理料金とデータ転送料の両方を削減できます。","reasons":[{"l":"B","html":"インターフェース型はENIの時間料金とデータ処理料金が発生します。S3宛てならゲートウェイ型のほうが安く、要件に合致します。"},{"l":"C","html":"台数を減らすと単一AZ障害の影響範囲が広がるうえ、削減されるのは時間料金だけで、支配的なデータ処理料金は変わりません。"},{"l":"D","html":"プライベートサブネットの前提に反し、セキュリティが大きく後退します。データ転送料も発生します。"}],"refs":"<a href=\"#network\" data-go=\"network\">第3章 3.3 VPCの外部接続</a> ／ <a href=\"#d4\" data-go=\"d4\">第14章 14.2 ストレージのコスト最適化</a>"},{"n":4,"topic":"データベースのコスト","level":2,"body":["社内の申請システムのデータベースが、平日の日中のみ利用され、夜間と週末はまったくアクセスがありません。現在はAurora PostgreSQLのプロビジョニング済みインスタンス（db.r6g.large）が24時間稼働しています。可用性要件は変わりません。最もコスト効率の高い構成はどれですか。"],"options":[{"l":"A","html":"Amazon DynamoDBへ移行する"},{"l":"B","html":"インスタンスサイズをdb.t4g.mediumへ変更する"},{"l":"C","html":"夜間と週末はクラスターを停止する運用をスクリプト化する"},{"l":"D","html":"Aurora Serverless v2に変更し、需要に応じてACUを自動増減させる"}],"answer":["D"],"multi":false,"req":"","key":"「<b>利用が断続的で、無負荷の時間帯が長い</b>」場合はAurora Serverless v2が適します。ACU単位で細かく増減し、アイドル時のコストを抑えられます。","reasons":[{"l":"A","html":"リレーショナルな申請ワークフローをDynamoDBへ移すのはアプリケーションの全面改修を伴い、コスト最適化の手段としては過剰です。"},{"l":"B","html":"サイズを下げても24時間分の課金は続き、ピーク時の性能も落ちます。"},{"l":"C","html":"Auroraクラスターの停止は最長7日で自動的に再開されるため、週末をまたぐ運用では停止し続けられません。スクリプトの保守も必要です。"}],"refs":"<a href=\"#database\" data-go=\"database\">第4章 4.2 Amazon Aurora</a> ／ <a href=\"#d4\" data-go=\"d4\">第14章 14.4 データベースのコスト最適化</a>"},{"n":5,"topic":"コスト管理ツール","level":2,"body":["経理部門から次の2つの要望がありました。<b>2つ選択してください。</b>","1. 今月の利用額が予算の80%に達した時点でメール通知を受け取りたい","2. 過去12か月の推移をサービス別・タグ別に分析し、来月の利用額の予測を見たい","それぞれに適したサービスはどれですか。"],"options":[{"l":"A","html":"AWS Budgets（要望1）"},{"l":"B","html":"AWS Cost and Usage Report（要望1）"},{"l":"C","html":"AWS Cost Explorer（要望2）"},{"l":"D","html":"AWS Trusted Advisor（要望2）"},{"l":"E","html":"AWS Compute Optimizer（要望1）"}],"answer":["A","C"],"multi":true,"req":"","key":"<b>事前に止める＝Budgets（しきい値でアラート）／使った結果を分析する＝Cost Explorer（推移の可視化と予測）</b>という役割分担です。","reasons":[{"l":"B","html":"CURは時間単位・リソース単位の最も詳細な請求データをS3へ出力する仕組みで、それ自体に通知機能はありません（Athena等で分析します）。"},{"l":"D","html":"Trusted Advisorはコスト・性能・セキュリティ・耐障害性・クォータの5観点の点検で、予算超過の通知や推移分析は行いません。"},{"l":"E","html":"Compute Optimizerは機械学習でEC2などの適正サイズを推奨するサービスで、予算アラートの機能はありません。"}],"refs":"<a href=\"#d4\" data-go=\"d4\">第14章 14.1 コスト管理ツールの使い分け</a> ／ <a href=\"#others\" data-go=\"others\">第10章 10.9〜10.11 コスト管理サービス</a>"},{"n":6,"topic":"コンピューティングのコスト","level":2,"body":["スタートアップが、1日あたり数千回だけ実行される画像リサイズ処理をEC2の常時稼働インスタンス（t3.small × 2台）で運用しています。1回の処理は3秒以内に完了します。運用の手間とコストの両方を下げたいと考えています。適切な移行先はどれですか。"],"options":[{"l":"A","html":"AWS Batchへ移行する"},{"l":"B","html":"EC2をスポットインスタンスへ変更する"},{"l":"C","html":"Auto Scalingグループを設定し、最小台数を1に下げる"},{"l":"D","html":"AWS Lambdaへ移行し、S3イベントで起動する"}],"answer":["D"],"multi":false,"req":"","key":"「<b>短時間・イベント駆動・実行回数が限られる</b>」ワークロードでは、アイドル時間に課金されないLambdaが最もコスト効率に優れ、サーバー管理も不要になります。","reasons":[{"l":"A","html":"Batchは15分を超えるような長時間のバッチ計算向けです。3秒の処理には過剰で、裏側のコンピュート費用も発生します。"},{"l":"B","html":"スポットでも常時稼働のアイドル時間には課金され、中断対応の実装も必要になります。"},{"l":"C","html":"1台分のアイドルコストは残り、サーバー管理の手間も減りません。"}],"refs":"<a href=\"#compute\" data-go=\"compute\">第1章 1.6 AWS Lambda</a> ／ <a href=\"#d4\" data-go=\"d4\">第14章 14.3 コンピューティングのコスト最適化</a>"},{"n":7,"topic":"ストレージのコスト","level":3,"body":["データ分析チームが利用するS3バケットには、<b>アクセスパターンがまったく予測できない</b>オブジェクトが数億件あります。運用の手間をかけずにコストを最適化したいと考えています。適切な方法はどれですか。"],"options":[{"l":"A","html":"ライフサイクルポリシーで、30日後に一律でStandard-IAへ移行する"},{"l":"B","html":"S3 Intelligent-Tieringを適用する"},{"l":"C","html":"CloudWatchメトリクスでアクセス頻度を毎月分析し、手動でクラスを変更する"},{"l":"D","html":"すべてをS3 Glacier Instant Retrievalへ移行する"}],"answer":["B"],"multi":false,"req":"","key":"「<b>アクセスパターンが不明・変動する</b>」「<b>運用の手間をかけたくない</b>」はIntelligent-Tieringの適用条件です。監視料金のみで自動的に階層を移動し、取り出し料金はかかりません。","reasons":[{"l":"A","html":"一律移行すると、頻繁にアクセスされるオブジェクトでは取り出し料金がかさみ、かえって高くつく場合があります。"},{"l":"C","html":"数億件を手動で分類する運用は現実的ではなく、「手間をかけずに」という要件に反します。"},{"l":"D","html":"Glacier Instant Retrievalは最低90日の保存期間があり、早期削除では残期間分が課金されます。頻繁にアクセスされるオブジェクトでは取り出し料金も発生します。"}],"refs":"<a href=\"#storage\" data-go=\"storage\">第2章 2.1 Amazon S3</a> ／ <a href=\"#d4\" data-go=\"d4\">第14章 14.2 ストレージのコスト最適化</a>"},{"n":8,"topic":"ネットワークのコスト","level":2,"body":["動画配信サービスで、S3に置いた動画ファイルを世界中の視聴者へ直接配信しています。S3からインターネットへのデータ転送料金が急増しました。視聴される動画には強い偏りがあり、上位1%のファイルが再生回数の大半を占めています。コスト削減に最も効果的な方法はどれですか。"],"options":[{"l":"A","html":"S3 Transfer Accelerationを有効化する"},{"l":"B","html":"S3のストレージクラスをOne Zone-IAへ変更する"},{"l":"C","html":"CloudFrontを前段に配置して配信し、S3バケットはOACで非公開にする"},{"l":"D","html":"リクエスタ支払い（Requester Pays）を有効化する"}],"answer":["C"],"multi":false,"req":"","key":"CloudFrontはエッジでキャッシュするためオリジン（S3）へのリクエストとデータ転送が大幅に減り、<b>CloudFrontからの配信単価はS3からの直接配信より安い</b>のが一般的です。アクセスに偏りがあるほどキャッシュヒット率が上がり効果的です。","reasons":[{"l":"A","html":"Transfer Accelerationは遠距離からの<b>アップロード</b>を高速化する機能で、追加料金が発生します。配信コストは下がりません。"},{"l":"B","html":"ストレージクラスは<b>保管</b>コストの話で、インターネットへのデータ転送料は変わりません。"},{"l":"D","html":"リクエスタ支払いは転送料金を取得側に負担させる仕組みで、一般の視聴者向け配信には適用できません。"}],"refs":"<a href=\"#network\" data-go=\"network\">第3章 3.6 CloudFrontとGlobal Accelerator</a> ／ <a href=\"#d4\" data-go=\"d4\">第14章 14.2 ストレージのコスト最適化</a>"},{"n":9,"topic":"コンピューティングのコスト","level":3,"body":["3年間の運用実績があるWebサービスで、ベースとなる負荷は常時一定、日中のみ負荷が1.5倍になり、月末のバッチ処理では一時的に3倍まで増加します。バッチ処理は中断可能です。最もコスト効率の高い購入方法の組み合わせはどれですか。<b>2つ選択してください。</b>"],"options":[{"l":"A","html":"ベース負荷分にスポットインスタンスを利用する"},{"l":"B","html":"ベース負荷分に Compute Savings Plans（またはリザーブドインスタンス）を適用する"},{"l":"C","html":"すべての負荷をオンデマンドインスタンスでまかなう"},{"l":"D","html":"月末のバッチ処理分にスポットインスタンスを利用する"},{"l":"E","html":"月末のバッチ処理分に3年間のリザーブドインスタンスを購入する"}],"answer":["B","D"],"multi":true,"req":"","key":"<b>ベース負荷はコミットメント割引（Savings Plans／RI）、変動分はオンデマンド、中断可能なバースト分はスポット</b>という重ね方が定石です。","reasons":[{"l":"A","html":"ベース負荷は常時必要な処理です。中断の可能性があるスポットをサービスの土台に使うのは適しません。"},{"l":"C","html":"常時一定の負荷にオンデマンドを使い続けるのは、割引の機会を捨てていることになります。"},{"l":"E","html":"月末のみの一時的な負荷に3年コミットするのは、稼働率が低く割引を活かせません。"}],"refs":"<a href=\"#compute\" data-go=\"compute\">第1章 1.1 Amazon EC2</a> ／ <a href=\"#d4\" data-go=\"d4\">第14章 14.3 コンピューティングのコスト最適化</a>"},{"n":10,"topic":"データベースのコスト","level":2,"body":["IoTプラットフォームがDynamoDBにセンサーデータを保存しています。データは直近90日間のみ照会され、それ以前のデータは年に数回の分析でしか使われませんが、テーブルの容量が増え続けコストを圧迫しています。適切な対処はどれですか。"],"options":[{"l":"A","html":"プロビジョニングされた読み取りキャパシティを引き下げる"},{"l":"B","html":"TTL属性を設定して90日経過した項目を自動削除し、削除前のデータはDynamoDB StreamsやエクスポートでS3へ退避して分析はAthenaで行う"},{"l":"C","html":"テーブルをオンデマンドキャパシティモードへ変更する"},{"l":"D","html":"グローバルセカンダリインデックスを追加し、古いデータを分離する"}],"answer":["B"],"multi":false,"req":"","key":"DynamoDBのストレージ費用は項目数に比例します。<b>TTLで自動削除</b>して容量を抑え、めったに使わない履歴は<b>S3に退避してAthenaで分析</b>するのが定石です。","reasons":[{"l":"A","html":"キャパシティの調整はスループット課金の話で、増え続けるストレージ費用には効きません。"},{"l":"C","html":"課金方式が変わるだけで、保存しているデータ量そのものは減りません。"},{"l":"D","html":"GSIはインデックス分のストレージとキャパシティを<b>追加で消費</b>するため、コストはむしろ増えます。"}],"refs":"<a href=\"#database\" data-go=\"database\">第4章 4.3 Amazon DynamoDB</a> ／ <a href=\"#d4\" data-go=\"d4\">第14章 14.4 データベースのコスト最適化</a>"}]},{"id":"exam-set-05","file":"set-05.md","num":"問題セット05","title":"総合（本番の分野比率に合わせた混合セット）","questions":[{"n":1,"topic":"マルチアカウント統制","level":2,"body":["企業が新規事業ごとにAWSアカウントを発行する方針を決めました。各アカウントには、ログの集約、ガードレールの適用、標準的なネットワーク構成が最初から備わっている必要があります。アカウント発行のたびに手作業で設定する運用は避けたいと考えています。適切なサービスはどれですか。"],"options":[{"l":"A","html":"AWS Control Towerでランディングゾーンを構築し、Account Factoryでアカウントを発行する"},{"l":"B","html":"AWS Organizationsを有効化し、アカウント作成後にSCPを手動で適用する"},{"l":"C","html":"AWS CloudFormation StackSetsのみで各アカウントへリソースを展開する"},{"l":"D","html":"AWS Service Catalogで承認済みのアカウント設定を配布する"}],"answer":["A"],"multi":false,"req":"","key":"「<b>マルチアカウント基盤をベストプラクティス構成で自動的に立ち上げる</b>」のがControl Towerです。Organizations、SCP、ログ集約、アカウント発行（Account Factory）を一括で用意します。","reasons":[{"l":"B","html":"Organizations単体では請求統合とSCPの適用まで。ログ集約やネットワークの標準化、発行の自動化は自前で組む必要があります。"},{"l":"C","html":"StackSetsはリソースの展開手段であり、アカウントそのものの発行やガードレールの枠組みは提供しません（Control Towerの内部でも使われます）。"},{"l":"D","html":"Service Catalogは利用者に承認済みの構成テンプレートを配布する仕組みで、アカウント基盤の構築とは目的が異なります。"}],"refs":"<a href=\"#management\" data-go=\"management\">第8章 8.5 AWS Organizations</a> ／ <a href=\"#d1\" data-go=\"d1\">第11章 11.1 アクセス管理</a>"},{"n":2,"topic":"オンプレミス接続","level":3,"body":["本社データセンターとAWS間を、<b>帯域が安定した専用線</b>で接続しています。監査部門から「経路上のデータはすべて暗号化されていること」という指摘を受けました。既存の接続方式は維持したまま、最小の変更で対応する方法はどれですか。"],"options":[{"l":"A","html":"転送するデータをアプリケーション側でS3へアップロードしてから処理する"},{"l":"B","html":"Direct Connectを解約し、Site-to-Site VPNのみに切り替える"},{"l":"C","html":"Direct Connect Gatewayを追加する"},{"l":"D","html":"Direct Connectの上にIPsec VPN（またはMACsec）を構成し、通信を暗号化する"}],"answer":["D"],"multi":false,"req":"","key":"<b>Direct Connectは既定では暗号化されません</b>。専用線の帯域特性を保ったまま暗号化要件を満たすには、その上にIPsec VPNを重ねるか、対応回線でMACsecを使います。","reasons":[{"l":"A","html":"経路の暗号化要件に対する回答になっておらず、アプリケーションの作り替えも必要になります。"},{"l":"B","html":"VPNはインターネット経由のため、専用線の「安定した帯域・低レイテンシ」という前提を失います。"},{"l":"C","html":"DX Gatewayは複数リージョン・複数VPCへ接続を広げる仕組みで、暗号化とは無関係です。"}],"refs":"<a href=\"#network\" data-go=\"network\">第3章 3.3 VPCの外部接続</a> ／ <a href=\"#d1\" data-go=\"d1\">第11章 11.2 データ保護</a>"},{"n":3,"topic":"暗号鍵の管理","level":3,"body":["金融機関のシステムで、規制により「<b>暗号鍵は専有のハードウェアで管理し、FIPS 140-2 レベル3の検証を受けていること</b>」「鍵素材はクラウド事業者にも一切触らせないこと」が求められています。適切なサービスはどれですか。"],"options":[{"l":"A","html":"AWS Secrets Manager"},{"l":"B","html":"AWS KMSのカスタマー管理キー（自動ローテーション有効）"},{"l":"C","html":"AWS KMSのAWSマネージドキー"},{"l":"D","html":"AWS CloudHSM"}],"answer":["D"],"multi":false,"req":"","key":"<b>専有HSM・FIPS 140-2 レベル3・鍵素材の完全な自己管理</b>という要件はCloudHSMです（KMSのカスタムキーストアと組み合わせることもできます）。","reasons":[{"l":"A","html":"Secrets Managerは資格情報の保管とローテーションのサービスで、暗号鍵のハードウェア要件とは関係ありません。"},{"l":"B","html":"KMSはマネージドな共有HSM基盤で、専有ハードウェアの要件を満たしません。"},{"l":"C","html":"AWSマネージドキーはポリシーの変更もできず、要件から最も遠い選択肢です。"}],"refs":"<a href=\"#security\" data-go=\"security\">第5章 5.8 AWS KMS</a> ／ <a href=\"#d1\" data-go=\"d1\">第11章 11.2 データ保護</a>"},{"n":4,"topic":"API設計","level":2,"body":["社内向けのモノリシックなアプリケーションから、参照系の機能だけを切り出してAPIとして外部パートナーへ公開することになりました。パートナーごとに<b>呼び出し回数の上限</b>を設け、超過分は遮断する必要があります。バックエンドはLambda関数で実装します。適切な構成はどれですか。"],"options":[{"l":"A","html":"Lambda関数URLを発行し、関数内で呼び出し回数をカウントする"},{"l":"B","html":"Application Load BalancerのターゲットにLambdaを登録し、WAFのレートベースルールで制限する"},{"l":"C","html":"Amazon API Gatewayで公開し、APIキーと使用量プランでパートナーごとの上限を設定する"},{"l":"D","html":"CloudFrontを前段に置き、キャッシュのTTLを長くする"}],"answer":["C"],"multi":false,"req":"","key":"<b>利用者ごとの流量制御（APIキー＋使用量プラン）</b>はAPI Gatewayの標準機能です。スロットリングでバックエンドも保護できます。","reasons":[{"l":"A","html":"カウント処理を自前で実装・保守することになり、超過時の遮断やプラン管理も作り込みが必要です。"},{"l":"B","html":"WAFのレートベースルールは主にIP単位の制限で、パートナー単位の契約上限を管理する仕組みとしては粗すぎます。"},{"l":"D","html":"キャッシュは負荷軽減には効きますが、契約上の呼び出し回数の上限管理にはなりません。"}],"refs":"<a href=\"#others\" data-go=\"others\">第10章 10.1 Amazon API Gateway</a> ／ <a href=\"#d2\" data-go=\"d2\">第12章 12.2 疎結合アーキテクチャ</a>"},{"n":5,"topic":"コンテナ移行","level":2,"body":["オンプレミスで稼働するDockerアプリケーションをAWSへ移行します。開発チームにKubernetesの運用経験はなく、<b>EC2インスタンスの管理も避けたい</b>と考えています。既存のDockerfileはそのまま使う方針です。適切な構成はどれですか。"],"options":[{"l":"A","html":"Amazon EKS on Amazon EC2（マネージドノードグループ）"},{"l":"B","html":"Amazon ECS on AWS Fargate"},{"l":"C","html":"Amazon EC2上にDockerを導入して直接実行する"},{"l":"D","html":"AWS Lambdaのコンテナイメージサポートを利用する"}],"answer":["B"],"multi":false,"req":"","key":"<b>Kubernetesの記述がない＋サーバー管理をしたくない</b>＝ECS on Fargateです。AWSサービスとの統合が容易で、運用負荷が最も低くなります。","reasons":[{"l":"A","html":"Kubernetesの学習・運用コストが発生し、EC2ノードの管理も残ります。要件と逆方向です。"},{"l":"C","html":"OSのパッチ適用、スケーリング、障害対応をすべて自前で担うことになります。"},{"l":"D","html":"Lambdaは15分の実行時間制限とイベント駆動の実行モデルが前提です。常時稼働するWebアプリケーションの移行先としては制約が大きすぎます。"}],"refs":"<a href=\"#container\" data-go=\"container\">第9章 9.3 AWS Fargate</a> ／ <a href=\"#d2\" data-go=\"d2\">第12章 12.3 サーバーレステクノロジーの活用</a>"},{"n":6,"topic":"高可用性","level":3,"body":["単一AZのEC2インスタンス1台とRDSシングルAZ構成で動いているアプリケーションを、<b>AZ障害が起きてもサービスを継続できる</b>構成に変更します。実施すべき対策はどれですか。<b>2つ選択してください。</b>"],"options":[{"l":"A","html":"EC2のインスタンスタイプを1つ大きいサイズへ変更する"},{"l":"B","html":"RDSのリードレプリカを同一AZに1台追加する"},{"l":"C","html":"EC2をAuto Scalingグループに入れ、複数AZのサブネットにまたがってALB配下で最低2台稼働させる"},{"l":"D","html":"EBSのスナップショットを1時間おきに取得する"},{"l":"E","html":"RDSをマルチAZ配置に変更する"}],"answer":["C","E"],"multi":true,"req":"","key":"AZ障害への耐性は「<b>複数AZに冗長化する</b>」ことでしか得られません。アプリ層はASG＋ELB＋マルチAZ、DB層はマルチAZ配置が定型です。","reasons":[{"l":"A","html":"スケールアップは処理能力の話で、AZ障害時には同じように停止します。"},{"l":"B","html":"同一AZにレプリカを置いても、そのAZが落ちれば同時に失われます（別AZへ置けば可用性にも寄与しますが、自動フェイルオーバーはマルチAZ配置の役割です）。"},{"l":"D","html":"スナップショットは復旧の材料であり、障害時にサービスを継続させるものではありません（RPOの改善にとどまります）。"}],"refs":"<a href=\"#d2\" data-go=\"d2\">第12章 12.5 高可用性と耐障害性</a> ／ <a href=\"#foundations\" data-go=\"foundations\">第0章 0.2 可用性と耐久性</a>"},{"n":7,"topic":"データ取り込み","level":2,"body":["数万台のIoTデバイスから送られるテレメトリを、<b>追加のコードを書かずに</b>S3へ集約し、Parquet形式に変換して保存したいと考えています。取り込みは数分程度の遅延が許容されます。運用負荷を最小にする構成はどれですか。"],"options":[{"l":"A","html":"Kinesis Data Streamsで受け、独自のコンシューマーアプリケーションでS3へ書き出す"},{"l":"B","html":"Amazon Data Firehose（旧 Kinesis Data Firehose）でS3へ配信し、形式変換を有効にする"},{"l":"C","html":"Amazon SQSで受け、Lambdaで変換してS3へ書き出す"},{"l":"D","html":"Amazon EMRクラスターを常時稼働させ、デバイスから直接書き込ませる"}],"answer":["B"],"multi":false,"req":"","key":"「<b>S3などへ配送するだけ</b>」「<b>コード不要・完全マネージド</b>」「数分の遅延が許容」はFirehoseの適用条件です。Parquetへの形式変換も組み込み機能で行えます。","reasons":[{"l":"A","html":"Data Streamsはコンシューマーを自分で実装・運用する前提で、順序保証や再処理が必要な場合に選びます。今回は要件に含まれていません。"},{"l":"C","html":"実装と運用が必要になり、「追加のコードを書かずに」という要件に反します。"},{"l":"D","html":"常時稼働のEMRはコストが高く、取り込みの入口としても適しません。"}],"refs":"<a href=\"#analytics\" data-go=\"analytics\">第7章 7.1 Amazon Kinesis</a> ／ <a href=\"#d3\" data-go=\"d3\">第13章 13.1 ストレージとパフォーマンス</a>"},{"n":8,"topic":"データ変換と分析","level":2,"body":["S3に蓄積した生ログに対し、<b>スキーマを自動的に推論してカタログ化</b>し、ETL処理を行ったうえで、アナリストがSQLでアドホックに分析できるようにしたいと考えています。サーバーの管理は避けたい方針です。適切な組み合わせはどれですか。"],"options":[{"l":"A","html":"AWS Glue（クローラーとETLジョブ）＋ Amazon Athena"},{"l":"B","html":"Amazon EMR（Spark）＋ Amazon Redshift"},{"l":"C","html":"AWS Lambda（変換）＋ Amazon RDS"},{"l":"D","html":"Amazon Kinesis Data Streams ＋ Amazon QuickSight"}],"answer":["A"],"multi":false,"req":"","key":"<b>スキーマ推論とカタログ化＝Glueクローラー／サーバーレスETL＝Glueジョブ／S3への直接SQL＝Athena</b>。いずれもサーバー管理が不要です。","reasons":[{"l":"B","html":"EMRはクラスターの構成管理が必要で、Redshiftも常時稼働のクラスター運用を伴います。「サーバー管理を避けたい」に反します。"},{"l":"C","html":"Lambdaでの大規模ETLは実行時間の制約があり、RDSはアドホックな大規模分析の基盤には適しません。"},{"l":"D","html":"Data Streamsはリアルタイム取り込みの仕組みで、蓄積済みデータのカタログ化・変換は行いません。QuickSightは可視化であり、データを取得する層が別途必要です。"}],"refs":"<a href=\"#analytics\" data-go=\"analytics\">第7章 7.2 AWS Glue</a> ／ <a href=\"#analytics\" data-go=\"analytics\">第7章 7.3 Amazon Athena</a>"},{"n":9,"topic":"ロードバランサーの選択","level":2,"body":["サードパーティ製の仮想ファイアウォールアプライアンスを導入し、VPCへ出入りするトラフィックをすべて検査したうえで転送する構成を作ります。アプライアンスは複数台で冗長化し、スケールさせる必要があります。適切なサービスはどれですか。"],"options":[{"l":"A","html":"Network Load Balancer"},{"l":"B","html":"Application Load Balancer"},{"l":"C","html":"Gateway Load Balancer"},{"l":"D","html":"Amazon Route 53の加重ルーティング"}],"answer":["C"],"multi":false,"req":"","key":"<b>サードパーティの仮想アプライアンス（ファイアウォール、IDS/IPS）を透過的に挟み込み、冗長化・スケールさせる</b>のがGateway Load Balancerの役割です（GENEVEプロトコルでカプセル化します）。","reasons":[{"l":"A","html":"NLBはL4の負荷分散で、アプライアンスへの透過的な引き込み（ミラーではなくインライン挿入）の仕組みは持ちません。"},{"l":"B","html":"ALBはL7のHTTP/HTTPS向けで、すべてのトラフィックを透過的に検査する用途には使えません。"},{"l":"D","html":"Route 53はDNSレベルの振り分けで、パケットの検査経路を構成するものではありません。"}],"refs":"<a href=\"#network\" data-go=\"network\">第3章 3.5 負荷分散（ELB）</a> ／ <a href=\"#cmp\" data-go=\"cmp\">付録A ネットワーク</a>"},{"n":10,"topic":"ストレージのコスト","level":2,"body":["数百台のEC2インスタンスで、汎用SSD（gp2）のEBSボリュームを使用しています。現在のIOPS使用状況を調べたところ、多くのボリュームで割り当てIOPSを持て余している一方、一部のボリュームではIOPS不足のためにサイズだけを大きくして対応していました。コストと性能の両面で最も適切な対処はどれですか。"],"options":[{"l":"A","html":"gp3へ変更し、必要なIOPSとスループットを容量とは独立に設定する"},{"l":"B","html":"すべてのボリュームをio2 Block Expressへ変更する"},{"l":"C","html":"IOPS不足のボリュームだけをさらに大きなサイズへ拡張する"},{"l":"D","html":"スループット最適化HDD（st1）へ変更する"}],"answer":["A"],"multi":false,"req":"","key":"gp3は<b>IOPSとスループットを容量から切り離して設定</b>できます。容量を増やしてIOPSを稼ぐ必要がなくなり、gp2より単価も安くなります。","reasons":[{"l":"B","html":"io2 Block Expressは最高水準の性能を要するDB向けで、単価が高くコスト最適化に反します。"},{"l":"C","html":"容量課金が増え続けるうえ、余っているボリュームの無駄は解消されません。"},{"l":"D","html":"st1はシーケンシャルなスループット向けのHDDで、ブートボリュームにも使えず、ランダムIOPSを要する用途には不適です。"}],"refs":"<a href=\"#storage\" data-go=\"storage\">第2章 2.2 Amazon EBS</a> ／ <a href=\"#d4\" data-go=\"d4\">第14章 14.2 ストレージのコスト最適化</a>"}]},{"id":"exam-set-06","file":"set-06.md","num":"問題セット06","title":"複合問題（分野をまたぐ設計判断）","questions":[{"n":1,"topic":"セキュリティ × コスト","level":3,"body":["医療情報を含む監査ログをS3に保管します。要件は次の3つです。(1) 保存データは<b>キーの利用履歴を追跡できる方式</b>で暗号化する、(2) 法定保存期間は7年で、<b>照会は年に1回程度、取り出しに数時間かかっても構わない</b>、(3) 7年間の総コストを最小化する。最も適切な構成はどれですか。"],"options":[{"l":"A","html":"SSE-KMSで暗号化し、S3 Standardのまま7年間保管する"},{"l":"B","html":"SSE-S3で暗号化し、ライフサイクルポリシーで30日後にS3 Glacier Deep Archiveへ移行する"},{"l":"C","html":"SSE-KMS（S3バケットキー有効）で暗号化し、ライフサイクルポリシーで30日後にS3 Glacier Deep Archiveへ移行して7年後に失効させる"},{"l":"D","html":"SSE-KMS（S3バケットキー有効）で暗号化し、ライフサイクルポリシーで30日後にS3 One Zone-IAへ移行する"}],"answer":["C"],"multi":false,"req":"①キー利用履歴の追跡＝<b>SSE-KMS</b>（第1分野）／②取り出しは数時間でよい＝<b>Deep Archiveが許容できる</b>（第3分野）／③7年の総コスト最小（第4分野）","key":"3つすべてを満たす選択肢は1つだけです。SSE-KMSで監査要件を満たしつつ、<b>S3バケットキー</b>でKMSリクエスト料金を抑え、取り出し時間の許容度を使ってDeep Archiveまで落とします。","reasons":[{"l":"A","html":"要件(1)は満たしますが、最も高いクラスで7年間保管するため要件(3)に反します。"},{"l":"B","html":"SSE-S3はCloudTrailにキーの利用が記録されず、要件(1)を満たしません。コストだけを見て暗号化方式の要件を落とした典型例です。"},{"l":"D","html":"One Zone-IAは単一AZ保管でAZ障害時にデータが失われ、法定保存の要件に耐えません。コストもDeep Archiveより高くなります。"}],"refs":"<a href=\"#storage\" data-go=\"storage\">第2章 2.1 Amazon S3</a> ／ <a href=\"#security\" data-go=\"security\">第5章 5.8 AWS KMS</a> ／ <a href=\"#d4\" data-go=\"d4\">第14章 14.2 ストレージのコスト最適化</a>"},{"n":2,"topic":"可用性 × コスト","level":3,"body":["基幹システムのDR要件が「<b>RPO 5分以内、RTO 30分以内</b>」に決まりました。現在は東京リージョンのAurora MySQLで稼働しています。コストは要件を満たす範囲で最小にする方針です。適切な構成はどれですか。"],"options":[{"l":"A","html":"東京リージョン内でAuroraクラスターを3つのAZに拡張し、リードレプリカを2台追加する"},{"l":"B","html":"大阪リージョンに本番同等のAuroraクラスターとアプリ層を常時稼働させ、Route 53で両系へ振り分ける"},{"l":"C","html":"Auroraの自動バックアップを大阪リージョンへコピーし、被災時にCloudFormationで環境一式を構築して復元する"},{"l":"D","html":"Auroraグローバルデータベースで大阪リージョンにセカンダリクラスターを構成し、アプリ層はAMIとIaCテンプレートを用意して被災時に起動する"}],"answer":["D"],"multi":false,"req":"①RPO 5分以内＝<b>継続的なレプリケーションが必須</b>（第2分野）／②RTO 30分以内＝<b>DB以外は被災後の起動で間に合う</b>（第2分野）／③コスト最小（第4分野）","key":"RPOの要件がデータ層の常時レプリケーションを要求し、RTO 30分という緩さがアプリ層の事前起動を不要にします。この組み合わせが<b>パイロットライト</b>で、Auroraグローバルデータベース（通常1秒未満のレプリケーション）がそれを実現します。","reasons":[{"l":"A","html":"マルチAZとリードレプリカは<b>同一リージョン内</b>の可用性・性能対策です。リージョン障害に対するDRにはなりません。"},{"l":"B","html":"要件は満たしますが、本番環境を二重に常時稼働させるため最も高コストで、方針③に反します。"},{"l":"C","html":"バックアップからの復元はRPOがバックアップ間隔に縛られ、構築・復元にも時間がかかるため①②の双方を満たせません。"}],"refs":"<a href=\"#d2\" data-go=\"d2\">第12章 12.5 高可用性と耐障害性</a> ／ <a href=\"#database\" data-go=\"database\">第4章 4.2 Amazon Aurora</a> ／ <a href=\"#foundations\" data-go=\"foundations\">第0章 0.3 RTOとRPOの指標</a>"},{"n":3,"topic":"パフォーマンス × コスト","level":3,"body":["ゲームのランキング機能をDynamoDBで実装しています。トラフィックは<b>毎日ほぼ同じ形で推移し、予測可能</b>です。要件は (1) 読み取りレイテンシをマイクロ秒台にする、(2) 同じ上位100件が繰り返し読まれる、(3) キャパシティ料金を最小化する、の3つです。適切な構成はどれですか。"],"options":[{"l":"A","html":"オンデマンドキャパシティモードに変更し、DAXを前段に置く"},{"l":"B","html":"プロビジョニング済みキャパシティ＋Auto Scalingを使い、DynamoDB Accelerator（DAX）を前段に置く"},{"l":"C","html":"プロビジョニング済みキャパシティ＋Auto Scalingを使い、読み取りを強い整合性に変更する"},{"l":"D","html":"グローバルテーブルを有効化し、最寄りリージョンから読み取る"}],"answer":["B"],"multi":false,"req":"①マイクロ秒＝<b>DAX</b>（第3分野）／②同一データの繰り返し読み取り＝キャッシュが効く（第3分野）／③負荷が予測可能＝<b>プロビジョニング済みが最安</b>（第4分野）","key":"レイテンシ要件はDAXが、コスト要件はプロビジョニング済み＋Auto Scalingが満たします。<b>性能の手段とコストの手段は別々に選ぶ</b>のがこの種の設問の解き方です。","reasons":[{"l":"A","html":"オンデマンドは負荷が読めない場合に適し、予測可能な負荷ではプロビジョニング済みより割高になります（要件③に反する）。"},{"l":"C","html":"強い整合性は消費キャパシティが2倍になり、レイテンシも改善しません。①③の両方に反します。"},{"l":"D","html":"グローバルテーブルは地理的な分散とマルチリージョンの可用性のための機能で、マイクロ秒のレイテンシ要件には応えず、コストも増えます。"}],"refs":"<a href=\"#database\" data-go=\"database\">第4章 4.3 Amazon DynamoDB</a> ／ <a href=\"#d3\" data-go=\"d3\">第13章 13.3 データベースとパフォーマンス</a> ／ <a href=\"#d4\" data-go=\"d4\">第14章 14.4 データベースのコスト最適化</a>"},{"n":4,"topic":"セキュリティ × 弾力性","level":3,"body":["決済処理をSQSキュー経由の非同期処理に変更します。要件は (1) メッセージ本文に含まれるカード情報を<b>保存時に暗号化し、キーへのアクセスを制御する</b>、(2) 下流の障害で処理に失敗したメッセージを<b>失わずに隔離する</b>、(3) 処理は最長10分かかることがあり、<b>二重決済は許されない</b>、の3つです。適切な構成はどれですか。"],"options":[{"l":"A","html":"FIFOキューをSSE-KMSで暗号化し、可視性タイムアウトを30秒のままにする"},{"l":"B","html":"SSE-SQS（SQS管理キー）のキューを使い、可視性タイムアウトを既定の30秒のままにし、失敗時はアプリケーションから再送する"},{"l":"C","html":"SSE-KMS（カスタマー管理キー）を有効にしたキューを使い、デッドレターキューを設定し、可視性タイムアウトを処理時間より長く設定したうえで処理を冪等に実装する"},{"l":"D","html":"メッセージ本文をアプリケーション側で暗号化し、デッドレターキューの代わりにCloudWatchアラームで失敗を検知する"}],"answer":["C"],"multi":false,"req":"①キー制御が必要＝<b>SSE-KMS（カスタマー管理キー）</b>（第1分野）／②失敗メッセージの保全＝<b>DLQ</b>（第2分野）／③処理10分・二重決済不可＝<b>可視性タイムアウトの延長＋冪等性</b>（第2分野）","key":"3つの要件がそれぞれ別の機能に対応します。<b>要件ごとに担当する機能を割り当てられるか</b>が問われています。","reasons":[{"l":"A","html":"FIFOは順序と重複排除を提供しますが、<b>重複排除の対象は5分以内の送信</b>であり、処理中の可視性タイムアウト切れによる再配信は防げません（③未達）。DLQもなく②も満たしません。"},{"l":"B","html":"SSE-SQSではキーのアクセス制御ができず①を満たしません。可視性タイムアウト30秒のままでは10分の処理中に再配信され、③にも反します。"},{"l":"D","html":"独自の暗号化実装は鍵管理の負担が大きく、アラームは通知であって<b>メッセージの保全にはならない</b>ため②を満たしません。"}],"refs":"<a href=\"#integration\" data-go=\"integration\">第6章 6.1 Amazon SQS</a> ／ <a href=\"#security\" data-go=\"security\">第5章 5.8 AWS KMS</a> ／ <a href=\"#d2\" data-go=\"d2\">第12章 12.4 イベント駆動型アーキテクチャ</a>"},{"n":5,"topic":"セキュリティ × パフォーマンス","level":3,"body":["有料会員向けの動画をS3から配信します。要件は (1) 世界中の会員に低遅延で配信する、(2) <b>契約期間中の会員だけ</b>が視聴でき、URLを共有されても第三者は視聴できない、(3) S3バケットは<b>インターネットから直接アクセスできない</b>、の3つです。適切な構成はどれですか。"],"options":[{"l":"A","html":"CloudFrontを配置し、OACでS3へのアクセスをCloudFrontからのみに限定し、視聴者には有効期限付きの署名付きCookieを発行する"},{"l":"B","html":"CloudFrontを配置し、S3バケットをパブリック読み取りにして、CloudFrontの地理的制限で国を限定する"},{"l":"C","html":"S3の静的ウェブサイトホスティングを有効にし、事前署名URLを都度発行する"},{"l":"D","html":"CloudFrontを配置し、OACでS3を非公開にしたうえで、WAFのレートベースルールで過剰なアクセスを遮断する"}],"answer":["A"],"multi":false,"req":"①世界中へ低遅延＝<b>CloudFront</b>（第3分野）／②視聴者の限定＝<b>署名付きURL／Cookie</b>（第1分野）／③オリジンの非公開＝<b>OAC</b>（第1分野）","key":"<b>OACは「CloudFrontだけがS3を読める」ための仕組み、署名付きURL／Cookieは「正当な視聴者だけが配信を受けられる」ための仕組み</b>で、役割が異なります。複数ファイルからなる動画配信ではCookieが適します。","reasons":[{"l":"B","html":"バケットをパブリックにすると③に反します。地理的制限は国単位のフィルタであり、会員かどうかの判定にはなりません（②未達）。"},{"l":"C","html":"静的ウェブサイトホスティングはCDNを経由しないため①を満たさず、パブリックアクセスの設定も③に反します。"},{"l":"D","html":"①③は満たしますが、WAFのレート制限は流量の制御であって会員の識別ではないため②を満たしません。"}],"refs":"<a href=\"#network\" data-go=\"network\">第3章 3.6 CloudFrontとGlobal Accelerator</a> ／ <a href=\"#storage\" data-go=\"storage\">第2章 2.1 Amazon S3</a> ／ <a href=\"#d1\" data-go=\"d1\">第11章 11.2 データ保護</a>"},{"n":6,"topic":"弾力性 × パフォーマンス","level":3,"body":["ALBとAuto Scalingグループで動くWebアプリケーションで、次の2つの問題が同時に起きています。(1) スケールインのたびに利用者がログアウトされる、(2) ピーク時にRDSのCPU使用率が100%に張り付き、参照系のクエリが詰まる。<b>それぞれに対する適切な対処を2つ選択してください。</b>"],"options":[{"l":"A","html":"セッション情報をAmazon ElastiCache for RedisまたはDynamoDBへ外部化する"},{"l":"B","html":"RDSをマルチAZ配置に変更し、スタンバイへ参照系クエリを向ける"},{"l":"C","html":"ALBでスティッキーセッションを有効にし、スケールイン保護をすべてのインスタンスに設定する"},{"l":"D","html":"RDSにリードレプリカを追加し、参照系クエリの接続先をレプリカへ向ける"},{"l":"E","html":"Auto Scalingグループの最小台数をピーク時の台数に固定する"}],"answer":["A","D"],"multi":true,"req":"①スケールインで状態が消える＝<b>ステートレス化</b>（第2分野）／②参照系でDBが詰まる＝<b>読み取りのスケール</b>（第3分野）","key":"症状が2つあるときは<b>それぞれ別の層の問題</b>として切り分けます。状態はアプリ層の外へ、読み取り負荷はレプリカへ、が定型です。","reasons":[{"l":"B","html":"マルチAZ配置のスタンバイは<b>読み取りにも使えません</b>。可用性の対策であり、②の解決にはなりません。"},{"l":"C","html":"スティッキーセッションは同じインスタンスへ誘導するだけで、そのインスタンスが終了すればセッションは失われます。スケールイン保護を常時掛けるのは弾力性そのものを捨てる対処です。"},{"l":"E","html":"ピーク台数に固定すると常時コストが増えるうえ、①の原因（ローカルにセッションを持つ設計）は残ります。"}],"refs":"<a href=\"#d2\" data-go=\"d2\">第12章 12.1 スケーリング戦略</a> ／ <a href=\"#database\" data-go=\"database\">第4章 4.1 Amazon RDS</a> ／ <a href=\"#d3\" data-go=\"d3\">第13章 13.3 データベースとパフォーマンス</a>"},{"n":7,"topic":"コスト × 運用","level":2,"body":["開発・検証用のAWSアカウントで請求が想定を超えました。調査の結果、(1) 開発用EC2が夜間と週末も稼働している、(2) gp2ボリュームが大量にあり、IOPSを持て余している、(3) 使われていないElastic IPが数十個ある、ことが分かりました。<b>すぐに効果が出る対処を2つ選択してください。</b>"],"options":[{"l":"A","html":"EC2インスタンスをより小さいインスタンスタイプへ変更する"},{"l":"B","html":"スケジュールされたスケーリング（またはInstance Scheduler）で、平日夜間と週末はインスタンスを停止する"},{"l":"C","html":"すべてのEC2に3年間のリザーブドインスタンスを購入する"},{"l":"D","html":"アカウントにコスト配分タグを設定する"},{"l":"E","html":"gp2ボリュームをgp3へ変更し、必要なIOPSとスループットを個別に指定する"}],"answer":["B","E"],"multi":true,"req":"①稼働時間の無駄＝<b>止める</b>（第4分野）／②過剰なプロビジョニング＝<b>適正化する</b>（第4分野・第3分野）／③「すぐに効果が出る」＝実施が容易で即座に請求に反映されるもの","key":"コスト削減の基本は「<b>止める・落とす・コミットする</b>」の3手。開発環境では<b>止める</b>が最も効果的で、gp2→gp3は性能を落とさずに単価が下がります。","reasons":[{"l":"A","html":"性能要件を確認せずサイズを下げると開発効率を損ないます。Compute Optimizerの推奨を確認してから行う手順です。なお未使用のElastic IPは、アタッチされていない状態で課金されるため削除が必要です。"},{"l":"C","html":"開発環境は停止・廃止の可能性が高く、3年コミットは無駄になるリスクが大きい選択です。"},{"l":"D","html":"タグは可視化と配賦のための準備で、それ自体は請求額を下げません（次の打ち手を決めるためには有用です）。"}],"refs":"<a href=\"#d4\" data-go=\"d4\">第14章 14.3 コンピューティングのコスト最適化</a> ／ <a href=\"#d4\" data-go=\"d4\">第14章 14.2 ストレージのコスト最適化</a> ／ <a href=\"#management\" data-go=\"management\">第8章 8.6 AWS Trusted Advisor</a>"},{"n":8,"topic":"セキュリティ × 可用性 × コスト","level":3,"body":["Organizationsで管理する50アカウントのAPI操作ログを一元管理します。要件は (1) <b>全アカウント・全リージョン</b>の操作を漏れなく記録する、(2) ログは<b>アカウント管理者でも改ざん・削除できない</b>、(3) 保管は5年間で、コストを抑える、の3つです。適切な構成はどれですか。"],"options":[{"l":"A","html":"CloudWatch Logsに全アカウントのログを集約し、保持期間を5年に設定する"},{"l":"B","html":"各アカウントで個別にCloudTrailを有効化し、それぞれのアカウントのS3バケットへ保存する。バケットポリシーで削除を禁止する"},{"l":"C","html":"管理アカウントで組織証跡を作成し、管理アカウントのS3バケットへ集約する。バージョニングを有効にし、S3 Standardのまま5年間保管する"},{"l":"D","html":"管理アカウントで組織証跡を作成し、専用のログアカウントのS3バケットへ集約する。バケットはオブジェクトロック（コンプライアンスモード）を有効にし、ライフサイクルでGlacierクラスへ移行する"}],"answer":["D"],"multi":false,"req":"①全アカウント・全リージョンの記録＝<b>組織証跡</b>（第1分野）／②管理者でも消せない＝<b>オブジェクトロック（コンプライアンスモード）＋アカウント分離</b>（第1分野）／③5年保管のコスト＝<b>ライフサイクルでGlacierへ</b>（第4分野）","key":"「<b>改ざんできない</b>」という要件は、バケットポリシーのような<b>変更できる防御</b>では満たせません。コンプライアンスモードのオブジェクトロックと、証跡アカウントの分離（権限の分離）が答えになります。","reasons":[{"l":"A","html":"CloudWatch Logsは検索・アラート向けで、長期保管のコスト効率ではS3＋Glacierに劣り、改ざん防止の要件も満たしません。"},{"l":"B","html":"個別設定は設定漏れが起きやすく、同一アカウント内にログがあるため、そのアカウントの管理者がポリシーを変更して削除できてしまいます（①②未達）。"},{"l":"C","html":"集約はできますが、バージョニングは削除を防ぐ仕組みではなく（権限があれば完全削除が可能）、5年間Standardで保管するためコストにも反します。"}],"refs":"<a href=\"#management\" data-go=\"management\">第8章 8.2 AWS CloudTrail</a> ／ <a href=\"#d1\" data-go=\"d1\">第11章 11.2 データ保護</a> ／ <a href=\"#d4\" data-go=\"d4\">第14章 14.2 ストレージのコスト最適化</a>"},{"n":9,"topic":"パフォーマンス × 弾力性","level":3,"body":["工場のセンサーから送られるデータを、リアルタイム処理と日次のバッチ分析の<b>両方</b>で使っています。要件は (1) センサーごとの<b>時系列の順序</b>を保つ、(2) リアルタイム処理と分析処理が<b>同じデータを独立して読める</b>、(3) 障害時は<b>過去24時間分を再処理</b>できる、の3つです。取り込みの入口として適切なサービスはどれですか。"],"options":[{"l":"A","html":"Amazon Kinesis Data Streams（センサーIDをパーティションキーにし、保持期間を24時間以上に設定する）"},{"l":"B","html":"Amazon SQS標準キューを2本用意し、送信側が両方へ送る"},{"l":"C","html":"Amazon Data Firehose（旧 Kinesis Data Firehose）でS3へ配信し、各処理はS3を読む"},{"l":"D","html":"Amazon SNSトピックに発行し、2つのSQSキューをサブスクライブさせる"}],"answer":["A"],"multi":false,"req":"①センサーごとの順序＝<b>パーティションキー単位の順序保証</b>（第3分野）／②複数のコンシューマーが同じデータを読む＝<b>ストリームの保持</b>（第2分野）／③再処理＝<b>保持期間内の巻き戻し</b>（第2分野）","key":"<b>「同じデータを複数のアプリが何度でも読める」「順序が保たれる」「再処理できる」</b>の3点が揃うのはKinesis Data Streamsです。SQSはメッセージを取得すると他から見えなくなり、再処理もできません。","reasons":[{"l":"B","html":"標準キューは順序を保証せず（①未達）、消費したメッセージは再取得できません（③未達）。送信側で二重送信する設計も壊れやすくなります。"},{"l":"C","html":"Firehoseは配送専用で<b>データを保持せず</b>、コンシューマーがストリームを読み直すこともできません。順序の保証もありません。"},{"l":"D","html":"ファンアウトで②は満たせますが、SQSに入った時点で順序保証と再処理性は失われます（①③未達）。"}],"refs":"<a href=\"#analytics\" data-go=\"analytics\">第7章 7.1 Amazon Kinesis</a> ／ <a href=\"#integration\" data-go=\"integration\">第6章 6.1 Amazon SQS</a> ／ <a href=\"#d2\" data-go=\"d2\">第12章 12.4 イベント駆動型アーキテクチャ</a>"},{"n":10,"topic":"全分野","level":3,"body":["社内の申請システムをAWSへ移行します。要件は (1) 利用は<b>平日日中のみ</b>で、夜間・週末はアクセスがない、(2) AZ障害時もサービスを継続する、(3) 保存データは暗号化し、DBはインターネットから到達できない、(4) 運用要員が少ないため<b>管理の手間を最小化</b>する、の4つです。最も適切な構成はどれですか。"],"options":[{"l":"A","html":"ALB＋EC2 Auto Scalingをマルチにに配置し、DBはEC2上にMySQLを構築して暗号化する"},{"l":"B","html":"ALB＋ECS on Fargate（Auto Scaling）をマルチAZに配置し、DBはAurora Serverless v2をプライベートサブネットで暗号化して構成する"},{"l":"C","html":"単一AZのEC2にアプリとMySQLを同居させ、夜間は停止するスクリプトを組む"},{"l":"D","html":"ALB＋EC2 Auto Scalingをマルチにに配置し、DBはRDSシングルAZをパブリックサブネットに配置して暗号化する"}],"answer":["B"],"multi":false,"req":"①日中のみ利用＝<b>アイドル時のコストを抑えたい</b>（第4分野）／②AZ障害への耐性＝<b>マルチAZ</b>（第2分野）／③暗号化とプライベート配置（第1分野）／④管理の手間＝<b>マネージド／サーバーレス</b>（第2・4分野）","key":"4つすべてを満たす選択肢は1つだけです。<b>Fargateでサーバー管理をなくし、Aurora Serverless v2でアイドル時のコストを抑え、マルチAZとプライベートサブネットで可用性とセキュリティを確保</b>します。複数要件の設問では、1つでも落とす選択肢を機械的に外していくのが最短です。","reasons":[{"l":"A","html":"EC2上のMySQLはパッチ適用・バックアップ・フェイルオーバーをすべて自前で運用することになり、④に反します。DB層の可用性も担保されません。"},{"l":"C","html":"単一AZ構成のため②を満たしません。同居構成は障害の影響範囲も広がります。"},{"l":"D","html":"RDSシングルAZは②を満たさず、パブリックサブネットへの配置は③に反します。"}],"refs":"<a href=\"#container\" data-go=\"container\">第9章 9.3 AWS Fargate</a> ／ <a href=\"#database\" data-go=\"database\">第4章 4.2 Amazon Aurora</a> ／ <a href=\"#d2\" data-go=\"d2\">第12章 12.5 高可用性と耐障害性</a> ／ <a href=\"#d1\" data-go=\"d1\">第11章 11.2 データ保護</a>"}]},{"id":"exam-set-07","file":"set-07.md","num":"問題セット07","title":"頻出①：ネットワークと名前解決","questions":[{"n":1,"topic":"SG と NACL","level":2,"body":["プライベートサブネットのEC2インスタンスから外部APIへのHTTPS通信が失敗します。セキュリティグループはアウトバウンドをすべて許可しており、ルートテーブルにはNAT Gateway宛てのデフォルトルートがあります。ネットワークACLではアウトバウンドでポート443を許可していますが、インバウンドはHTTPの80番のみ許可しています。原因として最も適切なものはどれですか。"],"options":[{"l":"A","html":"セキュリティグループのインバウンドで443番を許可していないため"},{"l":"B","html":"ネットワークACLは<b>ステートレス</b>であるため、戻りの通信（エフェメラルポート1024〜65535）をインバウンドで許可する必要がある"},{"l":"C","html":"NAT Gatewayがパブリックサブネットに配置されていないため"},{"l":"D","html":"ルートテーブルにインターネットゲートウェイ宛ての経路がないため"}],"answer":["B"],"multi":false,"req":"","key":"<b>セキュリティグループはステートフル（戻りは自動許可）／ネットワークACLはステートレス（往路と復路を別々に許可）</b>。NACLを触った直後の疎通不良は、まずエフェメラルポートの許可漏れを疑います。","reasons":[{"l":"A","html":"SGはステートフルなので、アウトバウンドで開始した通信の戻りはインバウンド許可がなくても通ります。"},{"l":"C","html":"NAT Gatewayの配置が誤っていれば通信は一切成立しません。設問はNACLの443アウトバウンドだけを許可した状態を示しており、原因の切り分けとして整合しません。"},{"l":"D","html":"プライベートサブネットのルートはNAT Gateway宛てが正しく、IGW宛てを設定するとプライベートサブネットの定義に反します。"}],"refs":"<a href=\"#network\" data-go=\"network\">第3章 3.2 通信制御</a> ／ <a href=\"#foundations\" data-go=\"foundations\">第0章 0.4 通信経路と認可の区別</a>"},{"n":2,"topic":"SG と NACL","level":2,"body":["特定の国から不正アクセスが集中しており、判明している数個の<b>送信元IPアドレスからのアクセスをサブネット単位で遮断</b>したいと考えています。適切な方法はどれですか。"],"options":[{"l":"A","html":"ネットワークACLのインバウンドルールで、対象IPを拒否（DENY）する"},{"l":"B","html":"セキュリティグループのインバウンドルールで、対象IPを拒否（DENY）する"},{"l":"C","html":"セキュリティグループから、対象IP以外をすべて許可するルールを作成する"},{"l":"D","html":"ルートテーブルで対象IP宛ての経路をブラックホールにする"}],"answer":["A"],"multi":false,"req":"","key":"<b>「拒否（DENY）ルールを書けるのはNACLだけ」「NACLはサブネット単位」</b>。特定IPの遮断はNACLの典型的な用途です。","reasons":[{"l":"B","html":"セキュリティグループは<b>許可ルールしか書けません</b>。拒否ルールという概念がありません。"},{"l":"C","html":"「対象IP以外をすべて許可」はSGでは事実上表現できず（許可の列挙になる）、運用も破綻します。"},{"l":"D","html":"ルートテーブルは宛先による経路制御で、送信元IPによる遮断はできません。"}],"refs":"<a href=\"#network\" data-go=\"network\">第3章 3.2 通信制御</a> ／ <a href=\"#cmp\" data-go=\"cmp\">付録A ネットワーク</a>"},{"n":3,"topic":"Route 53","level":3,"body":["同じWebアプリケーションを東京・アイルランド・オレゴンの3リージョンで運用しています。要件は「<b>利用者が最も応答の速いリージョンへ接続される</b>こと」です。適切なルーティングポリシーはどれですか。"],"options":[{"l":"A","html":"位置情報ルーティング（Geolocation）"},{"l":"B","html":"レイテンシーベースルーティング"},{"l":"C","html":"加重ルーティング"},{"l":"D","html":"複数値回答ルーティング"}],"answer":["B"],"multi":false,"req":"","key":"<b>「速い＝レイテンシーベース」「どこの国の人か＝位置情報」</b>。物理的な近さと実際の遅延は一致しないため、応答速度が要件ならレイテンシーベースです。","reasons":[{"l":"A","html":"位置情報は利用者の所在地で振り分ける方式で、<b>言語別サイトの出し分けや法規制によるアクセス制限</b>が用途です。必ずしも最速のリージョンにはなりません。"},{"l":"C","html":"加重は割合の指定で、A/Bテストや段階的な移行に使います。"},{"l":"D","html":"複数値回答は複数のIPをヘルスチェック付きで返す簡易な分散で、遅延の最小化は行いません。"}],"refs":"<a href=\"#network\" data-go=\"network\">第3章 3.4 名前解決：Route 53 と Resolver</a>"},{"n":4,"topic":"Route 53","level":2,"body":["<code>example.com</code>（ゾーン頂点／Zone Apex）へのアクセスを、Application Load Balancerへ向ける必要があります。追加のクエリ料金は避けたいと考えています。適切な設定はどれですか。"],"options":[{"l":"A","html":"ALBのIPアドレスを調べてAレコードに静的に設定する"},{"l":"B","html":"ALBのDNS名を指すCNAMEレコードを作成する"},{"l":"C","html":"ALBを指すエイリアス（ALIAS）レコードをAレコードとして作成する"},{"l":"D","html":"<code>www.example.com</code> へのリダイレクト用にNSレコードを作成する"}],"answer":["C"],"multi":false,"req":"","key":"<b>CNAMEはゾーン頂点に設定できません</b>。AWSリソース（ALB・CloudFront・S3・API Gatewayなど）へはエイリアスレコードを使い、これは<b>クエリ料金も無料</b>です。","reasons":[{"l":"A","html":"ALBのIPアドレスは動的に変化するため、静的な設定は障害の原因になります。"},{"l":"B","html":"DNSの仕様上、ゾーン頂点にCNAMEは設定できません（サブドメインなら可）。"},{"l":"D","html":"NSレコードはゾーンの委任に使うもので、リダイレクトの手段ではありません。"}],"refs":"<a href=\"#network\" data-go=\"network\">第3章 3.4 名前解決：Route 53 と Resolver</a>"},{"n":5,"topic":"VPC間接続","level":3,"body":["3つの部門VPC（A・B・C）があり、AとB、AとCの間でVPCピアリングを構成済みです。新たに<b>BとCの間でも通信</b>したいという要望が出ました。さらに今後VPCは20以上に増える見込みです。適切な対応はどれですか。"],"options":[{"l":"A","html":"各VPCにNAT Gatewayを配置し、インターネット経由で相互接続する"},{"l":"B","html":"VPC AのルートテーブルにBとCを相互に転送する経路を追加する"},{"l":"C","html":"BとCの間に新たなVPCピアリング接続を作成する"},{"l":"D","html":"AWS Transit Gatewayを導入し、各VPCをアタッチしてハブ＆スポーク構成にする"}],"answer":["D"],"multi":false,"req":"","key":"VPCピアリングは<b>推移的ルーティングができず</b>、接続数はVPC数の増加に対して急激に増えます（n×(n-1)/2）。<b>多数のVPCを相互接続するならTransit Gateway</b>が定石です。","reasons":[{"l":"A","html":"インターネット経由は遅延・コスト・セキュリティのいずれでも不利で、プライベート接続の要件を満たしません。"},{"l":"B","html":"ピアリングでは中継（推移的ルーティング）ができないため、この設定は機能しません。"},{"l":"C","html":"今回は動作しますが、20以上のVPCでは管理すべきピアリング接続が爆発的に増え、要件に耐えません。"}],"refs":"<a href=\"#network\" data-go=\"network\">第3章 3.3 VPCの外部接続</a> ／ <a href=\"#cmp\" data-go=\"cmp\">付録A ネットワーク</a>"},{"n":6,"topic":"ネットワーク監視","level":2,"body":["セキュリティ調査のため、特定のEC2インスタンスに出入りする通信を分析する必要があります。要件は (1) 拒否された通信も含めて<b>接続の記録</b>を残す、(2) 疑わしい通信については<b>パケットの中身</b>まで確認する、の2つです。適切な組み合わせはどれですか。"],"options":[{"l":"A","html":"VPCフローログで接続記録を取得し、パケットの中身はVPCトラフィックミラーリングで取得する"},{"l":"B","html":"VPCフローログのみを有効化し、ログからペイロードを抽出する"},{"l":"C","html":"CloudTrailのデータイベントで両方を記録する"},{"l":"D","html":"AWS Configで両方を記録する"}],"answer":["A"],"multi":false,"req":"","key":"<b>VPCフローログはメタデータ（送信元・宛先・ポート・許可/拒否）だけで、ペイロードは記録しません</b>。中身が必要ならトラフィックミラーリングです。","reasons":[{"l":"B","html":"フローログにはパケットの中身が含まれないため、要件(2)を満たせません。"},{"l":"C","html":"CloudTrailは<b>AWSのAPI呼び出し</b>の記録で、インスタンス間のネットワーク通信は対象外です。"},{"l":"D","html":"Configはリソースの設定状態と変更履歴を扱うサービスで、通信の記録はしません。"}],"refs":"<a href=\"#network\" data-go=\"network\">第3章 3.1 VPCの基礎</a> ／ <a href=\"#management\" data-go=\"management\">第8章 8.2 AWS CloudTrail</a>"},{"n":7,"topic":"ロードバランサー","level":2,"body":["Auto Scalingグループのスケールインが発生すると、<b>処理中のリクエストが途中で切断される</b>という苦情が出ています。1リクエストの処理には最大60秒かかります。適切な対処はどれですか。"],"options":[{"l":"A","html":"Auto Scalingグループのクールダウン期間を延長する"},{"l":"B","html":"ALBのアイドルタイムアウトを60秒未満に短縮する"},{"l":"C","html":"スティッキーセッションを有効にする"},{"l":"D","html":"ターゲットグループの「登録解除の遅延（接続ドレイニング）」を、処理の最大所要時間より長く設定する"}],"answer":["D"],"multi":false,"req":"","key":"<b>登録解除の遅延（既定300秒）</b>は、ターゲットを外す際に処理中のリクエストが完了するのを待つ設定です。「スケールイン時に通信が切れる」はこの値を疑います。","reasons":[{"l":"A","html":"クールダウンは次のスケーリング動作までの待機時間で、進行中のリクエストには影響しません。"},{"l":"B","html":"アイドルタイムアウトは無通信状態の接続を切るまでの時間で、短くすると切断は増えます。"},{"l":"C","html":"スティッキーセッションは振り分け先の固定であり、終了処理中の完了待ちとは無関係です。"}],"refs":"<a href=\"#network\" data-go=\"network\">第3章 3.5 負荷分散（ELB）</a> ／ <a href=\"#compute\" data-go=\"compute\">第1章 1.2 EC2 Auto Scaling</a>"},{"n":8,"topic":"エッジでの処理","level":3,"body":["CloudFrontで配信しているサイトに、次の2つの処理を追加します。それぞれに適したサービスはどれですか。","1. すべてのビューアリクエストに対し、<b>HTTPヘッダーを書き換え、URLを正規化する</b>（数万リクエスト/秒、1ミリ秒未満で完結）","2. オリジンへ転送する直前に、<b>外部の認可APIを呼び出して</b>アクセス可否を判定する"],"options":[{"l":"A","html":"1: CloudFront Functions ／ 2: Lambda@Edge"},{"l":"B","html":"1: Lambda@Edge ／ 2: CloudFront Functions"},{"l":"C","html":"1: CloudFront Functions ／ 2: CloudFront Functions"},{"l":"D","html":"1: AWS WAF ／ 2: Lambda@Edge"}],"answer":["A"],"multi":false,"req":"","key":"<b>CloudFront Functionsはビューア側のみ・JavaScript・サブミリ秒・超高頻度で安価</b>、ヘッダー操作やURL書き換えに使います。<b>Lambda@Edgeはオリジン側でも動作し、ネットワークアクセスや重い処理が可能</b>です。","reasons":[{"l":"B","html":"役割が逆です。CloudFront Functionsは外部へのネットワークアクセスができません。"},{"l":"C","html":"要件2は外部API呼び出しを含むため、CloudFront Functionsでは実現できません。"},{"l":"D","html":"WAFはリクエストの検査と遮断を行うもので、ヘッダーの書き換えやURL正規化の用途ではありません。"}],"refs":"<a href=\"#network\" data-go=\"network\">第3章 3.6 CloudFrontとGlobal Accelerator</a> ／ <a href=\"#compute\" data-go=\"compute\">第1章 1.6 AWS Lambda</a>"},{"n":9,"topic":"ハイブリッドDNS","level":3,"body":["オンプレミスのデータセンターとAWSをDirect Connectで接続しています。要件は (1) <b>オンプレミスのサーバーから、VPC内のプライベートホストゾーンの名前を解決</b>できるようにする、(2) <b>VPC内のEC2から、オンプレミスのADドメインの名前を解決</b>できるようにする、の2つです。適切な構成はどれですか。"],"options":[{"l":"A","html":"各EC2の <code>/etc/hosts</code> にオンプレミスのホスト名を記載し、オンプレ側のDNSにVPCのIPを静的登録する"},{"l":"B","html":"Route 53のパブリックホストゾーンに、両方のレコードを登録する"},{"l":"C","html":"Route 53 Resolverの<b>インバウンドエンドポイント</b>（要件1）と<b>アウトバウンドエンドポイント＋転送ルール</b>（要件2）を構成する"},{"l":"D","html":"AWS Directory Serviceの Simple AD を構築する"}],"answer":["C"],"multi":false,"req":"","key":"<b>インバウンド＝オンプレからAWSへ問い合わせる入口／アウトバウンド＝AWSからオンプレへ問い合わせる出口</b>。方向で名前が決まります。","reasons":[{"l":"A","html":"台数が増えるほど保守が破綻し、動的な変更にも追随できません。"},{"l":"B","html":"プライベートホストゾーンの名前をパブリックDNSに公開することになり、内部情報の露出という別の問題を生みます。"},{"l":"D","html":"Simple ADはディレクトリサービスであり、双方向のDNS転送を構成する仕組みではありません。"}],"refs":"<a href=\"#network\" data-go=\"network\">第3章 3.4 名前解決：Route 53 と Resolver</a>"},{"n":10,"topic":"IPv6とアウトバウンド","level":2,"body":["IPv6のみで構成したプライベートサブネットのEC2インスタンスから、<b>インターネット上のパッケージリポジトリへアウトバウンド通信のみ</b>を許可したいと考えています。インターネット側からの接続開始は拒否する必要があります。適切な構成はどれですか。"],"options":[{"l":"A","html":"NAT Gatewayを作成し、<code>::/0</code> の経路を向ける"},{"l":"B","html":"Egress-Only インターネットゲートウェイを作成し、<code>::/0</code> の経路を向ける"},{"l":"C","html":"インターネットゲートウェイを作成し、<code>::/0</code> の経路を向ける"},{"l":"D","html":"NATインスタンスを作成し、IPv6のNAT変換を有効にする"}],"answer":["B"],"multi":false,"req":"","key":"<b>IPv6にはNATの概念がありません</b>。アウトバウンド専用の出口は<b>Egress-Only インターネットゲートウェイ</b>（ステートフル）を使います。","reasons":[{"l":"A","html":"NAT GatewayはIPv4専用です（IPv6のトラフィックは扱いません）。"},{"l":"C","html":"IGWを向けると双方向に到達可能となり、インターネット側からの接続開始を拒否する要件に反します。"},{"l":"D","html":"IPv6でのNAT変換という仕組み自体がなく、NATインスタンスの運用負荷も要件に合いません。"}],"refs":"<a href=\"#network\" data-go=\"network\">第3章 3.1 VPCの基礎</a>"}]},{"id":"exam-set-08","file":"set-08.md","num":"問題セット08","title":"頻出②：ストレージの選択とデータ移行","questions":[{"n":1,"topic":"共有ストレージの選択","level":2,"body":["Linux上で動くコンテンツ管理システムを、複数のEC2インスタンスへスケールアウトします。各インスタンスは<b>同じディレクトリを同時に読み書き</b>する必要があり、容量は使用量に応じて自動的に増減してほしいと考えています。適切なストレージはどれですか。"],"options":[{"l":"A","html":"Amazon S3をファイルシステムとしてマウントする"},{"l":"B","html":"Amazon EBS（gp3）を各インスタンスにアタッチする"},{"l":"C","html":"Amazon EBS Multi-Attach（io2）"},{"l":"D","html":"Amazon EFS"}],"answer":["D"],"multi":false,"req":"","key":"<b>「複数のインスタンスから同時にマウント」「Linux／NFS」「容量の自動拡張」＝EFS</b>。マルチAZに分散配置されるため可用性も高まります。","reasons":[{"l":"A","html":"S3はオブジェクトストレージで、POSIXのファイルロックや部分更新を前提とするCMSの用途には向きません。"},{"l":"B","html":"EBSは単一インスタンスにアタッチするブロックストレージで、別々のボリュームになるため内容を共有できません。"},{"l":"C","html":"Multi-Attachは<b>io1/io2かつ同一AZ限定</b>で、さらにクラスタ対応ファイルシステムの導入が前提です。一般的なファイル共有には適しません。"}],"refs":"<a href=\"#storage\" data-go=\"storage\">第2章 2.3 Amazon EFS</a> ／ <a href=\"#cmp\" data-go=\"cmp\">付録A ストレージ</a>"},{"n":2,"topic":"共有ストレージの選択","level":2,"body":["社内の<b>Windowsファイルサーバー</b>をAWSへ移行します。要件は (1) SMBプロトコルで既存のクライアントからそのまま接続できる、(2) <b>Active Directoryのユーザー権限（NTFS ACL）をそのまま使う</b>、(3) サーバーの運用をやめたい、の3つです。適切なサービスはどれですか。"],"options":[{"l":"A","html":"Amazon FSx for Lustre"},{"l":"B","html":"Amazon EFS"},{"l":"C","html":"Amazon FSx for Windows File Server"},{"l":"D","html":"EC2にWindows Serverを構築してファイルサーバーにする"}],"answer":["C"],"multi":false,"req":"","key":"<b>Windows・SMB・Active Directory統合・NTFS ACL</b>というキーワードが揃えばFSx for Windows File Serverです。","reasons":[{"l":"A","html":"FSx for LustreはHPC・機械学習向けの高スループット並列ファイルシステムで、用途が異なります。"},{"l":"B","html":"EFSはLinux向けのNFSで、SMBやNTFS ACLには対応しません。"},{"l":"D","html":"OSのパッチ適用やバックアップなど運用が残り、要件(3)に反します。"}],"refs":"<a href=\"#storage\" data-go=\"storage\">第2章 2.4 Amazon FSx</a> ／ <a href=\"#cmp\" data-go=\"cmp\">付録A ストレージ</a>"},{"n":3,"topic":"ハイブリッドストレージ","level":3,"body":["オンプレミスのバックアップソフトウェアが、物理テープライブラリへバックアップを書き出しています。テープ装置を廃止したいものの、<b>バックアップソフトウェアは変更したくありません</b>。適切なサービスはどれですか。"],"options":[{"l":"A","html":"AWS DataSync"},{"l":"B","html":"AWS Storage Gateway の S3 File Gateway"},{"l":"C","html":"AWS Storage Gateway の Tape Gateway（仮想テープライブラリ）"},{"l":"D","html":"AWS Backup"}],"answer":["C"],"multi":false,"req":"","key":"<b>「既存のバックアップソフトのテープ装置をそのまま置き換える」＝Tape Gateway（VTL）</b>。バックアップソフトからは従来のテープ装置に見え、実体はS3／Glacierに保管されます。","reasons":[{"l":"A","html":"DataSyncはファイルの転送サービスで、テープ装置としては振る舞いません。"},{"l":"B","html":"File GatewayはNFS/SMBのファイル共有として見せる方式で、テープインターフェースは提供しません。"},{"l":"D","html":"AWS BackupはAWSリソースのバックアップを一元管理するサービスで、オンプレのバックアップソフトのテープ出力先にはなりません。"}],"refs":"<a href=\"#storage\" data-go=\"storage\">第2章 2.6 AWS Storage Gateway</a>"},{"n":4,"topic":"移行方式の選択","level":3,"body":["オンプレミスのNASに蓄積された<b>300 TB</b>のデータをS3へ移行します。拠点のインターネット回線は実効 <b>100 Mbps</b> で、業務時間帯は帯域を空けられません。移行はできるだけ短期間で完了させたい考えです。適切な方法はどれですか。"],"options":[{"l":"A","html":"S3 Transfer Acceleration を有効化してアップロードする"},{"l":"B","html":"AWS DataSync でインターネット経由の転送をスケジュール実行する"},{"l":"C","html":"AWS Transfer Family のSFTPエンドポイントへアップロードする"},{"l":"D","html":"AWS Snowball Edge を利用して物理デバイスで移送する"}],"answer":["D"],"multi":false,"req":"","key":"<b>回線容量と転送量の比</b>で判断します。100 Mbps で 300 TB は、理論値でも <b>270日以上</b>（300 TB ÷ 100 Mbps ≒ 6,600時間超）かかります。<b>回線が細い／データが大きい／期限がある</b>ならSnow Familyの物理移送です。","reasons":[{"l":"A","html":"Transfer Accelerationは遠距離のレイテンシを改善する機能で、帯域そのものを増やすわけではありません。"},{"l":"B","html":"DataSyncは転送を効率化しますが、<b>物理的な回線容量の上限は超えられません</b>。"},{"l":"C","html":"Transfer Familyは既存のSFTP運用を維持するためのサービスで、大容量の一括移行手段ではありません。"}],"refs":"<a href=\"#others\" data-go=\"others\">第10章 10.15 その他の移行サービス</a> ／ <a href=\"#others\" data-go=\"others\">第10章 10.13 AWS DataSync</a>"},{"n":5,"topic":"移行方式の選択","level":2,"body":["オンプレミスのNFSサーバーにある <b>2 TB</b> のファイルを、毎晩Amazon EFSへ同期します。差分のみを効率よく転送し、転送後にデータの整合性も検証したいと考えています。適切なサービスはどれですか。"],"options":[{"l":"A","html":"AWS DataSync"},{"l":"B","html":"AWS Storage Gateway の S3 File Gateway"},{"l":"C","html":"rsync を cron で実行するスクリプトをEC2上に構築する"},{"l":"D","html":"AWS Snowcone"}],"answer":["A"],"multi":false,"req":"","key":"<b>「オンプレ↔AWSの定期的なファイル同期」「増分転送」「整合性チェック」＝DataSync</b>。NFS/SMB/HDFSからS3・EFS・FSxへ転送できます。","reasons":[{"l":"B","html":"Storage Gatewayは<b>オンプレから使い続ける</b>ためのハイブリッド運用の仕組みで、同期ジョブの管理は行いません。"},{"l":"C","html":"自前実装は保守・監視・再試行・整合性検証をすべて自分で担うことになります。"},{"l":"D","html":"Snowconeは物理デバイスによる少量データの移送用で、毎晩の同期には使えません。"}],"refs":"<a href=\"#others\" data-go=\"others\">第10章 10.13 AWS DataSync</a> ／ <a href=\"#storage\" data-go=\"storage\">第2章 2.6 AWS Storage Gateway</a>"},{"n":6,"topic":"データベース移行","level":3,"body":["オンプレミスのOracleデータベース（4 TB）をAmazon Aurora PostgreSQLへ移行します。要件は (1) <b>停止時間を数分以内</b>に抑える、(2) スキーマとストアドプロシージャを変換する、の2つです。適切な組み合わせはどれですか。"],"options":[{"l":"A","html":"AWS DMSのフルロードのみを実行し、完了後にアプリケーションを切り替える"},{"l":"B","html":"AWS SCT（Schema Conversion Tool）でスキーマを変換し、AWS DMSの継続的レプリケーション（CDC）で差分同期してから切り替える"},{"l":"C","html":"Oracleのデータポンプでエクスポートし、S3経由でインポートする"},{"l":"D","html":"AWS DataSyncでデータファイルを転送する"}],"answer":["B"],"multi":false,"req":"","key":"<b>異種DB移行＝SCT（スキーマ変換）＋DMS（データ移行）</b>、<b>停止時間の最小化＝CDCによる継続的レプリケーション</b>。この組み合わせが定番です。","reasons":[{"l":"A","html":"フルロードのみでは、ロード中の更新が反映されず、停止時間もデータ量に比例して長くなります。"},{"l":"C","html":"データポンプは同種DB間の手段で、PostgreSQLへの異種移行ではスキーマ変換の問題が残り、停止時間も長くなります。"},{"l":"D","html":"DataSyncはファイル転送サービスで、稼働中のDBの論理的な移行には使えません。"}],"refs":"<a href=\"#others\" data-go=\"others\">第10章 10.12 AWS Database Migration Service</a>"},{"n":7,"topic":"外部連携","level":2,"body":["取引先30社が、毎日<b>SFTPクライアント</b>でファイルを送信してきます。現在はEC2上にSFTPサーバーを構築して運用していますが、パッチ適用と可用性の確保が負担です。取引先の接続方法は変更できません。適切な移行先はどれですか。"],"options":[{"l":"A","html":"AWS Transfer Family のSFTPエンドポイントを作成し、保存先をS3にする"},{"l":"B","html":"S3の事前署名URLを毎日発行して取引先へ配布する"},{"l":"C","html":"AWS DataSyncのエージェントを取引先に導入してもらう"},{"l":"D","html":"Amazon AppFlowで取引先のシステムと連携する"}],"answer":["A"],"multi":false,"req":"","key":"<b>「取引先の既存SFTPクライアントを変えられない」「サーバー運用をやめたい」＝Transfer Family</b>。認証はIAM・Active Directory・カスタムIDプロバイダーと連携でき、保存先はS3またはEFSです。","reasons":[{"l":"B","html":"接続方法の変更を取引先に強いることになり、前提に反します。"},{"l":"C","html":"取引先側にエージェント導入を求めるのは現実的でなく、DataSyncの用途とも異なります。"},{"l":"D","html":"AppFlowはSaaS（SalesforceやZendeskなど）との連携用で、SFTPの受け口にはなりません。"}],"refs":"<a href=\"#others\" data-go=\"others\">第10章 10.14 AWS Transfer Family</a>"},{"n":8,"topic":"S3のデータ保護","level":3,"body":["コンプライアンス要件により、S3バケットのオブジェクトを<b>別リージョンへ複製</b>することになりました。設定後に確認すると、<b>既存のオブジェクトが複製されていません</b>。原因と対処として正しいものはどれですか。<b>2つ選択してください。</b>"],"options":[{"l":"A","html":"レプリケーションは設定後に作成・更新されたオブジェクトが対象のため、既存分はS3バッチレプリケーションで複製する"},{"l":"B","html":"既存オブジェクトを複製するには、バケットのリージョンを変更する必要がある"},{"l":"C","html":"レプリケーション先のストレージクラスをGlacierにすれば既存オブジェクトも複製される"},{"l":"D","html":"レプリケーションはライフサイクルポリシーで設定するため、移行日数を0日にすれば既存分も対象になる"},{"l":"E","html":"レプリケーションにはソースと宛先の両方のバケットで<b>バージョニングの有効化</b>が必要である"}],"answer":["A","E"],"multi":true,"req":"","key":"レプリケーションの前提は<b>バージョニング</b>、対象は<b>設定後の変更分</b>。既存オブジェクトは<b>バッチレプリケーション</b>で別途複製します。","reasons":[{"l":"B","html":"バケットのリージョンは作成後に変更できません。"},{"l":"C","html":"宛先のストレージクラスは複製対象の範囲とは無関係です。"},{"l":"D","html":"レプリケーションとライフサイクルは別の機能で、ライフサイクルで複製を起こすことはできません。"}],"refs":"<a href=\"#storage\" data-go=\"storage\">第2章 2.1 Amazon S3</a> ／ <a href=\"#d2\" data-go=\"d2\">第12章 12.5 高可用性と耐障害性</a>"},{"n":9,"topic":"EC2のストレージ","level":2,"body":["動画のトランスコード処理を行うEC2インスタンスで、<b>処理中の一時ファイル</b>を最速のディスクに置きたいと考えています。一時ファイルは処理が終われば不要で、インスタンスの停止・終了時に失われても構いません。適切なストレージはどれですか。"],"options":[{"l":"A","html":"EBS gp3"},{"l":"B","html":"インスタンスストア（NVMe SSD）"},{"l":"C","html":"EBS st1"},{"l":"D","html":"Amazon EFS"}],"answer":["B"],"multi":false,"req":"","key":"<b>インスタンスストアは物理サーバー直結で最速</b>。<b>停止・終了でデータが消える</b>（再起動では消えない）という性質が、一時ファイルの用途と一致します。","reasons":[{"l":"A","html":"gp3は永続ストレージで十分高速ですが、ネットワーク越しのためインスタンスストアのレイテンシには及びません。"},{"l":"C","html":"st1はHDDでシーケンシャルなスループット向け、ランダムI/Oの多い一時領域には不適です。"},{"l":"D","html":"EFSはネットワーク共有ファイルシステムで、一時ファイル用途では遅く、コストも無駄になります。"}],"refs":"<a href=\"#storage\" data-go=\"storage\">第2章 2.2 Amazon EBS</a> ／ <a href=\"#d3\" data-go=\"d3\">第13章 13.1 ストレージとパフォーマンス</a>"},{"n":10,"topic":"大容量アップロード","level":2,"body":["海外の拠点から、<b>1ファイルあたり20 GB</b>の測定データをS3（東京リージョン）へ毎日アップロードしています。アップロードの失敗が多く、完了までの時間も長いという問題があります。適切な対処はどれですか。<b>2つ選択してください。</b>"],"options":[{"l":"A","html":"ストレージクラスをS3 Standard-IAに変更する"},{"l":"B","html":"アップロード先のバケットでバージョニングを有効化する"},{"l":"C","html":"マルチパートアップロードを使い、分割して並列にアップロードする"},{"l":"D","html":"S3 Transfer Accelerationを有効化し、最寄りのエッジロケーション経由で転送する"},{"l":"E","html":"ファイルをGlacier Deep Archiveへ直接アップロードする"}],"answer":["C","D"],"multi":true,"req":"","key":"<b>単一PUTの上限は5 GB</b>であり、20 GBのファイルは<b>マルチパートアップロードが必須</b>です（分割・並列・再試行が可能になり、失敗にも強くなります）。加えて<b>遠距離からの転送はTransfer Acceleration</b>で改善します。","reasons":[{"l":"A","html":"ストレージクラスは保管コストの話で、アップロードの速度や成功率には影響しません。"},{"l":"B","html":"バージョニングは誤削除・上書き対策で、転送の問題には関係しません。"},{"l":"E","html":"アーカイブクラスへ直接置いても転送は速くならず、取り出しにも時間がかかるようになります。"}],"refs":"<a href=\"#storage\" data-go=\"storage\">第2章 2.1 Amazon S3</a> ／ <a href=\"#d3\" data-go=\"d3\">第13章 13.1 ストレージとパフォーマンス</a>"}]},{"id":"exam-set-09","file":"set-09.md","num":"問題セット09","title":"頻出③：ID・運用・サーバーレス連携","questions":[{"n":1,"topic":"認証の主体","level":3,"body":["3つのID管理の要件があります。それぞれに最も適したサービスの組み合わせはどれですか。","1. モバイルアプリの<b>エンドユーザー数百万人</b>のサインアップ・サインインを実装したい","2. 社員が<b>50個のAWSアカウント</b>へ、既存のIdP（Okta）のIDでログインできるようにしたい","3. AWS上のWindows Serverを、<b>オンプレミスのActive Directory</b>のユーザーで認証させたい（AWS側にディレクトリを置かない）"],"options":[{"l":"A","html":"1: IAM Identity Center ／ 2: Amazon Cognito ／ 3: AWS Managed Microsoft AD"},{"l":"B","html":"1: Amazon Cognito ／ 2: IAM Identity Center ／ 3: AD Connector"},{"l":"C","html":"1: Amazon Cognito ／ 2: IAMユーザーとグループ ／ 3: Simple AD"},{"l":"D","html":"1: AWS Directory Service ／ 2: IAM Identity Center ／ 3: Amazon Cognito"}],"answer":["B"],"multi":false,"req":"","key":"<b>アプリの利用者＝Cognito／AWSを操作する社員＝IAM Identity Center／Windowsのドメイン認証＝Directory Service</b>。さらにDirectory Serviceの中では「<b>AWS側にディレクトリを置かず、オンプレADへ転送する＝AD Connector</b>」です。","reasons":[{"l":"A","html":"1と2が逆です。Identity Centerは社内の管理者・開発者向けで、一般消費者のサインアップには使いません。"},{"l":"C","html":"50アカウントに個別のIAMユーザーを作る運用は破綻します。Simple ADはオンプレADとの信頼関係を張れず、要件3を満たしません。"},{"l":"D","html":"Directory Serviceは消費者向けのサインアップ基盤ではなく、Cognitoはドメイン参加の認証を提供しません。"}],"refs":"<a href=\"#security\" data-go=\"security\">第5章 5.2 IAM Identity Center</a> ／ <a href=\"#security\" data-go=\"security\">第5章 5.3 AWS Directory Service</a> ／ <a href=\"#security\" data-go=\"security\">第5章 5.4 Amazon Cognito</a>"},{"n":2,"topic":"ポリシー評価","level":3,"body":["あるIAMロールには<code>AmazonS3FullAccess</code>が付与されています。しかし、そのアカウントが所属するOUに適用されたSCPで、<code>s3:DeleteObject</code>が明示的に拒否されています。さらに対象バケットのバケットポリシーでは、当該ロールに対して<code>s3:*</code>が明示的に許可されています。このロールは対象バケットのオブジェクトを削除できますか。"],"options":[{"l":"A","html":"できる。SCPはルートユーザーにのみ適用されるため"},{"l":"B","html":"できる。バケットポリシーでの明示的な許可が、SCPの拒否を上書きするため"},{"l":"C","html":"できる。IAMポリシーとバケットポリシーの両方で許可されているため"},{"l":"D","html":"できない。SCPによる明示的な拒否は、他のどの許可よりも優先されるため"}],"answer":["D"],"multi":false,"req":"","key":"<b>明示的な拒否（Deny）はすべての許可に優先</b>します。SCP・IAMポリシー・リソースポリシーのどこか1つでも拒否があれば、その操作は実行できません。","reasons":[{"l":"A","html":"SCPはメンバーアカウント内のすべてのプリンシパル（ルートユーザーを含む）に適用されます。管理アカウントには効かない、という点との混同に注意します。"},{"l":"B","html":"リソースポリシーの許可がSCPの拒否を上書きすることはありません。評価順の理解を問う典型的な誤答です。"},{"l":"C","html":"「複数箇所で許可されている＝実行できる」ではありません。拒否の有無が先に効きます。"}],"refs":"<a href=\"#security\" data-go=\"security\">第5章 5.1 AWS IAM</a> ／ <a href=\"#d1\" data-go=\"d1\">第11章 11.1 アクセス管理</a>"},{"n":3,"topic":"資格情報の管理","level":2,"body":["アプリケーションの設定値と資格情報をAWSで管理します。要件は (1) RDSのマスターパスワードを<b>30日ごとに自動でローテーション</b>する、(2) アプリの機能フラグなど<b>数百件の設定値を無料で</b>保管する、の2つです。適切な組み合わせはどれですか。"],"options":[{"l":"A","html":"1: AWS KMS ／ 2: Amazon S3"},{"l":"B","html":"1: AWS Systems Manager Parameter Store ／ 2: AWS Secrets Manager"},{"l":"C","html":"1: AWS Secrets Manager ／ 2: AWS Systems Manager Parameter Store"},{"l":"D","html":"1: AWS Secrets Manager ／ 2: AWS Secrets Manager"}],"answer":["C"],"multi":false,"req":"","key":"<b>自動ローテーションが要件にあるか</b>で決まります。あればSecrets Manager（RDS等と統合済み・有料）、なければParameter Store（標準パラメータは無料、SecureStringでKMS暗号化）。","reasons":[{"l":"A","html":"KMSは鍵の管理サービスで、資格情報そのものの保管・ローテーションは行いません。S3に平文で置くのは論外です。"},{"l":"B","html":"Parameter Storeの標準機能には、RDSと統合した自動ローテーションはありません。"},{"l":"D","html":"Secrets Managerはシークレット1件あたりの月額課金があるため、数百件の一般的な設定値には割高です。"}],"refs":"<a href=\"#security\" data-go=\"security\">第5章 5.10 Secrets Manager vs Parameter Store</a>"},{"n":4,"topic":"監視","level":2,"body":["EC2インスタンスの<b>メモリ使用率</b>と<b>ディスクの空き容量</b>が、CloudWatchのメトリクス一覧に表示されず、しきい値アラームを設定できません。適切な対処はどれですか。"],"options":[{"l":"A","html":"CloudWatchエージェントをインスタンスに導入し、カスタムメトリクスとして送信する"},{"l":"B","html":"詳細モニタリングを有効化し、取得間隔を1分にする"},{"l":"C","html":"インスタンスにIAMロールを付与すれば、標準メトリクスとして自動的に収集される"},{"l":"D","html":"VPCフローログを有効化する"}],"answer":["A"],"multi":false,"req":"","key":"CloudWatchの標準メトリクスは<b>ハイパーバイザー視点</b>で取得されるため、<b>OSの内部情報であるメモリ使用率やディスク空き容量は含まれません</b>。エージェントの導入が必要です（試験の頻出ポイント）。","reasons":[{"l":"B","html":"詳細モニタリングは取得<b>間隔</b>を5分から1分にするもので、取得できる<b>種類</b>は増えません。"},{"l":"C","html":"IAMロールはエージェントがメトリクスを送信するために必要ですが、ロールだけでは収集されません。"},{"l":"D","html":"フローログはネットワーク通信の記録で、OSのリソース使用率とは無関係です。"}],"refs":"<a href=\"#management\" data-go=\"management\">第8章 8.1 Amazon CloudWatch</a> ／ <a href=\"#d3\" data-go=\"d3\">第13章 13.2 コンピューティングとパフォーマンス</a>"},{"n":5,"topic":"監視と統制","level":3,"body":["セキュリティ監査の指摘に対応します。要件は (1) <b>ルートユーザーによるログインが発生したら即座に通知</b>する、(2) <b>S3バケットが公開設定になっていないかを継続的に評価し、違反を自動修復</b>する、の2つです。適切な組み合わせはどれですか。"],"options":[{"l":"A","html":"1: AWS Config ルール ／ 2: CloudTrail のデータイベント"},{"l":"B","html":"1: CloudTrail → CloudWatch Logs のメトリクスフィルタ＋アラーム → SNS ／ 2: AWS Config ルール＋修復アクション"},{"l":"C","html":"1: Amazon GuardDuty ／ 2: Amazon Macie"},{"l":"D","html":"1: AWS Trusted Advisor ／ 2: Amazon Inspector"}],"answer":["B"],"multi":false,"req":"","key":"<b>「特定のAPI操作をリアルタイムに検知」＝CloudTrail＋メトリクスフィルタ＋アラーム</b>、<b>「設定が基準に沿っているかを継続評価し直す」＝Config ルール＋修復アクション（SSM Automation）</b>。","reasons":[{"l":"A","html":"Configは設定状態の評価であり、ログイン操作そのものの通知には向きません。データイベントはS3オブジェクト操作等の記録で、公開設定の評価はしません。"},{"l":"C","html":"GuardDutyは脅威検知、Macieは機密データの発見で、いずれも設定の準拠評価や自動修復の仕組みではありません。"},{"l":"D","html":"Trusted Advisorは定期的な点検、Inspectorは脆弱性診断で、要件の即時通知・自動修復には対応しません。"}],"refs":"<a href=\"#management\" data-go=\"management\">第8章 8.2 AWS CloudTrail</a> ／ <a href=\"#management\" data-go=\"management\">第8章 8.7 AWS Config</a>"},{"n":6,"topic":"イベント駆動","level":2,"body":["次の2つの自動化を実装します。それぞれに適したサービスはどれですか。","1. <b>毎日深夜2時</b>に、未使用リソースを棚卸しするLambda関数を実行する","2. <b>RDSインスタンスの障害イベントが発生したら</b>、運用チームのSlackへ通知する"],"options":[{"l":"A","html":"1: Amazon EventBridge（スケジュール式） ／ 2: Amazon EventBridge（イベントパターン）"},{"l":"B","html":"1: Amazon SQSの遅延キュー ／ 2: Amazon SNS"},{"l":"C","html":"1: AWS Lambdaのタイマー機能 ／ 2: AWS CloudTrail"},{"l":"D","html":"1: Amazon EventBridge（スケジュール式） ／ 2: Amazon SQS"}],"answer":["A"],"multi":false,"req":"","key":"<b>EventBridgeは「cron/rate式による定期実行」と「AWSサービスの状態変化をルールで振り分ける」の両方を担います</b>。どちらも試験の定番パターンです。","reasons":[{"l":"B","html":"SQSの遅延キューは配信を最大15分遅らせる機能で、毎日のスケジュール実行はできません。"},{"l":"C","html":"Lambda自体にスケジュール実行の機能はなく（EventBridgeが起動します）、CloudTrailは記録であって通知の振り分けは行いません。"},{"l":"D","html":"SQSはキューであり、イベントの内容に応じた振り分けや通知の役割は担いません。"}],"refs":"<a href=\"#integration\" data-go=\"integration\">第6章 6.3 Amazon EventBridge</a> ／ <a href=\"#d2\" data-go=\"d2\">第12章 12.4 イベント駆動型アーキテクチャ</a>"},{"n":7,"topic":"ワークフロー","level":3,"body":["保険金請求の処理を自動化します。処理は「書類のOCR → 内容の検証 → <b>金額が100万円を超える場合は管理者の承認を待つ</b> → 支払い」という流れで、各ステップの失敗時には再試行と補償処理が必要です。承認待ちは数日に及ぶことがあります。適切なサービスはどれですか。"],"options":[{"l":"A","html":"AWS Step Functions（標準ワークフロー、コールバックパターンで承認を待つ）"},{"l":"B","html":"単一のAWS Lambda関数にすべての処理を実装する"},{"l":"C","html":"Amazon SQS FIFOキューで各ステップをつなぐ"},{"l":"D","html":"Amazon EventBridgeのイベントバスで各Lambdaを連鎖させる"}],"answer":["A"],"multi":false,"req":"","key":"<b>分岐・再試行・補償処理・長時間の待機</b>を宣言的に管理できるのがStep Functionsです。標準ワークフローは<b>最大1年</b>実行でき、タスクトークンによるコールバックで人の承認を待てます。","reasons":[{"l":"B","html":"Lambdaの実行時間は<b>最大15分</b>で、数日の承認待ちは不可能です。エラー処理も自前実装になります。"},{"l":"C","html":"キューは処理の受け渡しはできますが、条件分岐・状態管理・補償処理の枠組みは提供しません。"},{"l":"D","html":"EventBridgeでの連鎖は、全体の状態把握と再試行・巻き戻しが困難で、長時間の待機状態を管理できません。"}],"refs":"<a href=\"#integration\" data-go=\"integration\">第6章 6.4 AWS Step Functions</a> ／ <a href=\"#d2\" data-go=\"d2\">第12章 12.2 疎結合アーキテクチャ</a>"},{"n":8,"topic":"コンテナの権限","level":3,"body":["Amazon ECS on Fargateで動くアプリケーションが、S3バケットへのアクセスで<code>AccessDenied</code>になります。一方、<b>ECRからのイメージ取得とCloudWatch Logsへのログ出力は正常</b>に動作しています。修正すべき対象はどれですか。"],"options":[{"l":"A","html":"サービスにアタッチされたセキュリティグループでHTTPSのアウトバウンドを許可する"},{"l":"B","html":"タスク実行ロール（task execution role）にS3へのアクセス許可を追加する"},{"l":"C","html":"EC2インスタンスプロファイルにS3へのアクセス許可を追加する"},{"l":"D","html":"タスクロール（task role）にS3へのアクセス許可を追加する"}],"answer":["D"],"multi":false,"req":"","key":"<b>タスクロール＝コンテナ内のアプリが他のAWSサービスを呼ぶための権限</b>、<b>タスク実行ロール＝ECSエージェントがイメージ取得とログ出力を行うための権限</b>。イメージ取得とログが正常なので、実行ロールは正しく機能しています。","reasons":[{"l":"A","html":"通信が遮断されていればタイムアウトになります。<code>AccessDenied</code>は<b>到達したうえで認可が拒否された</b>ことを示します。"},{"l":"B","html":"実行ロールはアプリケーションのAPI呼び出しには使われません（症状からも正常に機能していると分かります）。"},{"l":"C","html":"Fargateではインスタンスプロファイルは存在しません（EC2起動タイプの概念です）。"}],"refs":"<a href=\"#container\" data-go=\"container\">第9章 9.1 Amazon ECS</a> ／ <a href=\"#foundations\" data-go=\"foundations\">第0章 0.4 通信経路と認可の区別</a>"},{"n":9,"topic":"Lambdaの同時実行","level":3,"body":["同一アカウント内に複数のLambda関数があります。次の2つの問題が発生しました。<b>それぞれに対する適切な対処を2つ選択してください。</b>","1. 大量に起動されるバッチ用の関数が同時実行数を占有し、<b>決済APIの関数がスロットリング</b>された","2. 決済APIの関数で、<b>コールドスタートによる初回応答の遅延</b>が問題になっている"],"options":[{"l":"A","html":"決済APIの関数のタイムアウト値を15分に延長する"},{"l":"B","html":"バッチ用の関数に<b>予約済み同時実行数</b>を設定し、使用できる上限を制限する"},{"l":"C","html":"決済APIの関数に<b>プロビジョニング済み同時実行数</b>を設定する"},{"l":"D","html":"バッチ用の関数のメモリ割り当てを減らす"},{"l":"E","html":"決済APIの関数をVPC内に配置する"}],"answer":["B","C"],"multi":true,"req":"","key":"<b>予約済み同時実行＝その関数の上限を固定し、他の関数への影響を隔離する</b>（スロットリング対策）。<b>プロビジョニング済み同時実行＝あらかじめ実行環境を温めておく</b>（コールドスタート対策）。名前が似ているため役割の取り違えが頻出します。","reasons":[{"l":"A","html":"タイムアウトは1回の実行時間の上限で、同時実行数の枯渇にも初回遅延にも効きません。"},{"l":"D","html":"メモリを減らすとCPUも比例して下がり処理が遅くなるため、占有時間はむしろ延びます。"},{"l":"E","html":"VPC配置はネットワーク到達性のための設定で、コールドスタートはむしろ不利になる場合があります。"}],"refs":"<a href=\"#compute\" data-go=\"compute\">第1章 1.6 AWS Lambda</a> ／ <a href=\"#d3\" data-go=\"d3\">第13章 13.2 コンピューティングとパフォーマンス</a>"},{"n":10,"topic":"運用の自動化","level":2,"body":["数百台のEC2インスタンスに対し、OSのセキュリティパッチを<b>定期的に適用し、適用状況をレポート</b>したいと考えています。インスタンスへのSSH接続は禁止されています。適切なサービスはどれですか。"],"options":[{"l":"A","html":"AWS Config"},{"l":"B","html":"Amazon Inspector"},{"l":"C","html":"AWS Systems Manager Patch Manager（メンテナンスウィンドウで実行）"},{"l":"D","html":"Amazon EventBridge＋Lambdaで各インスタンスへSSH接続してパッチを適用する"}],"answer":["C"],"multi":false,"req":"","key":"<b>パッチ適用の自動化と準拠レポート＝Patch Manager</b>。SSMエージェント経由で動作するためSSHは不要で、メンテナンスウィンドウで実行時間帯も制御できます。","reasons":[{"l":"A","html":"Configは設定の記録と準拠評価で、OSのパッチ適用の実行者ではありません。"},{"l":"B","html":"Inspectorは脆弱性を<b>検出</b>するサービスで、パッチの適用は行いません（検出→Patch Managerで適用、という組み合わせになります）。"},{"l":"D","html":"SSH接続が禁止されている前提に反し、自前実装の保守負担も大きくなります。"}],"refs":"<a href=\"#management\" data-go=\"management\">第8章 8.4 AWS Systems Manager</a> ／ <a href=\"#security\" data-go=\"security\">第5章 5.12 Amazon Inspector</a>"}]},{"id":"exam-set-10","file":"set-10.md","num":"問題セット10","title":"頻出④：コンピューティングとアプリ連携の細目","questions":[{"n":1,"topic":"スケーリングポリシー","level":2,"body":["ECサイトのアクセスは、毎日<b>朝9時と夜20時に大きく増える</b>という明確な周期があります。現在はターゲット追跡スケーリングのみを設定していますが、増加の立ち上がりでインスタンスの起動が追いつかず、数分間レスポンスが悪化します。適切な対処はどれですか。"],"options":[{"l":"A","html":"クールダウン期間を0秒に設定する"},{"l":"B","html":"ステップスケーリングに変更し、しきい値を細かく刻む"},{"l":"C","html":"予測スケーリングを有効にし、過去の傾向から事前にインスタンスを増やす"},{"l":"D","html":"スケールイン保護をすべてのインスタンスに設定する"}],"answer":["C"],"multi":false,"req":"","key":"<b>周期的な負荷パターンがあり、事後の反応では間に合わない</b>場合は予測スケーリングです。機械学習で需要を予測し、<b>負荷が来る前に</b>容量を用意します（時刻が固定で読めるならスケジュールされたスケーリングでも可）。","reasons":[{"l":"A","html":"クールダウンを詰めても、しきい値を超えてから起動する点は変わらず、立ち上がりの遅れは解消しません。"},{"l":"B","html":"ステップスケーリングも実測値に反応する方式のため、起動時間そのものは埋められません。"},{"l":"D","html":"スケールイン保護は縮小を止める設定で、増加への追随とは無関係です。"}],"refs":"<a href=\"#compute\" data-go=\"compute\">第1章 1.2 EC2 Auto Scaling</a> ／ <a href=\"#d2\" data-go=\"d2\">第12章 12.1 スケーリング戦略</a>"},{"n":2,"topic":"ライフサイクルフック","level":3,"body":["Auto Scalingグループのスケールインでインスタンスが終了する際、<b>ローカルに残っているアプリケーションログをS3へ退避</b>してから終了させたいと考えています。退避には最大3分かかります。適切な方法はどれですか。"],"options":[{"l":"A","html":"終了ポリシーを「最も古いインスタンス」に変更する"},{"l":"B","html":"終了時のライフサイクルフック（Terminating:Wait）を設定し、退避完了後にライフサイクルアクションを完了させる"},{"l":"C","html":"ターゲットグループの登録解除の遅延を180秒に設定する"},{"l":"D","html":"インスタンスのシャットダウンスクリプトに退避処理を書く"}],"answer":["B"],"multi":false,"req":"","key":"<b>終了・起動の途中で処理を差し込みたいときはライフサイクルフック</b>です。インスタンスを待機状態（Terminating:Wait）で止め、処理完了を通知するまで終了を保留できます。","reasons":[{"l":"A","html":"終了ポリシーは「どのインスタンスを選ぶか」の設定で、終了処理の内容には関与しません。"},{"l":"C","html":"登録解除の遅延は<b>処理中のリクエストを完了させる</b>ための待機で、任意の後処理の完了を保証するものではありません。"},{"l":"D","html":"シャットダウンスクリプトは確実な完了を保証できず（強制終了され得る）、失敗時の検知もできません。"}],"refs":"<a href=\"#compute\" data-go=\"compute\">第1章 1.2 EC2 Auto Scaling</a>"},{"n":3,"topic":"Elastic Beanstalk","level":3,"body":["Elastic Beanstalkで運用するアプリケーションのデプロイ要件は、(1) <b>ダウンタイムを発生させない</b>、(2) 既存インスタンスの容量を落とさない、(3) 新バージョンに問題があれば<b>即座に切り戻せる</b>、の3つです。追加インスタンスのコストは許容できます。適切なデプロイポリシーはどれですか。"],"options":[{"l":"A","html":"All at once"},{"l":"B","html":"Rolling"},{"l":"C","html":"Rolling with additional batch"},{"l":"D","html":"Immutable"}],"answer":["D"],"multi":false,"req":"","key":"Immutableは<b>新しいインスタンス群を別に立ち上げてから入れ替える</b>方式です。既存環境には触れないため容量が落ちず、失敗時は新しい群を破棄するだけで<b>即座に元に戻せます</b>。","reasons":[{"l":"A","html":"全インスタンスを同時に入れ替えるためダウンタイムが発生します。"},{"l":"B","html":"入れ替え中は稼働インスタンスが減り、要件(2)に反します。切り戻しにも再デプロイが必要です。"},{"l":"C","html":"容量は維持できますが、既存インスタンスを段階的に更新するため、切り戻しには再デプロイを要し要件(3)を満たしにくくなります。"}],"refs":"<a href=\"#compute\" data-go=\"compute\">第1章 1.3 AWS Elastic Beanstalk</a>"},{"n":4,"topic":"AMIの管理","level":2,"body":["セキュリティ部門から「<b>毎月、最新のOSパッチとセキュリティエージェントを適用したゴールデンAMIを作成し、各アカウントへ配布する</b>」よう求められました。手作業を避けたいと考えています。適切なサービスはどれですか。"],"options":[{"l":"A","html":"EC2 Image Builder"},{"l":"B","html":"AWS Systems Manager Patch Manager"},{"l":"C","html":"Amazon Inspector"},{"l":"D","html":"AWS Backup"}],"answer":["A"],"multi":false,"req":"","key":"<b>AMIの作成・テスト・配布をパイプラインとして自動化</b>するのがEC2 Image Builderです。スケジュール実行と他アカウントへの共有まで扱えます。","reasons":[{"l":"B","html":"Patch Managerは<b>稼働中のインスタンス</b>へパッチを適用する仕組みで、AMIの生成・配布は行いません（併用はします）。"},{"l":"C","html":"Inspectorは脆弱性の検出であり、イメージの作成はしません。"},{"l":"D","html":"AWS Backupはバックアップの管理で、ゴールデンイメージの継続的な生成には使いません。"}],"refs":"<a href=\"#compute\" data-go=\"compute\">第1章 1.7 その他のコンピューティングサービス</a> ／ <a href=\"#management\" data-go=\"management\">第8章 8.4 AWS Systems Manager</a>"},{"n":5,"topic":"EC2の停止と再開","level":3,"body":["科学計算アプリケーションは、起動時に<b>メモリ上へ大きなデータセットを読み込むのに15分</b>かかります。日中しか使わないため夜間は停止したいのですが、翌朝の起動に毎回15分待たされるのは避けたいと考えています。適切な方法はどれですか。"],"options":[{"l":"A","html":"インスタンスを停止せず、夜間はインスタンスタイプを小さく変更する"},{"l":"B","html":"EC2 Hibernate（休止）を使い、メモリの内容をEBSルートボリュームへ保存して再開する"},{"l":"C","html":"夜間にAMIを作成し、翌朝そのAMIから新しいインスタンスを起動する"},{"l":"D","html":"インスタンスストアにデータセットを保存しておく"}],"answer":["B"],"multi":false,"req":"","key":"<b>Hibernateはメモリの内容をEBSルートボリュームに保存</b>し、再開時に復元します。長い初期化処理をやり直さずに済みます（対応インスタンスタイプ・暗号化されたルートボリュームなどの条件があります）。","reasons":[{"l":"A","html":"タイプ変更にも停止が必要なうえ、稼働し続ける分の課金が残ります。"},{"l":"C","html":"AMIから起動しても<b>メモリの状態は復元されない</b>ため、15分の読み込みは再度発生します。"},{"l":"D","html":"インスタンスストアは<b>停止で内容が失われます</b>。加えてディスクからの読み込み自体は発生します。"}],"refs":"<a href=\"#compute\" data-go=\"compute\">第1章 1.1 Amazon EC2</a> ／ <a href=\"#d4\" data-go=\"d4\">第14章 14.3 コンピューティングのコスト最適化</a>"},{"n":6,"topic":"Lambdaの起動時間","level":3,"body":["Java製のLambda関数で、<b>初回呼び出しの遅延（コールドスタート）が1秒を超える</b>ことが問題になっています。呼び出しは断続的で、常時ウォームな状態を維持するとコストが見合いません。適切な対処はどれですか。"],"options":[{"l":"A","html":"共通ライブラリをLambdaレイヤーへ移動する"},{"l":"B","html":"プロビジョニング済み同時実行数を常時100に設定する"},{"l":"C","html":"関数のタイムアウト値を延長する"},{"l":"D","html":"Lambda SnapStartを有効化する"}],"answer":["D"],"multi":false,"req":"","key":"<b>SnapStartは初期化済みの実行環境のスナップショットから復元</b>するため、追加コストなしでコールドスタートを短縮できます（Javaで顕著に効きます）。","reasons":[{"l":"A","html":"レイヤーはデプロイパッケージの共通化・管理のための機能で、初期化時間の短縮を保証するものではありません。"},{"l":"B","html":"効果はありますが、常時ウォームな環境を確保する分の料金がかかり「コストが見合わない」という前提に反します。"},{"l":"C","html":"タイムアウトは処理の上限時間で、起動の遅延とは無関係です。"}],"refs":"<a href=\"#compute\" data-go=\"compute\">第1章 1.6 AWS Lambda</a> ／ <a href=\"#d3\" data-go=\"d3\">第13章 13.2 コンピューティングとパフォーマンス</a>"},{"n":7,"topic":"API Gatewayの種別","level":2,"body":["モバイルアプリ向けのシンプルなプロキシAPI（Lambda統合のみ）を新規に公開します。要件は<b>可能な限り低コスト・低レイテンシ</b>で、APIキーや使用量プラン、リクエスト検証、レスポンスキャッシュは不要です。適切な選択はどれですか。"],"options":[{"l":"A","html":"HTTP APIを作成する"},{"l":"B","html":"REST APIを作成し、キャッシュを無効化する"},{"l":"C","html":"WebSocket APIを作成する"},{"l":"D","html":"Application Load BalancerにLambdaを直接登録する"}],"answer":["A"],"multi":false,"req":"","key":"<b>HTTP APIはREST APIより安価で低レイテンシ</b>な代わりに機能が絞られています。設問は「絞られた機能が不要」と明示しているため、HTTP APIが最適です。","reasons":[{"l":"B","html":"REST APIは高機能ですが、使わない機能の分だけ単価が高くなります。"},{"l":"C","html":"WebSocketは双方向通信用で、リクエスト・レスポンス型のAPIには適しません。"},{"l":"D","html":"ALBは時間課金が常時発生し、APIとしての認証・スロットリングなどの機能も別途必要になります。"}],"refs":"<a href=\"#others\" data-go=\"others\">第10章 10.1 Amazon API Gateway</a>"},{"n":8,"topic":"メッセージング基盤","level":2,"body":["オンプレミスで稼働する社内システム群が、<b>Apache ActiveMQ（JMS／AMQP）</b>を介して連携しています。この仕組みをAWSへ移行しますが、<b>アプリケーションのコードは変更できません</b>。適切なサービスはどれですか。"],"options":[{"l":"A","html":"Amazon MQ"},{"l":"B","html":"Amazon SNS"},{"l":"C","html":"Amazon SQS"},{"l":"D","html":"Amazon Kinesis Data Streams"}],"answer":["A"],"multi":false,"req":"","key":"<b>既存のJMS／AMQPなど標準プロトコルのアプリをコード変更なしで移行するならAmazon MQ</b>（ActiveMQ／RabbitMQのマネージド版）です。新規開発ならSQS/SNSを選びます。","reasons":[{"l":"B","html":"SNSもAWS独自のPub/Subで、プロトコル互換性がありません。"},{"l":"C","html":"SQSはAWS独自のAPIで、JMSクライアントからそのまま利用することはできません（コード変更が必要）。"},{"l":"D","html":"Kinesisはストリーミングデータの取り込み基盤で、メッセージブローカーの置き換えではありません。"}],"refs":"<a href=\"#integration\" data-go=\"integration\">第6章 6.5 Amazon MQ</a> ／ <a href=\"#cmp\" data-go=\"cmp\">付録A アプリケーション統合</a>"},{"n":9,"topic":"通知の振り分け","level":3,"body":["1つのSNSトピックに、注文イベント（<code>type=order</code>）と在庫イベント（<code>type=stock</code>）の両方が発行されています。在庫管理チームのキューには<b>在庫イベントだけ</b>を届けたいと考えています。アプリケーションの発行側は変更できません。適切な方法はどれですか。"],"options":[{"l":"A","html":"トピックを用途ごとに分割し、発行側で送り分ける"},{"l":"B","html":"在庫チームのキュー側で、不要なメッセージを受信後に破棄する"},{"l":"C","html":"在庫チーム用のサブスクリプションに、メッセージ属性に基づくフィルターポリシーを設定する"},{"l":"D","html":"SQSの可視性タイムアウトを調整する"}],"answer":["C"],"multi":false,"req":"","key":"<b>SNSのフィルターポリシーは、サブスクリプションごとにメッセージ属性で配信を絞り込みます</b>。発行側に手を入れずに、必要な通知だけを届けられます。","reasons":[{"l":"A","html":"発行側の変更が必要で、「発行側は変更できない」という前提に反します。"},{"l":"B","html":"不要なメッセージも配信・受信されるため、リクエスト料金と処理の無駄が残ります。"},{"l":"D","html":"可視性タイムアウトは処理中の再配信を防ぐ設定で、配信内容の絞り込みとは無関係です。"}],"refs":"<a href=\"#integration\" data-go=\"integration\">第6章 6.2 Amazon SNS</a>"},{"n":10,"topic":"起動の遅いワークロード","level":3,"body":["Auto Scalingグループで使うAMIは、アプリケーションの初期化に<b>約5分</b>かかります。トラフィックの増加は毎朝ほぼ同じ時間帯に起こりますが、スケールアウトが間に合わず、その間エラー率が上がります。<b>適切な対策を2つ選択してください。</b>"],"options":[{"l":"A","html":"ウォームプールを構成し、初期化済みのインスタンスを待機状態で確保しておく"},{"l":"B","html":"ヘルスチェックの猶予期間（グレースピリオド）を0秒に短縮する"},{"l":"C","html":"予測スケーリングを有効にし、需要の増加前に容量を追加する"},{"l":"D","html":"Auto Scalingグループの最大容量を2倍に引き上げる"},{"l":"E","html":"スケールイン時のクールダウンを延長する"}],"answer":["A","C"],"multi":true,"req":"","key":"<b>起動に時間がかかる</b>ことが原因なので、対処は「<b>あらかじめ用意しておく（ウォームプール）</b>」か「<b>早めに増やし始める（予測スケーリング）</b>」のどちらかです。","reasons":[{"l":"B","html":"グレースピリオドを短くすると、初期化中のインスタンスが異常と判定されて置き換えられ、状況が悪化します。"},{"l":"D","html":"最大容量は上限値であり、起動の遅さ（立ち上がりの時間）は変わりません。"},{"l":"E","html":"スケールインのクールダウンは縮小の頻度を抑える設定で、スケールアウトの遅れには効きません。"}],"refs":"<a href=\"#compute\" data-go=\"compute\">第1章 1.2 EC2 Auto Scaling</a> ／ <a href=\"#d2\" data-go=\"d2\">第12章 12.1 スケーリング戦略</a>"}]},{"id":"exam-set-11","file":"set-11.md","num":"問題セット11","title":"頻出⑤：データベースと分析の細目","questions":[{"n":1,"topic":"Aurora","level":3,"body":["Aurora MySQLで、開発者が誤って本番テーブルの大量の行を削除してしまいました。<b>5分前の状態に、できるだけ短時間で戻す</b>必要があります。スナップショットからの復元では新しいクラスターの作成に時間がかかりすぎます。適切な方法はどれですか。"],"options":[{"l":"A","html":"バイナリログから手動でリカバリする"},{"l":"B","html":"ポイントインタイムリカバリで新しいクラスターへ復元する"},{"l":"C","html":"リードレプリカを昇格させる"},{"l":"D","html":"Auroraバックトラックで、指定した時刻までクラスターを巻き戻す"}],"answer":["D"],"multi":false,"req":"","key":"<b>バックトラックは「復元」ではなく「巻き戻し」</b>です。新しいクラスターを作らずに、同じクラスターを指定時刻の状態へ短時間で戻せます（Aurora MySQL互換の機能で、事前に有効化と保持期間の設定が必要です）。","reasons":[{"l":"A","html":"手動リカバリは時間も難度も高く、運用手段として適切ではありません。"},{"l":"B","html":"PITRは新しいクラスターを作成するため時間がかかり、「短時間で」という要件に合いません。"},{"l":"C","html":"リードレプリカは削除操作も複製済みのため、昇格しても失われた行は戻りません。"}],"refs":"<a href=\"#database\" data-go=\"database\">第4章 4.2 Amazon Aurora</a>"},{"n":2,"topic":"Aurora","level":2,"body":["本番のAuroraクラスター（データ量2 TB）と同じデータで、性能試験を行う検証環境を用意します。要件は (1) <b>短時間で用意</b>できること、(2) ストレージコストを抑えること、(3) 本番に影響を与えないこと、の3つです。適切な方法はどれですか。"],"options":[{"l":"A","html":"Auroraの高速データベースクローンを作成する"},{"l":"B","html":"スナップショットを取得し、新しいクラスターへ復元する"},{"l":"C","html":"リードレプリカを追加し、検証用に使う"},{"l":"D","html":"mysqldumpでエクスポートし、別クラスターへインポートする"}],"answer":["A"],"multi":false,"req":"","key":"<b>高速クローンはコピーオンライト方式</b>で、データを複製せずに即座に別クラスターを作れます。<b>変更された分だけストレージが増える</b>ためコストも抑えられます。","reasons":[{"l":"B","html":"2 TBの復元には時間がかかり、ストレージも丸ごと複製されます。"},{"l":"C","html":"レプリカは本番クラスターの一部であり、性能試験の負荷が本番へ影響します（要件3に反する）。"},{"l":"D","html":"エクスポート・インポートは最も時間がかかり、本番への負荷もかかります。"}],"refs":"<a href=\"#database\" data-go=\"database\">第4章 4.2 Amazon Aurora</a>"},{"n":3,"topic":"RDSの運用","level":3,"body":["Amazon RDS for PostgreSQLの<b>メジャーバージョンアップ</b>を実施します。要件は (1) 本番と同じ構成で事前に検証する、(2) 切り替えのダウンタイムを<b>数分以内</b>に抑える、(3) 問題があれば元に戻せる、の3つです。適切な方法はどれですか。"],"options":[{"l":"A","html":"スナップショットから新バージョンのインスタンスを復元し、アプリの接続先を変更する"},{"l":"B","html":"メンテナンスウィンドウでインプレースアップグレードを実行する"},{"l":"C","html":"RDS Blue/Greenデプロイを使い、緑環境で検証してから切り替える"},{"l":"D","html":"リードレプリカを新バージョンで作成し、昇格させる"}],"answer":["C"],"multi":false,"req":"","key":"<b>Blue/Greenデプロイは本番の複製（緑）を作り、継続的に同期しながら検証</b>でき、切り替えは通常1分程度です。切り戻しも容易で、3要件すべてに合致します。","reasons":[{"l":"A","html":"復元時点以降の差分が失われ、ダウンタイムも長くなります。"},{"l":"B","html":"インプレースはダウンタイムが長く、事前検証も切り戻しも困難です。"},{"l":"D","html":"クロスバージョンのレプリカ構成は制約が多く、検証と切り戻しの枠組みも自前で用意する必要があります。"}],"refs":"<a href=\"#database\" data-go=\"database\">第4章 4.1 Amazon RDS</a>"},{"n":4,"topic":"DBの性能分析","level":2,"body":["RDSインスタンスで、特定の時間帯にだけ応答が遅くなります。<b>どのSQLがどの待機イベントで時間を消費しているか</b>を特定したいと考えています。適切な機能はどれですか。"],"options":[{"l":"A","html":"CloudWatchの標準メトリクス（CPUUtilization、DatabaseConnections）"},{"l":"B","html":"Performance Insights"},{"l":"C","html":"拡張モニタリング（Enhanced Monitoring）"},{"l":"D","html":"VPCフローログ"}],"answer":["B"],"multi":false,"req":"","key":"<b>Performance Insightsはデータベースの負荷（DBロード）を待機イベントと上位SQL単位で可視化</b>します。「どのクエリが原因か」を突き止める機能です。","reasons":[{"l":"A","html":"標準メトリクスは「遅い」という事実までは分かっても、原因のSQLは特定できません。"},{"l":"C","html":"拡張モニタリングはOSレベルの指標（プロセスごとのCPU・メモリなど）で、SQL単位の分析はできません。"},{"l":"D","html":"フローログはネットワーク通信の記録で、DB内部の待機とは無関係です。"}],"refs":"<a href=\"#database\" data-go=\"database\">第4章 4.1 Amazon RDS</a> ／ <a href=\"#d3\" data-go=\"d3\">第13章 13.3 データベースとパフォーマンス</a>"},{"n":5,"topic":"キャパシティ計算","level":3,"body":["DynamoDBテーブルで、<b>1項目あたり6 KB</b>の項目を<b>毎秒80回、結果整合性のある読み取り</b>で取得します。プロビジョニングすべき読み取りキャパシティユニット（RCU）はいくつですか。"],"options":[{"l":"A","html":"40 RCU"},{"l":"B","html":"80 RCU"},{"l":"C","html":"160 RCU"},{"l":"D","html":"240 RCU"}],"answer":["B"],"multi":false,"req":"","key":"手順は3段階です。<b>①項目サイズを4 KB単位に切り上げる</b>（6 KB → 2 単位）。<b>②強い整合性なら 2 RCU／回</b>。<b>③結果整合性はその半分</b>なので 1 RCU／回。これを毎秒80回なので <b>80 RCU</b> です。","reasons":[{"l":"A","html":"さらに半分にした値です。結果整合性の割引を二重に適用しています。"},{"l":"C","html":"強い整合性で計算した場合の値（2 × 80）です。設問は結果整合性です。"},{"l":"D","html":"項目サイズの切り上げを誤り、3単位（6 KB ÷ 4 KB を3と数える）として計算した場合の値です。"}],"refs":"<a href=\"#database\" data-go=\"database\">第4章 4.3 Amazon DynamoDB</a> ／ <a href=\"#kw\" data-go=\"kw\">付録B 主要な数値クォータ</a>"},{"n":6,"topic":"インメモリDB","level":3,"body":["リアルタイム入札システムで、<b>マイクロ秒台の読み書き</b>が必要です。加えて、扱うデータは<b>障害時に失われてはならず</b>、このデータストア自体がプライマリのデータベースとして機能する必要があります。適切なサービスはどれですか。"],"options":[{"l":"A","html":"Amazon MemoryDB"},{"l":"B","html":"Amazon ElastiCache for Redis（クラスターモード有効）"},{"l":"C","html":"Amazon DynamoDB Accelerator（DAX）"},{"l":"D","html":"Amazon ElastiCache for Memcached"}],"answer":["A"],"multi":false,"req":"","key":"<b>MemoryDBはRedis互換でありながら、マルチAZのトランザクションログにより耐久性を持つ</b>ため、キャッシュではなく<b>プライマリDBとして</b>使えます。","reasons":[{"l":"B","html":"ElastiCacheは基本的にキャッシュ層で、永続化の仕組みはあるものの、プライマリDBとしての耐久性保証は目的が異なります。"},{"l":"C","html":"DAXはDynamoDBの前段に置くキャッシュで、単体のデータベースではありません。"},{"l":"D","html":"Memcachedは永続化もレプリケーションもなく、要件から最も遠い選択肢です。"}],"refs":"<a href=\"#database\" data-go=\"database\">第4章 4.4 Amazon ElastiCache</a> ／ <a href=\"#cmp\" data-go=\"cmp\">付録A データベース</a>"},{"n":7,"topic":"データウェアハウス","level":2,"body":["Amazon Redshiftで運用中のデータウェアハウスに加え、<b>S3に蓄積された過去5年分の生ログ</b>も分析対象にしたいという要望が出ました。ログをRedshiftへロードするとストレージが逼迫します。適切な方法はどれですか。"],"options":[{"l":"A","html":"ログをDynamoDBへ移し、Redshiftから参照する"},{"l":"B","html":"すべてのログをCOPYコマンドでRedshiftへロードする"},{"l":"C","html":"Redshift Spectrumで、S3上のデータを外部テーブルとして直接クエリする"},{"l":"D","html":"Redshiftクラスターのノード数を増やす"}],"answer":["C"],"multi":false,"req":"","key":"<b>Redshift SpectrumはS3のデータをロードせずに直接クエリ</b>できます。Redshift内のテーブルとの結合も可能で、ストレージを増やさずに分析範囲を広げられます。","reasons":[{"l":"A","html":"DynamoDBは大規模な分析クエリには向かず、構成も複雑になります。"},{"l":"B","html":"ストレージの逼迫という前提に反し、コストも増えます。"},{"l":"D","html":"ノード追加はコスト増であり、S3のデータを扱えるようにする解決にはなりません。"}],"refs":"<a href=\"#analytics\" data-go=\"analytics\">第7章 7.4 Amazon Redshift</a>"},{"n":8,"topic":"データウェアハウス","level":2,"body":["Redshiftクラスターは日中は安定していますが、<b>毎朝9時にレポートクエリが集中</b>し、待ち行列が発生して結果が返るまで数十分かかります。それ以外の時間帯は余裕があります。適切な対処はどれですか。"],"options":[{"l":"A","html":"クラスターを常時2倍のノード数へリサイズする"},{"l":"B","html":"同時実行スケーリングを有効にして、混雑時に自動で処理能力を追加する"},{"l":"C","html":"すべてのレポートを夜間バッチへ移す"},{"l":"D","html":"クエリのタイムアウト値を延長する"}],"answer":["B"],"multi":false,"req":"","key":"<b>同時実行スケーリングは、混雑時だけ追加のクラスター容量を自動的に割り当てます</b>。ピークの短時間だけ能力を足せるため、常時増強よりコスト効率に優れます。","reasons":[{"l":"A","html":"ピーク以外の時間帯も課金され続け、コスト効率が悪化します。"},{"l":"C","html":"業務要件（朝のレポート）を変更する提案であり、技術的な解決になっていません。"},{"l":"D","html":"待ち時間が長くなるだけで、遅延そのものは解消しません。"}],"refs":"<a href=\"#analytics\" data-go=\"analytics\">第7章 7.4 Amazon Redshift</a> ／ <a href=\"#d4\" data-go=\"d4\">第14章 14.4 データベースのコスト最適化</a>"},{"n":9,"topic":"特化型データベース","level":3,"body":["3つの要件それぞれに最も適したデータベースの組み合わせはどれですか。","1. SNSの友人関係をたどり、「友人の友人」を数ホップ先まで高速に検索したい","2. 工場のセンサーが送る<b>時系列データ</b>を保存し、期間を指定した集計を高速に行いたい","3. 金融取引の履歴を、<b>変更不可能かつ暗号学的に検証可能</b>な形で記録したい"],"options":[{"l":"A","html":"1: Amazon Neptune ／ 2: Amazon Timestream ／ 3: Amazon QLDB"},{"l":"B","html":"1: Amazon DocumentDB ／ 2: Amazon Neptune ／ 3: Amazon Managed Blockchain"},{"l":"C","html":"1: Amazon Neptune ／ 2: Amazon DynamoDB ／ 3: Amazon DocumentDB"},{"l":"D","html":"1: Amazon Keyspaces ／ 2: Amazon Timestream ／ 3: Amazon QLDB"}],"answer":["A"],"multi":false,"req":"","key":"<b>関係をたどる＝Neptune（グラフ）／時系列＝Timestream／改ざん不可能な台帳＝QLDB</b>。用途特化型DBは、キーワードとサービスが1対1で対応します。","reasons":[{"l":"B","html":"DocumentDBはMongoDB互換のドキュメントDB、Managed Blockchainは<b>複数組織が対等に検証する</b>分散台帳で、単一所有者の台帳にはQLDBが適します。"},{"l":"C","html":"DynamoDBでも時系列データは扱えますが、期間集計に最適化されたTimestreamが要件に合致します。DocumentDBに改ざん検証の仕組みはありません。"},{"l":"D","html":"KeyspacesはCassandra互換で、グラフ探索の用途ではありません。"}],"refs":"<a href=\"#database\" data-go=\"database\">第4章 4.6 その他の特化型データベースサービス</a> ／ <a href=\"#cmp\" data-go=\"cmp\">付録A データベース</a>"},{"n":10,"topic":"DBの可用性","level":3,"body":["Amazon RDS for MySQLで、フェイルオーバー発生時に<b>アプリケーションが数分間エラーを返し続ける</b>ことが分かりました。原因は、アプリが古いエンドポイントのIPをキャッシュし続け、再接続の嵐でDBの接続数も枯渇するためです。<b>適切な対策を2つ選択してください。</b>"],"options":[{"l":"A","html":"マルチAZ配置を有効にする"},{"l":"B","html":"RDS Proxyを導入し、アプリケーションの接続先をプロキシのエンドポイントにする"},{"l":"C","html":"リードレプリカを追加する"},{"l":"D","html":"アプリケーション側でDNSのTTLを尊重し、接続プールの再接続とリトライ（指数バックオフ）を実装する"},{"l":"E","html":"インスタンスクラスを大きくする"}],"answer":["B","D"],"multi":true,"req":"","key":"<b>RDS Proxyは接続をプールし、フェイルオーバー時の切り替えをアプリに代わって吸収</b>します（接続の枯渇も防ぎます）。あわせて、<b>クライアント側のDNSキャッシュとリトライ設計</b>を直すのが定石です。","reasons":[{"l":"A","html":"マルチAZはフェイルオーバーを<b>起こせるようにする</b>前提条件で、設問はすでにフェイルオーバーが発生している状況です。切り替え後の接続問題は解決しません。"},{"l":"C","html":"リードレプリカは読み取りのスケール手段で、フェイルオーバー時の再接続には関係しません。"},{"l":"E","html":"インスタンスを大きくしても、DNSキャッシュや再接続の嵐という原因は残ります。"}],"refs":"<a href=\"#database\" data-go=\"database\">第4章 4.1 Amazon RDS</a> ／ <a href=\"#d2\" data-go=\"d2\">第12章 12.5 高可用性と耐障害性</a>"}]},{"id":"exam-set-12","file":"set-12.md","num":"問題セット12","title":"頻出⑥：セキュリティ運用・IaC・エッジ・AI","questions":[{"n":1,"topic":"証明書","level":2,"body":["CloudFrontディストリビューションに独自ドメインのHTTPS証明書を設定しようとしたところ、<b>ACMで発行済みの証明書が選択肢に表示されません</b>。証明書は東京リージョン（ap-northeast-1）で発行しています。適切な対処はどれですか。"],"options":[{"l":"A","html":"AWS Private CAで証明書を再発行する"},{"l":"B","html":"CloudFrontのディストリビューションを東京リージョンで作り直す"},{"l":"C","html":"証明書をALBに関連付けてから、CloudFrontのオリジンをALBに変更する"},{"l":"D","html":"証明書をバージニア北部（us-east-1）で発行またはインポートし直す"}],"answer":["D"],"multi":false,"req":"","key":"<b>CloudFrontで使うACM証明書は、バージニア北部（us-east-1）である必要があります</b>（CloudFrontがグローバルサービスのため）。ALB用は、そのALBと同じリージョンで発行します。","reasons":[{"l":"A","html":"Private CAは社内向けのプライベート証明書用で、一般の利用者が検証できる公開証明書にはなりません。"},{"l":"B","html":"CloudFrontはグローバルサービスで、リージョンを指定して作成するものではありません。"},{"l":"C","html":"ALBに証明書を付けても、CloudFrontのビューア向け証明書の要件（us-east-1）は変わりません。"}],"refs":"<a href=\"#security\" data-go=\"security\">第5章 5.7 AWS Certificate Manager</a> ／ <a href=\"#network\" data-go=\"network\">第3章 3.6 CloudFrontとGlobal Accelerator</a>"},{"n":2,"topic":"DDoS対策","level":3,"body":["大規模なキャンペーンを控え、DDoS攻撃への備えを強化します。要件は (1) 攻撃中に<b>AWSの専門チームの支援</b>を受けられる、(2) 攻撃に起因して急増したスケーリング費用の<b>補償</b>を受けられる、(3) L7の攻撃にも対応する、の3つです。適切な選択はどれですか。"],"options":[{"l":"A","html":"AWS Shield Advanced を契約する"},{"l":"B","html":"AWS Shield Standard を有効化する"},{"l":"C","html":"AWS WAFのレートベースルールのみを設定する"},{"l":"D","html":"Network Firewallを導入する"}],"answer":["A"],"multi":false,"req":"","key":"<b>SRT（Shield Response Team）の支援と、DDoSに起因するスケーリング費用の補償はShield Advancedの機能</b>です。要件(1)(2)が出たら即決できます。","reasons":[{"l":"B","html":"StandardはすべてのAWS利用者に自動適用される基本的なL3/L4防御で、専門チームの支援や費用補償はありません。"},{"l":"C","html":"WAFは有効な対策ですが、単体では支援体制や費用補償は付きません。"},{"l":"D","html":"Network FirewallはVPCのトラフィック検査用で、大規模DDoSの緩和を担う製品ではありません。"}],"refs":"<a href=\"#security\" data-go=\"security\">第5章 5.6 AWS Shield</a> ／ <a href=\"#d1\" data-go=\"d1\">第11章 11.3 多層防御</a>"},{"n":3,"topic":"検出から対応まで","level":3,"body":["GuardDutyが「EC2インスタンスが既知のマルウェア配布元と通信している」という検出結果を出したとき、<b>人手を介さずに自動で当該インスタンスを隔離</b>したいと考えています。適切な構成はどれですか。"],"options":[{"l":"A","html":"GuardDutyの検出結果をCloudTrailに記録し、定期的に確認する"},{"l":"B","html":"GuardDutyの検出結果をEventBridgeルールで受け、Lambdaで隔離用セキュリティグループへ付け替える"},{"l":"C","html":"AWS Configルールで、GuardDutyの検出結果を評価して修復する"},{"l":"D","html":"Security Hubで検出結果を集約し、担当者へメール通知する"}],"answer":["B"],"multi":false,"req":"","key":"<b>検出（GuardDuty）→ 振り分け（EventBridge）→ 対応（Lambda／SSM Automation）</b>が自動対応の定型パターンです。","reasons":[{"l":"A","html":"CloudTrailはAPI操作の記録であり、検出結果の保存先でも自動対応の仕組みでもありません。"},{"l":"C","html":"Configが評価するのは<b>リソースの設定</b>で、GuardDutyの検出結果を入力とする仕組みではありません。"},{"l":"D","html":"集約と通知までで、<b>自動で隔離する</b>という要件を満たしません。"}],"refs":"<a href=\"#security\" data-go=\"security\">第5章 5.11 Amazon GuardDuty</a> ／ <a href=\"#integration\" data-go=\"integration\">第6章 6.3 Amazon EventBridge</a>"},{"n":4,"topic":"IaC","level":3,"body":["CloudFormationで構築した検証環境を削除する際、<b>RDSインスタンスのデータだけは残したい</b>（またはスナップショットとして保全したい）と考えています。適切な方法はどれですか。"],"options":[{"l":"A","html":"スタックを削除する前に、RDSに削除保護を設定する"},{"l":"B","html":"テンプレートのRDSリソースに <code>DeletionPolicy: Snapshot</code>（または <code>Retain</code>）を指定する"},{"l":"C","html":"スタックポリシーで、RDSリソースの更新を拒否する"},{"l":"D","html":"スタックを削除せず、手動でリソースを1つずつ削除する"}],"answer":["B"],"multi":false,"req":"","key":"<b>DeletionPolicy はスタック削除時のリソースの扱いを指定</b>します。<code>Snapshot</code> はスナップショットを残して削除、<code>Retain</code> はリソースを残します。データ消失事故を防ぐ定番の設定です。","reasons":[{"l":"A","html":"削除保護が有効だとスタックの削除自体が失敗し、中途半端な状態になります（データ保全の仕組みではありません）。"},{"l":"C","html":"スタックポリシーは<b>更新時</b>の保護で、削除時の挙動は制御しません。"},{"l":"D","html":"手動削除はスタックとの整合性が崩れ、再現性も失われます。"}],"refs":"<a href=\"#management\" data-go=\"management\">第8章 8.3 AWS CloudFormation</a>"},{"n":5,"topic":"障害情報","level":2,"body":["あるリージョンで自社システムに断続的な障害が出ています。<b>AWS側のサービス障害やメンテナンスが、自分のアカウントのリソースに影響していないか</b>を確認したいと考えています。適切なサービスはどれですか。"],"options":[{"l":"A","html":"AWS Health Dashboard（アカウント固有のイベントを含む）"},{"l":"B","html":"Amazon CloudWatch の標準メトリクス"},{"l":"C","html":"AWS Trusted Advisor"},{"l":"D","html":"AWS CloudTrail"}],"answer":["A"],"multi":false,"req":"","key":"<b>AWS側の障害・メンテナンス・自分のリソースへの影響を知らせるのがHealth Dashboard</b>です。EventBridgeと連携して自動通知もできます。","reasons":[{"l":"B","html":"CloudWatchは自分のリソースの状態を示すもので、AWS基盤側の障害情報は扱いません。"},{"l":"C","html":"Trusted Advisorはベストプラクティスの点検で、障害情報の通知はしません。"},{"l":"D","html":"CloudTrailは自分のアカウントでのAPI操作の記録です。"}],"refs":"<a href=\"#management\" data-go=\"management\">第8章 8.8 その他の管理、監視、ガバナンスサービス</a>"},{"n":6,"topic":"AIサービス","level":2,"body":["3つの要件に最も適したサービスの組み合わせはどれですか。","1. スキャンした<b>請求書PDFから、表とフォームの項目を構造化データとして</b>抽出したい","2. コールセンターの<b>通話音声を文字起こし</b>したい","3. 文字起こしした内容から<b>苦情かどうかの感情</b>を判定したい"],"options":[{"l":"A","html":"1: Amazon Comprehend ／ 2: Amazon Transcribe ／ 3: Amazon Textract"},{"l":"B","html":"1: Amazon Rekognition ／ 2: Amazon Polly ／ 3: Amazon Translate"},{"l":"C","html":"1: Amazon Textract ／ 2: Amazon Transcribe ／ 3: Amazon Comprehend"},{"l":"D","html":"1: Amazon Textract ／ 2: Amazon Polly ／ 3: Amazon Comprehend"}],"answer":["C"],"multi":false,"req":"","key":"<b>入力の種類で一意に決まります</b>。文書＝Textract（単なるOCRではなく表・フォームの構造化）、音声→テキスト＝Transcribe、テキストの意味・感情＝Comprehend。","reasons":[{"l":"A","html":"ComprehendとTextractの役割が入れ替わっています。"},{"l":"B","html":"Rekognitionは画像・動画、Pollyは<b>テキスト→音声</b>（向きが逆）、Translateは翻訳です。"},{"l":"D","html":"Pollyは読み上げであり、音声の文字起こしはできません。"}],"refs":"<a href=\"#others\" data-go=\"others\">第10章 10.3〜10.8 機械学習・AIサービス</a>"},{"n":7,"topic":"メール送信","level":2,"body":["ECサイトから、<b>注文確認メールを1日あたり10万通</b>送信します。HTMLメールのテンプレート管理と、バウンス率・苦情率の把握が必要です。適切なサービスはどれですか。"],"options":[{"l":"A","html":"Amazon SES"},{"l":"B","html":"Amazon SNSのEメールサブスクリプション"},{"l":"C","html":"Amazon Pinpoint のプッシュ通知"},{"l":"D","html":"Amazon WorkMail"}],"answer":["A"],"multi":false,"req":"","key":"<b>大量のトランザクションメール送信はSES</b>です。テンプレート、配信統計（バウンス・苦情）、専用IPなどの機能を備えます。","reasons":[{"l":"B","html":"SNSのEメールは運用通知向けで、<b>購読者による購読確認が必要</b>なうえHTMLテンプレートも使えません。顧客向けの大量送信には適しません。"},{"l":"C","html":"Pinpointはキャンペーン配信やセグメント配信の基盤で、プッシュ通知は今回の要件と異なります（メール送信自体はSESの仕組みを使います）。"},{"l":"D","html":"WorkMailは社内向けのメールボックスサービスです。"}],"refs":"<a href=\"#others\" data-go=\"others\">第10章 10.2 フロントエンド・モバイル向けサービス</a>"},{"n":8,"topic":"エッジロケーション","level":3,"body":["3つの要件に最も適したサービスの組み合わせはどれですか。","1. 法規制により、<b>データを自社データセンターの外に出せない</b>が、AWSのAPIで運用したい","2. 都市部の利用者へ、<b>一桁ミリ秒</b>のレイテンシで動画編集アプリを提供したい","3. <b>5G回線のモバイル端末</b>に対し、超低遅延で推論結果を返したい"],"options":[{"l":"A","html":"1: AWS Outposts ／ 2: Amazon CloudFront ／ 3: AWS Local Zones"},{"l":"B","html":"1: AWS Local Zones ／ 2: AWS Outposts ／ 3: Amazon CloudFront"},{"l":"C","html":"1: AWS Outposts ／ 2: AWS Local Zones ／ 3: AWS Wavelength"},{"l":"D","html":"1: AWS Snowball Edge ／ 2: AWS Wavelength ／ 3: AWS Local Zones"}],"answer":["C"],"multi":false,"req":"","key":"<b>自社DC内＝Outposts／大都市圏の一桁ミリ秒＝Local Zones／5Gキャリア網＝Wavelength</b>。3つは設置場所で区別します。","reasons":[{"l":"A","html":"CloudFrontはコンテンツ配信のキャッシュで、アプリケーションの実行環境ではありません。"},{"l":"B","html":"1と2が逆です。Local Zonesは自社データセンターではなくAWSが運営する小規模拠点です。"},{"l":"D","html":"Snowball Edgeは一時的な現場処理やデータ移送用で、常設の低遅延基盤ではありません。"}],"refs":"<a href=\"#compute\" data-go=\"compute\">第1章 1.4 AWS Outposts</a> ／ <a href=\"#cmp\" data-go=\"cmp\">付録A ネットワーク</a>"},{"n":9,"topic":"サーバー移行","level":2,"body":["オンプレミスで稼働する<b>200台の仮想サーバー</b>をAWSへ移行します。要件は (1) アプリケーションを書き換えずそのまま移す、(2) 切り替え時のダウンタイムを<b>数分</b>に抑える、(3) 移行前に各サーバーの依存関係と使用状況を把握する、の3つです。適切な組み合わせはどれですか。"],"options":[{"l":"A","html":"各サーバーのAMIを手動で作成し、順次起動する"},{"l":"B","html":"AWS DataSync で仮想ディスクをコピーし、EC2で起動する"},{"l":"C","html":"AWS Database Migration Service (DMS) で移行する"},{"l":"D","html":"AWS Application Discovery Service で調査し、AWS Application Migration Service (MGN) で移行する"}],"answer":["D"],"multi":false,"req":"","key":"<b>リフト＆シフト＝MGN</b>（ブロックレベルの継続的複製でダウンタイムを最小化）、<b>移行前の資産調査＝Application Discovery Service</b>。移行の定型セットです。","reasons":[{"l":"A","html":"200台を手作業で扱うのは非現実的で、ダウンタイムも長くなります。"},{"l":"B","html":"DataSyncはファイル転送サービスで、稼働中サーバーの継続的複製やカットオーバーの仕組みはありません。"},{"l":"C","html":"DMSはデータベースの移行ツールで、サーバー全体の移行には使いません。"}],"refs":"<a href=\"#others\" data-go=\"others\">第10章 10.15 その他の移行サービス</a>"},{"n":10,"topic":"コストの監視","level":2,"body":["先月、設定ミスにより特定サービスの利用料が通常の10倍に膨らみ、月末の請求で初めて気づきました。<b>早期に気づける仕組み</b>を用意します。<b>適切な対策を2つ選択してください。</b>"],"options":[{"l":"A","html":"AWS Cost and Usage Report をS3へ出力する設定を有効にする"},{"l":"B","html":"すべてのリソースにコスト配分タグを付与する"},{"l":"C","html":"AWS Cost Anomaly Detection を設定し、異常な支出パターンを検知したら通知する"},{"l":"D","html":"Cost Explorer で毎月末にレポートを確認する運用を定める"},{"l":"E","html":"AWS Budgets で予算と<b>予測超過</b>のしきい値を設定し、アラートを受け取る"}],"answer":["C","E"],"multi":true,"req":"","key":"<b>気づく仕組み＝能動的に通知が飛ぶもの</b>です。Cost Anomaly Detectionは機械学習で異常を検知し、Budgetsはしきい値（実績・予測）超過で通知します。","reasons":[{"l":"A","html":"CURは詳細データの出力であり、それ自体は通知しません（分析の材料です）。"},{"l":"B","html":"タグは可視化・配賦の前提として有用ですが、単体では異常を知らせません。"},{"l":"D","html":"月末の確認では「請求で初めて気づく」という現状と大差ありません。"}],"refs":"<a href=\"#d4\" data-go=\"d4\">第14章 14.1 コスト管理ツールの使い分け</a> ／ <a href=\"#others\" data-go=\"others\">第10章 10.9〜10.11 コスト管理サービス</a>"}]},{"id":"exam-set-13","file":"set-13.md","num":"問題セット13","title":"第1分野 2周目：セキュアなアーキテクチャの設計","questions":[{"n":1,"topic":"IAMロール","level":3,"body":["別アカウントの開発者が<code>sts:AssumeRole</code>を実行したところ、<code>AccessDenied</code>が返りました。ロールにはS3への必要な権限がアタッチされており、開発者側のIAMユーザーにも<code>sts:AssumeRole</code>が許可されています。次に確認すべき設定はどれですか。"],"options":[{"l":"A","html":"S3バケットのバケットポリシー"},{"l":"B","html":"ロールにアタッチされた権限ポリシーのS3アクション"},{"l":"C","html":"ロールの<b>信頼ポリシー</b>に、相手アカウント（またはプリンシパル）が許可されているか"},{"l":"D","html":"ロールの最大セッション時間"}],"answer":["C"],"multi":false,"req":"","key":"IAMロールには2種類のポリシーがあります。<b>信頼ポリシー（誰が引き受けられるか）</b>と<b>権限ポリシー（引き受けた後に何ができるか）</b>。<code>AssumeRole</code>自体が拒否されている＝<b>引き受けの段階</b>なので、信頼ポリシーを確認します。","reasons":[{"l":"A","html":"バケットポリシーはS3操作時の認可で、<code>AssumeRole</code>の失敗とは別の層です。"},{"l":"B","html":"権限ポリシーは引き受けた<b>後</b>に効くもので、引き受けの可否には影響しません。"},{"l":"D","html":"セッション時間は有効期限の設定で、引き受けの可否を左右しません。"}],"refs":"<a href=\"#security\" data-go=\"security\">第5章 5.1 AWS IAM</a> ／ <a href=\"#d1\" data-go=\"d1\">第11章 11.1 アクセス管理</a>"},{"n":2,"topic":"条件キー","level":3,"body":["S3バケットへのアクセスを、<b>特定のVPCエンドポイント経由のリクエストだけ</b>に限定したいと考えています。インターネット経由や他のVPCからのアクセスは、たとえ正しいIAM権限を持っていても拒否する必要があります。適切な方法はどれですか。"],"options":[{"l":"A","html":"IAMポリシーに <code>aws:SourceIp</code> 条件を追加する"},{"l":"B","html":"セキュリティグループで、S3のIPレンジ以外を拒否する"},{"l":"C","html":"バケットポリシーで、<code>aws:SourceVpce</code> が対象のエンドポイントIDと一致しない場合に Deny する"},{"l":"D","html":"バケットのブロックパブリックアクセスを有効化する"}],"answer":["C"],"multi":false,"req":"","key":"<b>リソース側（バケットポリシー）の条件キーで経路を縛る</b>のが定石です。<code>aws:SourceVpce</code>（エンドポイントID）や<code>aws:SourceVpc</code>（VPC ID）を使い、条件に合わない場合は明示的に拒否します。","reasons":[{"l":"A","html":"<code>aws:SourceIp</code>はVPCエンドポイント経由のリクエストには一致しません（プライベート経路のため）。"},{"l":"B","html":"セキュリティグループはENI単位の制御で、S3側で「どの経路から来たか」を判定するものではありません。"},{"l":"D","html":"ブロックパブリックアクセスは公開設定を防ぐ機能で、経路の限定はできません。"}],"refs":"<a href=\"#storage\" data-go=\"storage\">第2章 2.1 Amazon S3</a> ／ <a href=\"#d1\" data-go=\"d1\">第11章 11.1 アクセス管理</a>"},{"n":3,"topic":"権限の委譲","level":3,"body":["各開発チームのリーダーに、自チーム用のIAMロール作成を任せることになりました。ただし、**リーダーが自分やチームに管理者権限（<code>*:*</code>）を与えられてはなりません**。適切な仕組みはどれですか。"],"options":[{"l":"A","html":"リーダーのIAMユーザーに管理者ポリシーをアタッチし、運用ルールで制限する"},{"l":"B","html":"CloudTrailでロール作成を監視し、事後にレビューする"},{"l":"C","html":"AWS Configルールで、作成後に管理者権限のロールを検出して削除する"},{"l":"D","html":"作成されるIAMエンティティに<b>アクセス許可境界（Permissions Boundary）</b>の付与を必須とする条件付きのポリシーをリーダーに与える"}],"answer":["D"],"multi":false,"req":"","key":"<b>アクセス許可境界は「そのIAMエンティティが持てる権限の上限」</b>を定めます。委譲する相手のポリシーに「境界を付けたエンティティしか作れない」という条件を入れるのが、権限委譲の標準パターンです。","reasons":[{"l":"A","html":"技術的な制限がなく、運用ルールだけでは防げません。"},{"l":"B","html":"CloudTrailは記録であり、予防にはなりません。"},{"l":"C","html":"Configは<b>事後の検出と修復</b>で、作成そのものを防げません（設問は予防を求めています）。"}],"refs":"<a href=\"#security\" data-go=\"security\">第5章 5.1 AWS IAM</a> ／ <a href=\"#d1\" data-go=\"d1\">第11章 11.1 アクセス管理</a>"},{"n":4,"topic":"公開状態の検出","level":2,"body":["監査に備え、<b>アカウント内のS3バケット・IAMロール・KMSキーなどが、組織外の第三者と共有されていないか</b>を継続的に洗い出したいと考えています。適切なサービスはどれですか。"],"options":[{"l":"A","html":"Amazon Macie"},{"l":"B","html":"IAM Access Analyzer"},{"l":"C","html":"Amazon Inspector"},{"l":"D","html":"AWS Trusted Advisor"}],"answer":["B"],"multi":false,"req":"","key":"<b>IAM Access Analyzerは、リソースポリシーを解析して「外部エンティティからアクセス可能なリソース」を検出</b>します。信頼ゾーン（アカウントまたは組織）の外部への共有を洗い出す専用の仕組みです。","reasons":[{"l":"A","html":"MacieはS3内の<b>データの中身</b>（個人情報など）を検出するサービスで、共有設定の解析はしません。"},{"l":"C","html":"Inspectorは脆弱性診断で、ポリシーの解析は行いません。"},{"l":"D","html":"Trusted Advisorにも公開バケットの点検項目はありますが、IAMロールやKMSキーまで含めたポリシー解析の網羅性ではAccess Analyzerが適切です。"}],"refs":"<a href=\"#security\" data-go=\"security\">第5章 5.1 AWS IAM</a> ／ <a href=\"#security\" data-go=\"security\">第5章 5.13 その他のセキュリティ・ガバナンスサービス</a>"},{"n":5,"topic":"KMSのクロスアカウント","level":3,"body":["アカウントAのKMSカスタマー管理キーで暗号化したS3オブジェクトを、アカウントBのIAMロールから読み取らせます。バケットポリシーではアカウントBに<code>s3:GetObject</code>を許可済みですが、取得時に<code>AccessDenied</code>になります。追加で必要な設定はどれですか。"],"options":[{"l":"A","html":"アカウントAの<b>KMSキーポリシー</b>でアカウントBに<code>kms:Decrypt</code>を許可し、アカウントB側のIAMポリシーでも同じ操作を許可する"},{"l":"B","html":"S3バケットのブロックパブリックアクセスを無効化する"},{"l":"C","html":"アカウントBでKMSキーを新規作成する"},{"l":"D","html":"オブジェクトの暗号化方式をSSE-S3に変更する"}],"answer":["A"],"multi":false,"req":"","key":"<b>KMSはキーポリシーが必須</b>です。クロスアカウントでは「<b>キー所有側のキーポリシーでの許可</b>」と「<b>利用側アカウントのIAMポリシーでの許可</b>」の<b>両方</b>が揃って初めて復号できます。","reasons":[{"l":"B","html":"公開設定とは無関係で、セキュリティを損なうだけです。"},{"l":"C","html":"別のキーを作っても、既存オブジェクトは元のキーで暗号化されているため復号できません。"},{"l":"D","html":"暗号化方式を変えるにはオブジェクトの再暗号化が必要で、監査要件がある場合はSSE-KMSを外せません。"}],"refs":"<a href=\"#security\" data-go=\"security\">第5章 5.8 AWS KMS</a> ／ <a href=\"#d1\" data-go=\"d1\">第11章 11.2 データ保護</a>"},{"n":6,"topic":"S3のデータ保護","level":3,"body":["S3バケットのデータ保護について、2つの要件があります。それぞれに適した機能はどれですか。","1. 運用担当者による<b>バージョンの完全削除</b>を防ぎたい（削除時にMFAを要求する）","2. 規制対応として、<b>指定期間は誰も上書き・削除できない</b>状態にしたい"],"options":[{"l":"A","html":"1: オブジェクトロック（ガバナンスモード） ／ 2: MFA削除"},{"l":"B","html":"1: MFA削除 ／ 2: オブジェクトロック（コンプライアンスモード）"},{"l":"C","html":"1: バージョニング ／ 2: ライフサイクルポリシー"},{"l":"D","html":"1: バケットポリシーのDeny ／ 2: レプリケーション"}],"answer":["B"],"multi":false,"req":"","key":"<b>MFA削除＝削除操作に追加認証を要求する運用上の歯止め</b>、<b>オブジェクトロックのコンプライアンスモード＝期間中は誰も（ルートユーザーでも）変更・削除できないWORM</b>。規制対応はオブジェクトロックです。","reasons":[{"l":"A","html":"役割が逆です。ガバナンスモードは特別な権限を持つ利用者が解除できるため、厳格な規制要件には足りません。"},{"l":"C","html":"バージョニングは上書き・削除からの復旧手段、ライフサイクルは移行と失効の自動化で、保護の強制力はありません。"},{"l":"D","html":"バケットポリシーは権限があれば変更でき、レプリケーションは複製であって保護ではありません。"}],"refs":"<a href=\"#storage\" data-go=\"storage\">第2章 2.1 Amazon S3</a> ／ <a href=\"#d1\" data-go=\"d1\">第11章 11.2 データ保護</a>"},{"n":7,"topic":"アプリの認証","level":3,"body":["モバイルアプリの利用者が、S3バケット内の<b>自分専用のフォルダ（プレフィックス）だけ</b>に読み書きできるようにします。利用者数は数十万人規模で、1人ずつIAMユーザーを作ることはできません。適切な構成はどれですか。"],"options":[{"l":"A","html":"事前署名URLを、利用者のアクセスのたびに手動で発行する"},{"l":"B","html":"すべての利用者で共有する1つのIAMユーザーのアクセスキーをアプリに埋め込む"},{"l":"C","html":"利用者ごとにS3バケットを作成し、バケットポリシーで制御する"},{"l":"D","html":"Cognito IDプールで一時認証情報を発行し、IAMポリシーの変数（<code>${cognito-identity.amazonaws.com:sub}</code>）でプレフィックスを限定する"}],"answer":["D"],"multi":false,"req":"","key":"<b>Cognito IDプールは認証済み利用者に一時認証情報を渡す</b>仕組みで、<b>ポリシー変数</b>を使えば「自分のIDに対応するプレフィックスのみ」という制御が1つのポリシーで実現できます。","reasons":[{"l":"A","html":"手動発行は運用が破綻します（バックエンドで自動発行する設計はあり得ますが、選択肢は「手動」です）。"},{"l":"B","html":"全利用者が同じ権限を持ち、キーの漏洩リスクも高く、利用者ごとの分離ができません。"},{"l":"C","html":"バケット数には上限があり、数十万人分の運用は現実的ではありません。"}],"refs":"<a href=\"#security\" data-go=\"security\">第5章 5.4 Amazon Cognito</a> ／ <a href=\"#d1\" data-go=\"d1\">第11章 11.1 アクセス管理</a>"},{"n":8,"topic":"通信の制御","level":3,"body":["VPC内のEC2インスタンスからの外部通信を、<b>許可されたドメイン名（FQDN）宛てだけに制限</b>したいと考えています。宛先IPアドレスは頻繁に変わるため、IPベースの制御では運用できません。適切なサービスはどれですか。"],"options":[{"l":"A","html":"AWS Network Firewall"},{"l":"B","html":"ネットワークACL"},{"l":"C","html":"セキュリティグループ"},{"l":"D","html":"AWS WAF"}],"answer":["A"],"multi":false,"req":"","key":"<b>ドメイン名（FQDN）単位のフィルタリングができるのはNetwork Firewall</b>です。SGとNACLはIPアドレスとポートでしか制御できません。","reasons":[{"l":"B","html":"NACLはIP／ポート／プロトコルによる制御で、ドメイン名は扱えません。"},{"l":"C","html":"セキュリティグループも同様で、宛先はIPかプレフィックスリスト（またはSG）で指定します。"},{"l":"D","html":"WAFは<b>受信するHTTPリクエスト</b>の検査で、EC2からの送信先の制御には使いません。"}],"refs":"<a href=\"#network\" data-go=\"network\">第3章 3.1 VPCの基礎</a> ／ <a href=\"#d1\" data-go=\"d1\">第11章 11.3 多層防御</a>"},{"n":9,"topic":"組織全体の統制","level":3,"body":["Organizationsで管理する40アカウントすべてに対し、<b>同一のAWS WAFルールを適用</b>し、<b>新しく作成されたアカウントにも自動的に適用</b>されるようにしたいと考えています。適切なサービスはどれですか。"],"options":[{"l":"A","html":"AWS Firewall Manager"},{"l":"B","html":"各アカウントでCloudFormation StackSetsを手動実行する"},{"l":"C","html":"AWS Config のコンフォーマンスパック"},{"l":"D","html":"Service Control Policy（SCP）"}],"answer":["A"],"multi":false,"req":"","key":"<b>Firewall Managerは、WAF・Shield Advanced・セキュリティグループ・Network Firewallのポリシーを組織全体へ一元適用</b>します。新規アカウントにも自動で適用される点が要件に合致します。","reasons":[{"l":"B","html":"StackSets自体は自動展開も可能ですが、WAFルールの準拠状態を継続的に強制・是正する仕組みは別途必要です。「手動実行」という選択肢の記述も要件に反します。"},{"l":"C","html":"Configは準拠状況の評価で、WAFルールそのものを配布・適用するサービスではありません。"},{"l":"D","html":"SCPは操作の許可範囲を制限するもので、リソース（WAFルール）を作成・配布することはできません。"}],"refs":"<a href=\"#security\" data-go=\"security\">第5章 5.13 その他のセキュリティ・ガバナンスサービス</a> ／ <a href=\"#management\" data-go=\"management\">第8章 8.5 AWS Organizations</a>"},{"n":10,"topic":"認証情報の保護","level":2,"body":["アプリケーションがRDSへ接続する際の認証について、<b>パスワードそのものを保持せず、IAMの権限で接続</b>したいと考えています。適切な方法はどれですか。"],"options":[{"l":"A","html":"EC2のユーザーデータにパスワードを記述する"},{"l":"B","html":"データベースのパスワードをAMIに埋め込む"},{"l":"C","html":"RDSのIAMデータベース認証を有効にし、一時的な認証トークンで接続する"},{"l":"D","html":"データベースのパスワードをS3バケットに保存し、起動時に取得する"}],"answer":["C"],"multi":false,"req":"","key":"<b>IAMデータベース認証は、IAMの権限に基づく短命なトークン（15分）で接続</b>する仕組みです。長期のパスワードをアプリ側に持たせずに済みます（ローテーションが必要なパスワード運用ならSecrets Managerを使います）。","reasons":[{"l":"A","html":"ユーザーデータはインスタンスメタデータから参照でき、平文での保持は危険です。"},{"l":"B","html":"AMIに機密情報を埋め込むと、AMIの共有やコピーを通じて漏洩します。"},{"l":"D","html":"S3に置いただけでは、取得のための認証・認可とローテーションの問題が残ります。"}],"refs":"<a href=\"#database\" data-go=\"database\">第4章 4.1 Amazon RDS</a> ／ <a href=\"#security\" data-go=\"security\">第5章 5.10 Secrets Manager vs Parameter Store</a>"},{"n":11,"topic":"脆弱性と設定の監査","level":2,"body":["監査で2つの指摘を受けました。それぞれに適したサービスはどれですか。","1. EC2インスタンスとコンテナイメージに、<b>既知の脆弱性（CVE）</b>が残っていないか継続的に確認すること","2. すべてのEBSボリュームが<b>暗号化されているか</b>を継続的に評価し、違反を記録すること"],"options":[{"l":"A","html":"1: AWS Config ／ 2: Amazon Inspector"},{"l":"B","html":"1: Amazon Inspector ／ 2: AWS Config"},{"l":"C","html":"1: Amazon GuardDuty ／ 2: AWS Trusted Advisor"},{"l":"D","html":"1: Amazon Macie ／ 2: AWS CloudTrail"}],"answer":["B"],"multi":false,"req":"","key":"<b>脆弱性（CVE）＝Inspector／リソース設定の準拠評価＝Config</b>。「ソフトウェアの欠陥」か「設定の状態」かで切り分けます。","reasons":[{"l":"A","html":"2つの役割が入れ替わっています。"},{"l":"C","html":"GuardDutyは振る舞いの検知、Trusted Advisorは広く浅い点検で、継続的な準拠評価の仕組みではありません。"},{"l":"D","html":"MacieはS3の機密データ検出、CloudTrailはAPI操作の記録です。"}],"refs":"<a href=\"#security\" data-go=\"security\">第5章 5.12 Amazon Inspector</a> ／ <a href=\"#management\" data-go=\"management\">第8章 8.7 AWS Config</a>"},{"n":12,"topic":"多層防御","level":3,"body":["公開Webアプリケーションのセキュリティを強化します。<b>構成として適切な対策を2つ選択してください。</b>"],"options":[{"l":"A","html":"CloudFrontにWeb ACLを関連付け、SQLインジェクションとレート超過を遮断する"},{"l":"B","html":"すべてのEC2インスタンスにパブリックIPを割り当て、SSHを社内IPに限定する"},{"l":"C","html":"アプリケーションサーバーをプライベートサブネットに配置し、ALB経由でのみ到達可能にする"},{"l":"D","html":"ネットワークACLですべてのアウトバウンドを拒否する"},{"l":"E","html":"ALBのセキュリティグループで、インバウンドを0.0.0.0/0の全ポートに開放する"}],"answer":["A","C"],"multi":true,"req":"","key":"多層防御は<b>エッジ（WAF）→ ネットワーク境界（サブネット分離）→ ホスト → データ</b>と層を重ねます。AとBはそれぞれ別の層を担い、両立します。","reasons":[{"l":"B","html":"パブリックIPの付与は攻撃面を広げます。運用接続はSession Managerで代替すべきです。"},{"l":"D","html":"アウトバウンドを全拒否するとパッチ取得やAPI呼び出しが不能になり、アプリケーションが動作しません。"},{"l":"E","html":"全ポート開放は必要最小限の原則に反します。開放するのは443（と必要なら80）だけです。"}],"refs":"<a href=\"#d1\" data-go=\"d1\">第11章 11.3 多層防御</a> ／ <a href=\"#security\" data-go=\"security\">第5章 5.5 AWS WAF</a>"}]},{"id":"exam-set-14","file":"set-14.md","num":"問題セット14","title":"第2分野 2周目：弾力性に優れたアーキテクチャの設計","questions":[{"n":1,"topic":"メッセージの順序","level":3,"body":["在庫更新の処理で、<b>同じ商品IDに対する更新は送信順に処理</b>される必要があります。一方、異なる商品IDどうしは並行に処理して構いません。スループットは毎秒200メッセージ程度です。適切な構成はどれですか。"],"options":[{"l":"A","html":"SQS FIFOキューを使い、すべてのメッセージに同じメッセージグループIDを設定する"},{"l":"B","html":"SQS標準キューを使い、受信側でタイムスタンプ順に並べ替える"},{"l":"C","html":"SQS FIFOキューを使い、<b>商品IDをメッセージグループID</b>に設定する"},{"l":"D","html":"SNSトピックにFIFOで発行し、Lambdaで処理する"}],"answer":["C"],"multi":false,"req":"","key":"<b>FIFOキューの順序保証はメッセージグループID単位</b>です。商品IDをグループIDにすると、同一商品内では順序が守られ、異なる商品は並行に処理できます。","reasons":[{"l":"A","html":"全メッセージを1グループにすると<b>並行処理ができなくなり</b>、スループットが大きく落ちます。"},{"l":"B","html":"標準キューは順序を保証しないため、受信側での並べ替えには到着待ちのバッファが必要になり、設計が複雑かつ不確実です。"},{"l":"D","html":"SNS FIFOトピックのサブスクライバーはSQS FIFOキューに限られ、Lambdaを直接サブスクライブさせることはできません。"}],"refs":"<a href=\"#integration\" data-go=\"integration\">第6章 6.1 Amazon SQS</a>"},{"n":2,"topic":"ストリームの再処理","level":3,"body":["EventBridgeで各種イベントをLambdaへ配信しています。下流のバグにより、<b>過去3日分のイベントが正しく処理されていなかった</b>ことが判明しました。修正後、その期間のイベントを再実行したいと考えています。適切な方法はどれですか。"],"options":[{"l":"A","html":"Lambdaの非同期呼び出しの再試行回数を増やす"},{"l":"B","html":"CloudTrailのログからイベントを再構成して手動で再送する"},{"l":"C","html":"EventBridgeのアーカイブを有効にしておき、対象期間を指定してリプレイする"},{"l":"D","html":"デッドレターキューの内容を再送する"}],"answer":["C"],"multi":false,"req":"","key":"<b>EventBridgeのアーカイブとリプレイは、保存したイベントを後から再投入する機能</b>です。「過去のイベントをやり直す」要件はこれで満たせます（事前にアーカイブの設定が必要）。","reasons":[{"l":"A","html":"再試行は<b>失敗した</b>呼び出しへの対処です。設問は処理自体は成功し、結果が誤っていた状況です。"},{"l":"B","html":"CloudTrailはAPI操作の記録で、カスタムイベントの完全な再現には適しません。"},{"l":"D","html":"DLQには失敗したイベントしか入りません。成功扱いだったイベントは残っていません。"}],"refs":"<a href=\"#integration\" data-go=\"integration\">第6章 6.3 Amazon EventBridge</a> ／ <a href=\"#d2\" data-go=\"d2\">第12章 12.4 イベント駆動型アーキテクチャ</a>"},{"n":3,"topic":"ワークフローの選択","level":2,"body":["IoTデバイスから届くイベントごとに、<b>5つの短い処理を順に実行</b>するワークフローを構築します。イベントは<b>毎秒数千件</b>発生し、1件あたりの処理は数百ミリ秒で完了します。コストを抑えたいと考えています。適切な選択はどれですか。"],"options":[{"l":"A","html":"Step Functions の Expressワークフロー"},{"l":"B","html":"Step Functions の 標準ワークフロー"},{"l":"C","html":"Amazon SQS FIFOキューで各処理をつなぐ"},{"l":"D","html":"単一のLambda関数にすべての処理を実装する"}],"answer":["A"],"multi":false,"req":"","key":"<b>Expressワークフローは大量・高頻度・短時間（最大5分）の処理向け</b>で、実行単価が安く抑えられます。標準ワークフローは状態遷移ごとの課金で、長時間・監査重視の用途向けです。","reasons":[{"l":"B","html":"標準は最大1年の実行と正確に1回の実行保証が特徴ですが、毎秒数千件では課金が大きくなります。"},{"l":"C","html":"キューの連結では分岐・エラー処理・全体の可視化を自前で作ることになります。"},{"l":"D","html":"単一関数に詰め込むと、途中失敗時の再実行単位が粗くなり、処理の可視化もできません。"}],"refs":"<a href=\"#integration\" data-go=\"integration\">第6章 6.4 AWS Step Functions</a>"},{"n":4,"topic":"ロードバランサー","level":3,"body":["新しいEC2インスタンスがターゲットグループに登録された直後、<b>キャッシュが温まっていないため応答が遅く、エラー率が上がります</b>。数分経てば安定します。適切な設定はどれですか。"],"options":[{"l":"A","html":"ターゲットグループのスロースタート期間を設定し、徐々にトラフィックを増やす"},{"l":"B","html":"ヘルスチェックの間隔を短くする"},{"l":"C","html":"登録解除の遅延を延長する"},{"l":"D","html":"クロスゾーン負荷分散を無効化する"}],"answer":["A"],"multi":false,"req":"","key":"<b>スロースタートは、新しく登録されたターゲットへのトラフィックを設定時間かけて徐々に増やす</b>機能です。ウォームアップが必要なアプリケーションに使います。","reasons":[{"l":"B","html":"ヘルスチェックを頻繁にしても、ターゲットが温まる時間は短縮されません。"},{"l":"C","html":"登録解除の遅延は<b>取り外すとき</b>の設定で、追加時の挙動には関係しません。"},{"l":"D","html":"クロスゾーン負荷分散はAZ間の分散設定で、新規ターゲットの立ち上がりとは無関係です。"}],"refs":"<a href=\"#network\" data-go=\"network\">第3章 3.5 負荷分散（ELB）</a> ／ <a href=\"#d2\" data-go=\"d2\">第12章 12.1 スケーリング戦略</a>"},{"n":5,"topic":"ヘルスチェック","level":3,"body":["プライベートサブネット内のアプリケーションの健全性に応じて、Route 53のDNSフェイルオーバーを行いたいと考えています。対象はインターネットから到達できないため、Route 53の通常のエンドポイントヘルスチェックでは監視できません。適切な方法はどれですか。"],"options":[{"l":"A","html":"Route 53のヘルスチェックを無効にし、TTLを短くする"},{"l":"B","html":"ヘルスチェックの対象をALBのDNS名に変更する"},{"l":"C","html":"プライベートサブネットをパブリックサブネットに変更する"},{"l":"D","html":"アプリケーションのメトリクスからCloudWatchアラームを作成し、<b>CloudWatchアラームを参照するヘルスチェック</b>をRoute 53に設定する"}],"answer":["D"],"multi":false,"req":"","key":"Route 53のヘルスチェックには3種類（<b>エンドポイント／他のヘルスチェックの計算（親子）／CloudWatchアラーム</b>）があります。<b>インターネットから到達できない対象はCloudWatchアラーム経由</b>で監視します。","reasons":[{"l":"A","html":"ヘルスチェックを無効にすると、異常時に切り替えが起きなくなります。"},{"l":"B","html":"ALBが内部向け（internal）であれば同じ問題が残り、そもそもアプリ固有の健全性を表すとは限りません。"},{"l":"C","html":"セキュリティ要件を壊す変更であり、可用性の問題を解く手段としても不適切です。"}],"refs":"<a href=\"#network\" data-go=\"network\">第3章 3.4 名前解決：Route 53 と Resolver</a> ／ <a href=\"#d2\" data-go=\"d2\">第12章 12.5 高可用性と耐障害性</a>"},{"n":6,"topic":"RDSの可用性","level":3,"body":["RDSのマルチAZ構成について、要件は (1) フェイルオーバーを<b>できるだけ短時間</b>で完了させる、(2) <b>スタンバイも読み取りに活用</b>したい、の2つです。適切な構成はどれですか。"],"options":[{"l":"A","html":"マルチAZ <b>DBインスタンス</b>（単一のスタンバイ）＋ リードレプリカ1台"},{"l":"B","html":"マルチAZ <b>DBクラスター</b>（2つの読み取り可能なスタンバイを持つ構成）"},{"l":"C","html":"シングルAZ構成＋ 別AZのリードレプリカ"},{"l":"D","html":"マルチAZ DBインスタンスを2セット用意する"}],"answer":["B"],"multi":false,"req":"","key":"<b>マルチAZ DBクラスターは、読み取り可能なスタンバイを2つ持ち、フェイルオーバーも通常のマルチAZインスタンスより短時間</b>です。2つの要件を同時に満たします。","reasons":[{"l":"A","html":"要件は満たせますが、フェイルオーバー時間はDBクラスター構成より長く、構成要素も増えます。"},{"l":"C","html":"シングルAZでは自動フェイルオーバーがなく、レプリカの昇格は手動です。"},{"l":"D","html":"2セットは同期されておらず、可用性構成として成立しません。"}],"refs":"<a href=\"#database\" data-go=\"database\">第4章 4.1 Amazon RDS</a> ／ <a href=\"#d2\" data-go=\"d2\">第12章 12.5 高可用性と耐障害性</a>"},{"n":7,"topic":"レプリケーション","level":3,"body":["コンプライアンス要件で、S3オブジェクトを別リージョンへ複製し、<b>複製が15分以内に完了することをSLAで保証</b>する必要があります。また、複製の進捗を監視したいと考えています。適切な設定はどれですか。"],"options":[{"l":"A","html":"ライフサイクルポリシーで別リージョンへ移行する"},{"l":"B","html":"レプリケーションルールに <b>S3 Replication Time Control（RTC）</b> を設定する"},{"l":"C","html":"クロスリージョンレプリケーションを有効にするだけで、SLAは自動的に適用される"},{"l":"D","html":"AWS DataSyncで15分ごとに同期する"}],"answer":["B"],"multi":false,"req":"","key":"<b>RTC（Replication Time Control）は99.99%のオブジェクトを15分以内に複製するSLA</b>と、レプリケーションメトリクス・イベント通知を提供します。通常のレプリケーションにSLAはありません。","reasons":[{"l":"A","html":"ライフサイクルはストレージクラスの移行や失効の仕組みで、別リージョンへのコピー機能ではありません。"},{"l":"C","html":"標準のレプリケーションは<b>ベストエフォート</b>で、完了時間の保証はありません。"},{"l":"D","html":"DataSyncはスケジュール転送で、15分以内という保証はなく、S3イベント連携も別途必要です。"}],"refs":"<a href=\"#storage\" data-go=\"storage\">第2章 2.1 Amazon S3</a> ／ <a href=\"#d2\" data-go=\"d2\">第12章 12.5 高可用性と耐障害性</a>"},{"n":8,"topic":"コンテナの安全なデプロイ","level":2,"body":["Amazon ECSサービスの新しいタスク定義をデプロイした際、<b>アプリの不具合でタスクが起動に失敗し続け</b>、サービスが不安定になりました。今後は<b>失敗を検知したら自動的に前のバージョンへ戻したい</b>と考えています。適切な設定はどれですか。"],"options":[{"l":"A","html":"Fargate Spotに切り替える"},{"l":"B","html":"タスクの必要数（desired count）を増やす"},{"l":"C","html":"ターゲットグループのヘルスチェック間隔を延ばす"},{"l":"D","html":"ECSのデプロイサーキットブレーカー（自動ロールバック）を有効にする"}],"answer":["D"],"multi":false,"req":"","key":"<b>デプロイサーキットブレーカーは、デプロイの失敗を検知して自動的に直前の安定版へロールバック</b>します。段階的なデプロイの安全装置です。","reasons":[{"l":"A","html":"Fargate Spotはコスト最適化の選択で、デプロイの安全性とは無関係です（中断のリスクはむしろ増えます）。"},{"l":"B","html":"起動に失敗するタスクを増やしても状況は改善しません。"},{"l":"C","html":"ヘルスチェックを緩めると、異常なタスクが正常と扱われる時間が延びるだけです。"}],"refs":"<a href=\"#container\" data-go=\"container\">第9章 9.1 Amazon ECS</a> ／ <a href=\"#d2\" data-go=\"d2\">第12章 12.5 高可用性と耐障害性</a>"},{"n":9,"topic":"ストリーム処理","level":3,"body":["Kinesis Data Streamsを使う分析基盤で、<b>新たに3つ目のコンシューマーアプリケーション</b>を追加したところ、既存のコンシューマーの読み取りが遅延し、<code>ReadProvisionedThroughputExceeded</code>が発生するようになりました。シャード数は変えたくありません。適切な対処はどれですか。"],"options":[{"l":"A","html":"各コンシューマーを拡張ファンアウト（Enhanced Fan-Out）で登録する"},{"l":"B","html":"シャードのパーティションキーを変更する"},{"l":"C","html":"データ保持期間を24時間から7日へ延長する"},{"l":"D","html":"コンシューマーのポーリング間隔を短くする"}],"answer":["A"],"multi":false,"req":"","key":"標準のコンシューマーは<b>1シャードあたり2 MB/秒の読み取り帯域を共有</b>します。<b>拡張ファンアウトはコンシューマーごとに専用の2 MB/秒</b>を割り当てるため、シャードを増やさずに読み取りの競合を解消できます。","reasons":[{"l":"B","html":"パーティションキーは書き込みの分散に関する設定で、読み取り帯域の共有とは無関係です。"},{"l":"C","html":"保持期間は再処理できる時間の長さで、スループットは変わりません。"},{"l":"D","html":"ポーリングを増やすと共有帯域の奪い合いが激化し、悪化します。"}],"refs":"<a href=\"#analytics\" data-go=\"analytics\">第7章 7.1 Amazon Kinesis</a> ／ <a href=\"#d3\" data-go=\"d3\">第13章 13.3 データベースとパフォーマンス</a>"},{"n":10,"topic":"自動復旧","level":3,"body":["単一のEC2インスタンスで動く社内システムについて、<b>インスタンス障害からの復旧を自動化</b>したいと考えています。アプリケーションは冗長化に対応しておらず、当面は1台構成のままです。<b>適切な対策を2つ選択してください。</b>"],"options":[{"l":"A","html":"インスタンスストアにデータを保存する"},{"l":"B","html":"Auto Scalingグループ（最小=最大=1）に入れ、ELBヘルスチェックで異常時に自動で置き換える"},{"l":"C","html":"インスタンスタイプを大きくする"},{"l":"D","html":"CloudWatchアラームのEC2アクション（復旧）を設定し、ハードウェア障害時に別のホストで再起動させる"},{"l":"E","html":"終了保護を有効にする"}],"answer":["B","D"],"multi":true,"req":"","key":"<b>1台構成でも「壊れたら作り直す」仕組みは作れます</b>。ASG（最小1台）は置き換えによる復旧、CloudWatchの復旧アクションはシステムステータスチェック失敗時に<b>同じインスタンスIDのまま別ハードウェアで起動</b>します。","reasons":[{"l":"A","html":"インスタンスストアは停止・終了でデータが消えるため、復旧の妨げになります。"},{"l":"C","html":"サイズを上げても障害は起こり、復旧は自動化されません。"},{"l":"E","html":"終了保護は誤操作による削除を防ぐ設定で、障害からの復旧手段ではありません。"}],"refs":"<a href=\"#compute\" data-go=\"compute\">第1章 1.1 Amazon EC2</a> ／ <a href=\"#d2\" data-go=\"d2\">第12章 12.5 高可用性と耐障害性</a>"}]},{"id":"exam-set-15","file":"set-15.md","num":"問題セット15","title":"第3分野 2周目：高パフォーマンスなアーキテクチャの設計","questions":[{"n":1,"topic":"ストレージ性能","level":3,"body":["データベース用のEC2インスタンスで、EBSボリュームのIOPSを20,000までプロビジョニングしましたが、実測値は8,000前後で頭打ちになります。ボリュームのバーストクレジットは枯渇していません。最も可能性が高い原因はどれですか。"],"options":[{"l":"A","html":"ファイルシステムがXFSでないため"},{"l":"B","html":"ボリュームタイプをgp3にしていないため"},{"l":"C","html":"ボリュームのサイズが小さすぎるため"},{"l":"D","html":"インスタンスタイプのEBS帯域（EBS最適化の上限）がボトルネックになっている"}],"answer":["D"],"multi":false,"req":"","key":"EBSの性能は<b>ボリューム側の設定とインスタンス側のEBS帯域の両方</b>に制限されます。ボリュームでIOPSを上げても、<b>インスタンスタイプごとの上限</b>を超えることはできません。より大きい（またはEBS最適化性能の高い）インスタンスタイプへの変更が対処です。","reasons":[{"l":"A","html":"ファイルシステムの種類でプロビジョニングしたIOPSの上限が半分になることはありません。"},{"l":"B","html":"gp3でもio2でも、インスタンス側の上限は同じように効きます。"},{"l":"C","html":"gp3やio2はIOPSを容量と独立に指定できるため、サイズが直接の原因とは限りません。"}],"refs":"<a href=\"#storage\" data-go=\"storage\">第2章 2.2 Amazon EBS</a> ／ <a href=\"#d3\" data-go=\"d3\">第13章 13.1 ストレージとパフォーマンス</a>"},{"n":2,"topic":"共有ストレージ性能","level":2,"body":["複数のEC2インスタンスがEFSを共有しています。平常時は問題ありませんが、月次バッチの時間帯だけ<b>スループットが急激に低下</b>します。CloudWatchで確認すると、バーストクレジットの残高がゼロになっていました。適切な対処はどれですか。"],"options":[{"l":"A","html":"パフォーマンスモードを「最大I/O」に変更する"},{"l":"B","html":"スループットモードをElastic（または必要量に応じたプロビジョンド）に変更する"},{"l":"C","html":"ライフサイクル管理でIAへ移行する"},{"l":"D","html":"EFSをOne Zoneストレージクラスに変更する"}],"answer":["B"],"multi":false,"req":"","key":"<b>バーストスループットはファイルシステムのサイズに応じたクレジット制</b>です。クレジットが尽きてベースラインまで落ちる問題は、<b>Elasticまたはプロビジョンドスループット</b>への変更で解消します。","reasons":[{"l":"A","html":"最大I/Oは多数クライアントの並列性を上げるモードで、レイテンシは悪化します。スループットのクレジット枯渇とは別の話です。"},{"l":"C","html":"IAへの移行は保管コストの削減で、スループットは改善しません（むしろ取り出し料金が発生します）。"},{"l":"D","html":"One Zoneはコスト最適化の選択肢で、可用性が下がるだけでスループットは変わりません。"}],"refs":"<a href=\"#storage\" data-go=\"storage\">第2章 2.3 Amazon EFS</a> ／ <a href=\"#d3\" data-go=\"d3\">第13章 13.1 ストレージとパフォーマンス</a>"},{"n":3,"topic":"キャッシュ効率","level":3,"body":["CloudFrontを導入しましたが、<b>キャッシュヒット率が20%程度</b>と低く、オリジンの負荷が下がりません。調査すると、アプリケーションが計測用のクエリ文字列（<code>?utm_source=...</code>など）を付与しており、それらがキャッシュキーに含まれていました。適切な対処はどれですか。"],"options":[{"l":"A","html":"TTLを0に設定する"},{"l":"B","html":"キャッシュポリシーで、キャッシュキーに含めるクエリ文字列を必要なものだけに限定する"},{"l":"C","html":"すべてのリクエストをオリジンへ転送する設定にする"},{"l":"D","html":"価格クラスをAllに変更する"}],"answer":["B"],"multi":false,"req":"","key":"<b>キャッシュキーに不要な要素（クエリ文字列・ヘッダー・Cookie）が入ると、同じ内容が別物として扱われヒット率が落ちます</b>。キャッシュポリシーで必要な要素だけに絞るのが定石です。","reasons":[{"l":"A","html":"TTLを0にするとキャッシュされなくなり、状況は悪化します。"},{"l":"C","html":"オリジンへの転送を増やすのは目的と正反対です。"},{"l":"D","html":"価格クラスは配信するエッジの範囲の設定で、ヒット率とは無関係です。"}],"refs":"<a href=\"#network\" data-go=\"network\">第3章 3.6 CloudFrontとGlobal Accelerator</a> ／ <a href=\"#d3\" data-go=\"d3\">第13章 13.4 ネットワークパフォーマンスの最適化</a>"},{"n":4,"topic":"キャッシュ層のスケール","level":3,"body":["ElastiCache for Redisを使っていますが、<b>データ量が単一ノードのメモリ上限に近づき、書き込みのスループットも不足</b>してきました。アプリケーションの改修は許容されます。適切な対処はどれですか。"],"options":[{"l":"A","html":"ノードタイプを変更せず、TTLを短くする"},{"l":"B","html":"リードレプリカを追加する"},{"l":"C","html":"Memcachedへ移行する"},{"l":"D","html":"クラスターモードを有効にし、複数シャードへデータを分散する"}],"answer":["D"],"multi":false,"req":"","key":"<b>クラスターモード（シャーディング）は、データとスループットを複数ノードへ水平分割</b>します。メモリ上限と書き込み性能の両方に効く唯一の選択肢です。","reasons":[{"l":"A","html":"TTL短縮は一時しのぎで、根本的な容量・スループット不足は解決しません。"},{"l":"B","html":"レプリカは<b>読み取り</b>のスケールと可用性向上のためで、書き込みとメモリ容量は変わりません。"},{"l":"C","html":"Memcachedも水平分割はできますが、永続化・レプリケーション・高度なデータ型を失います。要件は改修可否のみで、機能の放棄は求められていません。"}],"refs":"<a href=\"#database\" data-go=\"database\">第4章 4.4 Amazon ElastiCache</a> ／ <a href=\"#d3\" data-go=\"d3\">第13章 13.3 データベースとパフォーマンス</a>"},{"n":5,"topic":"Auroraの読み取り分散","level":3,"body":["Auroraクラスターに15台のリーダーがあります。<b>重い分析クエリ専用に3台</b>を割り当て、通常のアプリケーションからの読み取りは残りのリーダーへ分散させたいと考えています。適切な方法はどれですか。"],"options":[{"l":"A","html":"カスタムエンドポイントを作成し、分析用の3台だけを含める"},{"l":"B","html":"リーダーエンドポイントへ接続し、アプリ側で接続先を選ぶ"},{"l":"C","html":"クラスターエンドポイントへ分析クエリを送る"},{"l":"D","html":"分析用に別のAuroraクラスターを作成し、手動で同期する"}],"answer":["A"],"multi":false,"req":"","key":"Auroraのエンドポイントは3種類。<b>クラスター（書き込み）／リーダー（全リーダーへ自動分散）／カスタム（指定したインスタンス群）</b>。用途別に分けるならカスタムエンドポイントです。","reasons":[{"l":"B","html":"リーダーエンドポイントは接続先を自動で分散するため、特定の3台に固定できません。"},{"l":"C","html":"クラスターエンドポイントはライター宛てで、分析クエリを送ると本番の書き込みに影響します。"},{"l":"D","html":"手動同期は運用負荷が高く、データの鮮度も落ちます。"}],"refs":"<a href=\"#database\" data-go=\"database\">第4章 4.2 Amazon Aurora</a> ／ <a href=\"#d3\" data-go=\"d3\">第13章 13.3 データベースとパフォーマンス</a>"},{"n":6,"topic":"DynamoDBのクエリ","level":3,"body":["DynamoDBテーブル（数億項目）から、<b>特定の顧客IDに紐づく注文だけ</b>を取得する処理が、極端に遅くキャパシティも大量に消費しています。実装では<code>Scan</code>にフィルター式を付けて顧客IDを絞り込んでいます。適切な対処はどれですか。"],"options":[{"l":"A","html":"顧客IDをパーティションキーに持つGSIを作成し、<code>Query</code>で取得する"},{"l":"B","html":"並列スキャン（Parallel Scan）に変更する"},{"l":"C","html":"読み取りを強い整合性に変更する"},{"l":"D","html":"プロビジョニングされた読み取りキャパシティを10倍にする"}],"answer":["A"],"multi":false,"req":"","key":"<b><code>Scan</code>は全項目を読んでからフィルターする</b>ため、対象が少なくてもテーブル全体分のキャパシティを消費します。<b>キーで直接引ける<code>Query</code></b>（必要ならGSIを作る）に変えるのが根本対処です。","reasons":[{"l":"B","html":"並列スキャンは速くなりますが、読み取り量（＝コスト）はむしろ増えます。"},{"l":"C","html":"整合性モデルを強くすると消費キャパシティは2倍になり、悪化します。"},{"l":"D","html":"キャパシティを増やしても全件読み取りという非効率は変わらず、コストだけが上がります。"}],"refs":"<a href=\"#database\" data-go=\"database\">第4章 4.3 Amazon DynamoDB</a> ／ <a href=\"#d3\" data-go=\"d3\">第13章 13.3 データベースとパフォーマンス</a>"},{"n":7,"topic":"グローバル配信","level":3,"body":["TCPベースのオンラインゲームでGlobal Acceleratorを利用しています。<b>同じプレイヤーのセッションが、常に同じエンドポイントへ接続される</b>ようにしたいと考えています。適切な設定はどれですか。"],"options":[{"l":"A","html":"エンドポイントの重みをすべて同じにする"},{"l":"B","html":"トラフィックダイヤルを50%に設定する"},{"l":"C","html":"リスナーのクライアントアフィニティを「送信元IP」に設定する"},{"l":"D","html":"ヘルスチェックの間隔を延ばす"}],"answer":["C"],"multi":false,"req":"","key":"<b>クライアントアフィニティを「送信元IP」にすると、同じクライアントからの接続が同じエンドポイントへ維持</b>されます（既定は「なし」でフローごとに分散）。","reasons":[{"l":"A","html":"重みは分散比率の設定で、粘着性は生まれません。"},{"l":"B","html":"トラフィックダイヤルはエンドポイントグループへ流す割合の調整で、個々のクライアントの固定には使えません。"},{"l":"D","html":"ヘルスチェック間隔は障害検知の速さの設定です。"}],"refs":"<a href=\"#network\" data-go=\"network\">第3章 3.6 CloudFrontとGlobal Accelerator</a>"},{"n":8,"topic":"ネットワーク性能","level":2,"body":["同一VPC内のEC2インスタンス間で、<b>大きなデータを高スループットで転送</b>したいと考えています。インスタンスは拡張ネットワーキング対応です。追加で有効な設定はどれですか。"],"options":[{"l":"A","html":"NAT Gateway経由で通信させる"},{"l":"B","html":"インスタンスにパブリックIPを割り当てる"},{"l":"C","html":"ジャンボフレーム（MTU 9001）を有効にし、同一VPC内の通信で使う"},{"l":"D","html":"VPCピアリングを設定する"}],"answer":["C"],"multi":false,"req":"","key":"<b>VPC内の通信ではMTU 9001（ジャンボフレーム）が利用でき、パケットあたりのペイロードが増えてスループットが向上</b>します（インターネットや一部のゲートウェイ越えでは1500に制限されます）。","reasons":[{"l":"A","html":"NAT Gatewayは外向き通信のための仕組みで、VPC内通信に挟む意味はありません。"},{"l":"B","html":"同一VPC内の通信にパブリックIPは不要で、経路がインターネット向けになると性能はむしろ落ちます。"},{"l":"D","html":"ピアリングは<b>別のVPC</b>と接続する機能で、同一VPC内では不要です。"}],"refs":"<a href=\"#d3\" data-go=\"d3\">第13章 13.4 ネットワークパフォーマンスの最適化</a> ／ <a href=\"#compute\" data-go=\"compute\">第1章 1.1 Amazon EC2</a>"},{"n":9,"topic":"分析性能","level":3,"body":["Athenaで、S3上の<b>日付パーティション（年/月/日）を持つ大量のデータ</b>をクエリしています。パーティション数が数十万に達し、<b>クエリの計画段階（パーティションの読み込み）に時間がかかる</b>ようになりました。適切な対処はどれですか。"],"options":[{"l":"A","html":"パーティション射影（Partition Projection）を有効にし、パーティション情報を計算で求める"},{"l":"B","html":"すべてのパーティションを削除し、単一のフォルダに統合する"},{"l":"C","html":"Glueクローラーの実行頻度を1時間ごとに増やす"},{"l":"D","html":"データ形式をCSVに戻す"}],"answer":["A"],"multi":false,"req":"","key":"<b>パーティション射影は、パーティションの一覧をカタログから読まずに命名規則から計算</b>します。パーティション数が非常に多いテーブルで、クエリ計画のオーバーヘッドを大きく削減できます。","reasons":[{"l":"B","html":"パーティションをなくすと、スキャン量が激増してコストと時間が悪化します。"},{"l":"C","html":"クローラーの頻度を上げてもパーティション数は減らず、カタログ更新の負荷が増えるだけです。"},{"l":"D","html":"CSVは列指向ではないため、スキャン量が増えて遅くなります。"}],"refs":"<a href=\"#analytics\" data-go=\"analytics\">第7章 7.3 Amazon Athena</a> ／ <a href=\"#analytics\" data-go=\"analytics\">第7章 7.2 AWS Glue</a>"},{"n":10,"topic":"性能改善の打ち手","level":3,"body":["Webアプリケーションの応答が遅く、調査の結果、(1) 同一の商品マスタへの参照クエリがDBへ繰り返し発行されている、(2) 静的な画像・CSS・JSがすべてオリジンのEC2から配信されている、という2点が判明しました。<b>適切な対策を2つ選択してください。</b>"],"options":[{"l":"A","html":"EC2のインスタンスタイプをメモリ最適化に変更する"},{"l":"B","html":"ALBのアイドルタイムアウトを延長する"},{"l":"C","html":"商品マスタの参照結果をElastiCacheにキャッシュし、TTLを設定する"},{"l":"D","html":"RDSのストレージをio2に変更する"},{"l":"E","html":"静的アセットをS3に置き、CloudFrontから配信する"}],"answer":["C","E"],"multi":true,"req":"","key":"<b>症状ごとに層を分けて対処</b>します。繰り返しの参照＝<b>キャッシュ層（ElastiCache）</b>、静的配信＝<b>CDN（CloudFront＋S3）</b>。どちらもオリジンの負荷を根本から減らします。","reasons":[{"l":"A","html":"ボトルネックはDBへの繰り返しアクセスと静的配信であり、アプリサーバーのメモリではありません。"},{"l":"B","html":"アイドルタイムアウトは接続維持時間の設定で、応答速度には影響しません。"},{"l":"D","html":"ストレージ性能の問題とは特定されていません。まずキャッシュでDBへの到達回数を減らすのが先です。"}],"refs":"<a href=\"#d3\" data-go=\"d3\">第13章 13.3 データベースとパフォーマンス</a> ／ <a href=\"#d3\" data-go=\"d3\">第13章 13.4 ネットワークパフォーマンスの最適化</a>"}]},{"id":"exam-set-16","file":"set-16.md","num":"問題セット16","title":"第4分野 2周目：コストを最適化したアーキテクチャの設計","questions":[{"n":1,"topic":"割引プランの選択","level":3,"body":["今後3年間、EC2に加えて<b>FargateとLambdaも併用</b>する計画です。利用するインスタンスファミリーやリージョンは、事業の状況に応じて変わる可能性があります。最も柔軟に割引を受けられる選択はどれですか。"],"options":[{"l":"A","html":"スタンダードリザーブドインスタンス（3年）"},{"l":"B","html":"EC2 Instance Savings Plans"},{"l":"C","html":"Compute Savings Plans"},{"l":"D","html":"オンデマンドキャパシティ予約"}],"answer":["C"],"multi":false,"req":"","key":"<b>Compute Savings Plansは、EC2・Fargate・Lambdaを横断して適用</b>され、インスタンスファミリー・サイズ・AZ・<b>リージョンの変更にも追随</b>します。柔軟性が要件のときはこれです。","reasons":[{"l":"A","html":"スタンダードRIはEC2のみが対象で、インスタンスファミリーの変更もできません（Convertible RIなら交換可）。"},{"l":"B","html":"EC2 Instance SPは割引率が高い代わりに、<b>特定リージョンの特定ファミリーに固定</b>され、FargateやLambdaには適用されません。"},{"l":"D","html":"キャパシティ予約は容量の確保が目的で、それ自体に割引はありません。"}],"refs":"<a href=\"#d4\" data-go=\"d4\">第14章 14.3 コンピューティングのコスト最適化</a> ／ <a href=\"#compute\" data-go=\"compute\">第1章 1.1 Amazon EC2</a>"},{"n":2,"topic":"リザーブドインスタンス","level":2,"body":["3年前に購入したスタンダードRIが、<b>アプリケーションの刷新で使われなくなりました</b>。残り1年の期間が無駄になっています。将来同じ事態を避けるための購入方法はどれですか。"],"options":[{"l":"A","html":"コンバーティブル（Convertible）リザーブドインスタンスを選ぶ"},{"l":"B","html":"全額前払いを選ぶ"},{"l":"C","html":"ゾーンRIを選ぶ"},{"l":"D","html":"1年ではなく3年契約を選ぶ"}],"answer":["A"],"multi":false,"req":"","key":"<b>コンバーティブルRIは、期間中にインスタンスファミリー・OS・テナンシーなどを交換できます</b>。構成変更の可能性がある場合は、割引率が少し下がってもこちらが適します（スタンダードRIはマーケットプレイスでの売却は可能ですが、交換はできません）。","reasons":[{"l":"B","html":"支払い方法の選択で、柔軟性は上がりません（むしろ前払い額が無駄になります）。"},{"l":"C","html":"ゾーンRIは特定AZのキャパシティ予約が付く形態で、柔軟性はさらに下がります。"},{"l":"D","html":"期間を延ばすと、使われなくなったときの損失が大きくなります。"}],"refs":"<a href=\"#d4\" data-go=\"d4\">第14章 14.3 コンピューティングのコスト最適化</a>"},{"n":3,"topic":"アーカイブ","level":3,"body":["EBSスナップショットを法令対応で<b>7年間保管</b>します。復元の必要が生じるのは数年に一度で、<b>復元までに1〜2日かかっても構いません</b>。保管コストを最小化する方法はどれですか。"],"options":[{"l":"A","html":"スナップショットをS3 Glacier Deep Archiveへコピーする"},{"l":"B","html":"スナップショットを標準層のまま保持する"},{"l":"C","html":"EBSスナップショットアーカイブ層へ移動する"},{"l":"D","html":"スナップショットからAMIを作成して保管する"}],"answer":["C"],"multi":false,"req":"","key":"<b>EBSスナップショットアーカイブは、めったに復元しないスナップショットの保管コストを大幅に下げる階層</b>です。復元には最大24〜72時間かかるため、「1〜2日待てる」という条件が決め手になります。","reasons":[{"l":"A","html":"EBSスナップショットを直接Glacierへコピーする機能はありません（アーカイブ層が正規の手段です）。"},{"l":"B","html":"標準層のままでは7年分の保管コストが高くつきます。"},{"l":"D","html":"AMIはスナップショットを参照するため、保管コストの削減になりません。"}],"refs":"<a href=\"#storage\" data-go=\"storage\">第2章 2.2 Amazon EBS</a> ／ <a href=\"#d4\" data-go=\"d4\">第14章 14.2 ストレージのコスト最適化</a>"},{"n":4,"topic":"ストレージ階層","level":3,"body":["S3 Intelligent-Tieringを使っているバケットで、<b>1年以上アクセスされていないオブジェクトが大量に存在</b>することが分かりました。これらの保管コストをさらに下げたいと考えています。取り出しには数時間かかっても構いません。適切な設定はどれですか。"],"options":[{"l":"A","html":"ライフサイクルポリシーでStandard-IAへ移行する"},{"l":"B","html":"Intelligent-Tieringの<b>アーカイブアクセス階層（および深いアーカイブアクセス階層）</b>をオプトインで有効化する"},{"l":"C","html":"バケットのバージョニングを無効化する"},{"l":"D","html":"オブジェクトをすべてOne Zone-IAへコピーする"}],"answer":["B"],"multi":false,"req":"","key":"Intelligent-Tieringの<b>アーカイブ階層はオプトイン（既定では無効）</b>です。有効化すると、一定期間アクセスのないオブジェクトが自動的により安い階層へ移動します（取り出しに時間がかかる点が許容条件）。","reasons":[{"l":"A","html":"Intelligent-Tieringはすでにアクセス頻度に応じて階層移動しており、Standard-IAへの移行は二重管理になります。"},{"l":"C","html":"バージョニングの無効化は誤削除対策を失うだけで、保管コストの本質的な削減にはなりません（不要な旧バージョンの失効はライフサイクルで行います）。"},{"l":"D","html":"コピーすると二重に保管されることになり、コストは増えます。"}],"refs":"<a href=\"#storage\" data-go=\"storage\">第2章 2.1 Amazon S3</a> ／ <a href=\"#d4\" data-go=\"d4\">第14章 14.2 ストレージのコスト最適化</a>"},{"n":5,"topic":"組織でのコスト最適化","level":2,"body":["Organizationsで20アカウントを運用しています。ある子アカウントでRIを購入しましたが、そのアカウントでの利用が少なく、<b>割引が余っています</b>。他のアカウントのEC2利用にもこの割引を適用したいと考えています。適切な方法はどれですか。"],"options":[{"l":"A","html":"すべてのEC2を1つのアカウントへ移設する"},{"l":"B","html":"RIを購入し直して各アカウントに分散する"},{"l":"C","html":"各アカウントを個別の請求に切り替える"},{"l":"D","html":"管理アカウントでRI/Savings Plansの割引共有を有効にする"}],"answer":["D"],"multi":false,"req":"","key":"<b>一括請求では、RIやSavings Plansの割引が組織内の他アカウントの利用にも適用</b>されます（管理アカウント側で共有の有効／無効を設定できます）。","reasons":[{"l":"A","html":"アカウント分離の設計意図（障害・権限の分離）を壊す大掛かりな変更です。"},{"l":"B","html":"買い直しは費用の無駄で、余剰の解消にもなりません。"},{"l":"C","html":"個別請求にすると一括請求のボリュームディスカウントと割引共有の両方を失います。"}],"refs":"<a href=\"#management\" data-go=\"management\">第8章 8.5 AWS Organizations</a> ／ <a href=\"#d4\" data-go=\"d4\">第14章 14.1 コスト管理ツールの使い分け</a>"},{"n":6,"topic":"配信コスト","level":2,"body":["CloudFrontで配信しているサービスの利用者は、<b>日本と北米のみ</b>です。ヨーロッパやアジア他地域のエッジロケーションからの配信は不要で、配信コストを抑えたいと考えています。適切な設定はどれですか。"],"options":[{"l":"A","html":"価格クラス（Price Class）を、対象地域を含む下位のクラスに変更する"},{"l":"B","html":"オリジンシールドを無効にする"},{"l":"C","html":"TTLを最小値に設定する"},{"l":"D","html":"地理的制限で日本と北米以外を拒否する"}],"answer":["A"],"multi":false,"req":"","key":"<b>価格クラスは「どの範囲のエッジロケーションを使うか」の設定</b>で、範囲を絞ると単価の高い地域を除外できます。利用者の所在が限られる場合の定番のコスト削減策です。","reasons":[{"l":"B","html":"オリジンシールドはオリジンへのリクエストを集約してオリジン負荷と転送量を減らす機能で、無効化するとむしろ不利になり得ます。"},{"l":"C","html":"TTLを短くするとキャッシュヒット率が下がり、オリジンへの転送が増えてコストが上がります。"},{"l":"D","html":"地理的制限はアクセスの可否の制御であり、配信の単価やエッジの範囲を変えるものではありません。"}],"refs":"<a href=\"#network\" data-go=\"network\">第3章 3.6 CloudFrontとGlobal Accelerator</a> ／ <a href=\"#d4\" data-go=\"d4\">第14章 14.2 ストレージのコスト最適化</a>"},{"n":7,"topic":"コンテナのコスト","level":3,"body":["ECS on Fargateで、<b>CI/CDのビルドジョブ</b>（1回15分程度、失敗しても再実行すればよい）を大量に実行しています。コストを削減する方法はどれですか。"],"options":[{"l":"A","html":"タスクのCPUとメモリを最大値に設定する"},{"l":"B","html":"Fargate Spotで実行する"},{"l":"C","html":"EC2起動タイプに変更し、オンデマンドインスタンスで実行する"},{"l":"D","html":"タスク数を固定し、常時起動しておく"}],"answer":["B"],"multi":false,"req":"","key":"<b>中断されても再実行すればよいワークロードはSpot</b>です。Fargate Spotは大幅に安く、CI/CDのビルドは中断耐性がある典型例です。","reasons":[{"l":"A","html":"リソースを増やすと単価が上がります（処理時間の短縮と相殺されるとは限りません）。"},{"l":"C","html":"オンデマンドのEC2に変えても割引はなく、インスタンス管理の手間が増えます。"},{"l":"D","html":"常時起動はアイドル時間に課金され、ジョブ実行型のワークロードには最も不向きです。"}],"refs":"<a href=\"#container\" data-go=\"container\">第9章 9.3 AWS Fargate</a> ／ <a href=\"#d4\" data-go=\"d4\">第14章 14.3 コンピューティングのコスト最適化</a>"},{"n":8,"topic":"データ転送コスト","level":3,"body":["3層構成のアプリケーションで、<b>アベイラビリティゾーンをまたぐデータ転送料</b>が想定以上に発生していました。可用性要件（マルチAZ構成）は維持したままコストを下げたいと考えています。<b>適切な対策を2つ選択してください。</b>"],"options":[{"l":"A","html":"アプリ層とDB層の通信が不要にAZをまたがないよう、リードレプリカを各AZに配置して同一AZ内で読み取りを完結させる"},{"l":"B","html":"すべての通信をパブリックIP経由に変更する"},{"l":"C","html":"マルチAZ構成をやめ、単一AZに集約する"},{"l":"D","html":"S3やDynamoDBへの通信にゲートウェイ型VPCエンドポイントを使い、NAT Gateway経由の転送をなくす"},{"l":"E","html":"ALBのクロスゾーン負荷分散を無効化し、可用性を下げてでも転送量を減らす"}],"answer":["A","D"],"multi":true,"req":"","key":"<b>可用性を維持したまま</b>転送量を減らすには、「<b>同一AZ内で完結させる</b>」「<b>そもそも課金される経路を通らない</b>」の2方向です。","reasons":[{"l":"B","html":"パブリック経路はデータ転送料がさらに高く、セキュリティも低下します。"},{"l":"C","html":"可用性要件（マルチAZ）を放棄しており、前提に反します。"},{"l":"E","html":"ALBのクロスゾーン負荷分散はALBでは既定で有効かつ無効化できず、「可用性を下げてでも」という方針も要件に反します。"}],"refs":"<a href=\"#d4\" data-go=\"d4\">第14章 14.2 ストレージのコスト最適化</a> ／ <a href=\"#network\" data-go=\"network\">第3章 3.3 VPCの外部接続</a>"}]},{"id":"exam-set-17","file":"set-17.md","num":"問題セット17","title":"複合問題 2周目（分野をまたぐ設計判断）","questions":[{"n":1,"topic":"セキュリティ × パフォーマンス × コスト","level":3,"body":["世界中の利用者がスマートフォンアプリから数百MBの動画をアップロードします。要件は (1) <b>認証済みの利用者だけ</b>が、自分に割り当てられたキーにのみアップロードできる、(2) 海外の利用者のアップロードも<b>遠距離による遅延の影響を減らして</b>速くする、(3) アップロードのためにアプリケーションサーバーを増強しない。最も適切な構成はどれですか。"],"options":[{"l":"A","html":"アプリに書き込み権限を持つIAMユーザーのアクセスキーを埋め込み、S3へ直接アップロードする"},{"l":"B","html":"世界各リージョンにEC2とALBを配置し、アプリサーバーが受け取った動画をS3へ転送する"},{"l":"C","html":"バケットのパブリック書き込みを許可し、アップロード後にLambdaで不正なオブジェクトを削除する"},{"l":"D","html":"バックエンドが短い有効期限の<b>署名付きURL（PUT）</b>を発行し、アプリはS3 Transfer Accelerationのエンドポイントへ直接アップロードする"}],"answer":["D"],"multi":false,"req":"①利用者ごと・キーごとの一時的な書き込み許可（第1分野）／②遠距離アップロードの高速化（第3分野）／③アプリサーバーを経由させない＝余計なコンピューティングを持たない（第4分野）","key":"<b>署名付きURL</b>は発行者の権限で、特定のキー・特定の操作だけを期限付きで許可します。アプリはS3へ直接送るのでサーバーを経由せず、<b>Transfer Acceleration</b>がエッジロケーション経由の最適化された経路で遠距離の転送を速めます。数百MBの動画ではマルチパートアップロードと組み合わせるのが定番です。","reasons":[{"l":"A","html":"長期のアクセスキーをアプリに埋め込むと、抽出されたときに全利用者の領域へ書き込めてしまいます。利用者ごとに範囲を絞れず、要件①を満たしません。"},{"l":"B","html":"要件②は満たせますが、動画がすべてアプリサーバーを通るため要件③に正面から反し、各リージョンに常駐するサーバーの費用もかかります。"},{"l":"C","html":"パブリック書き込みは要件①を満たしません。事後に削除する設計では、不正な書き込み自体を防げません。"}],"refs":"<a href=\"#storage\" data-go=\"storage\">第2章 2.1 Amazon S3</a> ／ <a href=\"#d1\" data-go=\"d1\">第11章 11.1 アクセス管理</a> ／ <a href=\"#d3\" data-go=\"d3\">第13章 13.1 ストレージとパフォーマンス</a>"},{"n":2,"topic":"弾力性 × コスト","level":3,"body":["毎晩、数百件の画像解析ジョブを実行します。1件の処理は<b>最大4時間</b>かかり、処理の途中経過は<b>S3へチェックポイントとして保存</b>できます。要件は (1) 翌朝までにすべてのジョブを終える、(2) 途中でインスタンスが失われても、そのジョブが再実行されて完了する、(3) サーバー管理の手間とコストを最小にする。最も適切な構成はどれですか。"],"options":[{"l":"A","html":"AWS Batchの<b>スポットインスタンス</b>を使うマネージド型コンピューティング環境で実行し、ジョブに再試行回数を設定する"},{"l":"B","html":"必要な台数のEC2を3年のリザーブドインスタンスで購入し、cronでジョブを順に投入する"},{"l":"C","html":"Lambda関数で1件ずつ処理し、SQSで並列度を制御する"},{"l":"D","html":"単一のインスタンスタイプを指定したスポットインスタンス1台でジョブを順番に処理する"}],"answer":["A"],"multi":false,"req":"①時間内に大量のジョブを完了＝並列実行（第3分野）／②中断されても完了する＝再試行と再開（第2分野）／③管理とコストの最小化（第4分野）","key":"<b>チェックポイントを保存でき、再実行に耐えるバッチ処理はスポットの典型的な適用先</b>です。AWS Batchはジョブのキューイング、コンピューティング環境の増減、失敗時の再試行を引き受けるので、中断を前提にしたスポットを安全に使えます。","reasons":[{"l":"B","html":"毎晩数時間しか使わない台数を3年間確保するため、日中は遊休になり要件③に反します。常時稼働するワークロード向けの割引です。"},{"l":"C","html":"Lambdaの実行時間は<b>最大15分</b>で、4時間かかるジョブは実行できません。"},{"l":"D","html":"1台で順番に処理すると翌朝までに終わらず、スポットの容量不足や中断が起きると全体が止まります。スポットは複数のインスタンスタイプに分散させて使うのが原則です。"}],"refs":"<a href=\"#compute\" data-go=\"compute\">第1章 1.5 AWS Batch</a> ／ <a href=\"#compute\" data-go=\"compute\">第1章 1.1 Amazon EC2</a> ／ <a href=\"#d4\" data-go=\"d4\">第14章 14.3 コンピューティングのコスト最適化</a>"},{"n":3,"topic":"セキュリティ × 弾力性","level":3,"body":["Lambda関数からRDS for MySQLへ接続するAPIがあります。アクセスが急増すると<b>DBの接続数が上限に達してエラー</b>になり、またDBのパスワードは<b>Lambdaの環境変数に平文で</b>設定されています。要件は (1) 認証情報を<b>定期的に自動でローテーション</b>する、(2) 同時実行数が増えても接続数が枯渇しない、(3) コードの変更は最小限にする。最も適切な構成はどれですか。"],"options":[{"l":"A","html":"認証情報をSecrets Managerに保管して自動ローテーションを有効にし、<b>RDS Proxy</b>経由で接続させる"},{"l":"B","html":"パスワードをSystems Manager Parameter StoreのSecureStringに移し、DBインスタンスのクラスを大きくして最大接続数を増やす"},{"l":"C","html":"パスワードをKMSで暗号化した環境変数に置き、Lambdaの予約済み同時実行数を1に制限する"},{"l":"D","html":"リードレプリカを追加し、Lambdaからはレプリカのエンドポイントへのみ接続させる"}],"answer":["A"],"multi":false,"req":"①認証情報の自動ローテーション（第1分野）／②接続の枯渇を防ぐ（第2・第3分野）／③コード変更を最小限に","key":"<b>RDS Proxy</b>が接続をプールして、多数のLambda実行環境からの接続をまとめます。RDS ProxyはSecrets Managerの認証情報を使ってDBへ接続するため、ローテーションはSecrets Managerに任せられ、アプリは接続先をプロキシのエンドポイントに変えるだけで済みます。","reasons":[{"l":"B","html":"Parameter Storeには<b>組み込みの自動ローテーション機能がありません</b>。また、接続数の上限を上げても、同時実行が増えればいずれ枯渇します。"},{"l":"C","html":"同時実行数を1に制限すると接続数は抑えられますが、APIが処理を捌けなくなります。暗号化した環境変数もローテーションは自動化されません。"},{"l":"D","html":"リードレプリカは読み取り負荷の分散であり、書き込みを含むAPIの接続枯渇は解決しません。認証情報の要件にも応えていません。"}],"refs":"<a href=\"#security\" data-go=\"security\">第5章 5.10 AWS Secrets Manager vs AWS Systems Manager Parameter Store</a> ／ <a href=\"#database\" data-go=\"database\">第4章 4.1 Amazon RDS</a> ／ <a href=\"#d2\" data-go=\"d2\">第12章 12.3 サーバーレステクノロジーの活用</a>"},{"n":4,"topic":"弾力性 × パフォーマンス","level":3,"body":["北米・欧州・アジアの利用者を持つSNSアプリで、利用者のプロフィールと投稿を保存します。要件は (1) <b>どのリージョンでも読み取りと書き込みを低遅延で受け付ける</b>、(2) 1つのリージョンが停止しても、他のリージョンで<b>書き込みを継続</b>できる、(3) データベースのサーバー管理はしない。最も適切な構成はどれですか。"],"options":[{"l":"A","html":"Auroraグローバルデータベースを構成し、各リージョンのアプリはそれぞれのセカンダリクラスターへ書き込む"},{"l":"B","html":"<b>DynamoDBグローバルテーブル</b>で3リージョンにレプリカを置き、Route 53のレイテンシーベースルーティングで最寄りのリージョンへ振り分ける"},{"l":"C","html":"ElastiCacheのグローバルデータストアを主データベースとして使う"},{"l":"D","html":"1つのリージョンにDynamoDBテーブルを置き、各リージョンのアプリからリージョンをまたいでアクセスする"}],"answer":["B"],"multi":false,"req":"①全リージョンで低遅延の読み書き＝<b>マルチアクティブ</b>（第3分野）／②リージョン停止時も書き込み継続（第2分野）／③サーバー管理なし","key":"<b>DynamoDBグローバルテーブル</b>は、すべてのレプリカが読み書きを受け付けるマルチアクティブ構成です。各リージョンでローカルに書き込み、変更は他のリージョンへ非同期で複製されます。リージョンが停止しても残りのレプリカで書き込みを続けられます。","reasons":[{"l":"A","html":"Auroraグローバルデータベースで書き込みを受け付けるのは<b>プライマリリージョンだけ</b>です。セカンダリへの書き込み転送を使っても、書き込み自体はプライマリで処理されるため、遠いリージョンの書き込みは低遅延になりません。"},{"l":"C","html":"グローバルデータストアで書き込めるのはプライマリクラスターだけで、しかもキャッシュ用途のサービスです。主データベースとしての永続性の要件にも合いません。"},{"l":"D","html":"単一リージョンのテーブルでは、遠いリージョンの利用者の遅延が大きく、そのリージョンが停止すると全体が止まります。"}],"refs":"<a href=\"#database\" data-go=\"database\">第4章 4.3 Amazon DynamoDB</a> ／ <a href=\"#database\" data-go=\"database\">第4章 4.2 Amazon Aurora</a> ／ <a href=\"#network\" data-go=\"network\">第3章 3.4 名前解決：Route 53 と Resolver</a>"},{"n":5,"topic":"セキュリティ × コスト","level":3,"body":["AWS Organizationsで40アカウントを管理しています。要件は (1) メンバーアカウントの管理者であっても、<b>許可された小さなインスタンスタイプ以外は起動できない</b>ようにする、(2) 同じく<b>CloudTrailの停止や削除をできない</b>ようにする、(3) 部門ごとの費用を<b>請求データで集計</b>できるようにする。<b>適切な対策を2つ選択してください。</b>"],"options":[{"l":"A","html":"部門タグを<b>タグポリシー</b>で標準化し、管理アカウントで<b>コスト配分タグ</b>として有効化する"},{"l":"B","html":"AWS Budgetsで部門ごとの予算を設定し、超過時にメールで通知する"},{"l":"C","html":"各アカウントのIAMグループに、大きなインスタンスタイプを拒否するポリシーをアタッチする"},{"l":"D","html":"AWS Configルールで大きなインスタンスタイプを検出し、管理者へ通知する"},{"l":"E","html":"<code>ec2:InstanceType</code> 条件で許可リスト外のRunInstancesを拒否し、<code>cloudtrail:StopLogging</code> と <code>cloudtrail:DeleteTrail</code> を拒否する<b>SCP</b>を組織単位に適用する"}],"answer":["A","E"],"multi":true,"req":"①②アカウント管理者にも効く<b>予防的な制限</b>（第1分野）／③部門別の費用の集計（第4分野）","key":"アカウントの管理者（ルートユーザーを含む）にも効く上限は<b>SCP</b>でしか掛けられません。費用の集計は、タグの付け方をそろえ（タグポリシー）、請求データで使えるように<b>コスト配分タグを有効化</b>するのが基本の流れです。","reasons":[{"l":"B","html":"予算の通知は事後の気づきであり、起動そのものは止められません。また部門別の集計には、タグを請求データへ反映させる設定が前提になります。"},{"l":"C","html":"メンバーアカウントの管理者は、自分でそのポリシーを外せます。アカウント内のIAMでは、管理者自身を縛る予防策になりません。"},{"l":"D","html":"Configルールは<b>検出</b>の仕組みで、起動を防ぐ予防策ではありません。要件①は「起動できない」ことを求めています。"}],"refs":"<a href=\"#management\" data-go=\"management\">第8章 8.5 AWS Organizations</a> ／ <a href=\"#d1\" data-go=\"d1\">第11章 11.1 アクセス管理</a> ／ <a href=\"#d4\" data-go=\"d4\">第14章 14.1 コスト管理ツールの使い分け</a>"},{"n":6,"topic":"弾力性 × パフォーマンス × コスト","level":3,"body":["ECサイトのWeb層はAuto Scalingグループで動いています。負荷は<b>常に最低6台分</b>あり、夕方には最大30台まで増えます。アプリはステートレスで、1台が突然終了しても処理に影響しません。要件は (1) 夕方のピークでも性能を落とさない、(2) 最低限の台数は<b>確実に確保</b>する、(3) 全体のコストを最小にする。最も適切な構成はどれですか。"],"options":[{"l":"A","html":"30台すべてをオンデマンドで起動し、3年のリザーブドインスタンスで30台分を購入する"},{"l":"B","html":"すべてをスポットインスタンスにし、単一のインスタンスタイプを指定する"},{"l":"C","html":"Auto Scalingグループの<b>混合インスタンスポリシー</b>で、ベース6台をオンデマンド（Savings Plansで割引）、それを超える分を<b>複数のインスタンスタイプのスポット</b>にし、容量の再調整を有効にする"},{"l":"D","html":"夕方の最大台数に合わせて、常時30台のオンデマンドを稼働させる"}],"answer":["C"],"multi":false,"req":"①ピーク時の性能＝スケールアウト（第3分野）／②最低台数は中断されない購入方法で確保（第2分野）／③変動部分は最安の購入方法で（第4分野）","key":"<b>常に必要な部分と変動する部分で購入方法を分ける</b>のが定石です。ベースはオンデマンドにSavings Plansを適用して確実に安く確保し、ステートレスで中断に耐える変動部分はスポットで賄います。スポットは複数のインスタンスタイプに分散させ、<b>容量の再調整</b>で中断の兆候が出たインスタンスを先回りして置き換えます。","reasons":[{"l":"A","html":"夕方の数時間しか使わない24台分まで3年間確保するため、要件③に反します。"},{"l":"B","html":"すべてがスポットでは、容量不足や一斉の中断で最低台数を確保できず要件②を満たしません。単一のインスタンスタイプはその危険をさらに高めます。"},{"l":"D","html":"性能は満たしますが、ピーク以外の時間も最大台数の費用を払い続けるため、要件③に反します。"}],"refs":"<a href=\"#compute\" data-go=\"compute\">第1章 1.2 Amazon EC2 Auto Scaling</a> ／ <a href=\"#d4\" data-go=\"d4\">第14章 14.3 コンピューティングのコスト最適化</a> ／ <a href=\"#d2\" data-go=\"d2\">第12章 12.1 スケーリング戦略</a>"},{"n":7,"topic":"セキュリティ × 弾力性","level":3,"body":["S3バケットに請求書のPDFがアップロードされるたびに、内容を読み取って会計システムへ登録します。要件は (1) 処理の待ち行列に入っているデータも<b>KMSで暗号化</b>する、(2) 処理に<b>何度か失敗したファイルは失われず</b>、後から調べて再処理できる、(3) アップロードが集中しても処理側が過負荷にならない。最も適切な構成はどれですか。"],"options":[{"l":"A","html":"S3イベント通知で<b>Lambdaを直接（非同期で）呼び出し</b>、Lambdaの同時実行数を大きくする"},{"l":"B","html":"処理用のEC2が1分ごとにバケットの一覧を取得し、未処理のファイルを探して処理する"},{"l":"C","html":"S3イベント通知をSNSトピックへ送り、Eメールで担当者に通知して手動で登録する"},{"l":"D","html":"S3イベント通知を<b>カスタマー管理のKMSキーでSSEを有効にしたSQSキュー</b>へ送り（キーポリシーでS3に使用を許可）、Lambdaがキューから取り出して処理する。キューには<b>リドライブポリシーでデッドレターキュー</b>を設定する"}],"answer":["D"],"multi":false,"req":"①待ち行列のデータも暗号化（第1分野）／②失敗したメッセージを保持して再処理（第2分野）／③集中時の負荷を平準化＝バッファ（第2分野）","key":"<b>SQSを挟むとバッファになり</b>、Lambdaは取り出せる分だけ処理するので集中しても過負荷になりません。規定回数失敗したメッセージは<b>デッドレターキュー</b>へ移り、失われずに後から調べられます。S3からの通知を暗号化キューへ送るには、S3がキーを使えるよう<b>カスタマー管理キーのキーポリシー</b>で許可する必要があります（AWS管理キーはキーポリシーを変更できません）。","reasons":[{"l":"A","html":"非同期呼び出しは失敗時に再試行されますが、宛先やDLQを設定しなければ最終的に失敗したイベントは破棄されます。同時実行数を増やすと、集中時にそのまま会計システムへ負荷が流れ込み、要件③にも反します。"},{"l":"B","html":"一覧取得によるポーリングはファイル数が増えるほど遅く高くなり、失敗の記録や再処理の仕組みも自前で作る必要があります。"},{"l":"C","html":"通知と手作業の登録では自動処理の要件を満たさず、暗号化・再処理のどちらにも応えていません。"}],"refs":"<a href=\"#integration\" data-go=\"integration\">第6章 6.1 Amazon SQS</a> ／ <a href=\"#security\" data-go=\"security\">第5章 5.8 AWS Key Management Service (KMS)</a> ／ <a href=\"#d2\" data-go=\"d2\">第12章 12.2 疎結合アーキテクチャ（Decoupling）</a>"},{"n":8,"topic":"弾力性 × コスト","level":2,"body":["本社のデータセンターとAWSのVPCを接続します。要件は (1) 日常の通信は<b>帯域と遅延が安定した専用線</b>を使う、(2) 専用線が切れても<b>通信を継続できる</b>、(3) 2本目の専用線を引くほどの費用はかけられず、<b>切り替え後は帯域が下がってもよい</b>。最も適切な構成はどれですか。"],"options":[{"l":"A","html":"Direct Connectを1本だけ契約し、障害時は復旧を待つ"},{"l":"B","html":"Direct Connectを主経路にし、<b>Site-to-Site VPNをバックアップ経路</b>として構成する"},{"l":"C","html":"Site-to-Site VPNを2本（2つのトンネル）張り、専用線は使わない"},{"l":"D","html":"異なるロケーションに2本のDirect Connectを契約する"}],"answer":["B"],"multi":false,"req":"①安定した帯域と遅延＝Direct Connect（第3分野）／②専用線の障害に備える（第2分野）／③2本目の専用線は不要、切り替え後の帯域低下は許容（第4分野）","key":"<b>Direct Connect＋VPNのバックアップ</b>は、費用を抑えて専用線の単一障害点をなくす定番です。BGPで専用線の経路を優先させ、専用線が切れたときだけインターネット経由のVPNへ切り替わります。","reasons":[{"l":"A","html":"専用線1本は単一障害点で、要件②を満たしません。"},{"l":"C","html":"VPNはインターネットを経由するため、帯域と遅延が安定せず要件①を満たしません。"},{"l":"D","html":"最も可用性は高い構成ですが、要件③が明示的に「2本目の専用線の費用はかけない」としています。"}],"refs":"<a href=\"#network\" data-go=\"network\">第3章 3.3 VPCの外部接続：エンドポイント・PrivateLink・ピアリング・Transit Gateway・Direct Connect</a> ／ <a href=\"#d2\" data-go=\"d2\">第12章 12.5 高可用性（HA）と耐障害性（Fault Tolerance）</a>"},{"n":9,"topic":"パフォーマンス（データ取り込み） × コスト","level":3,"body":["Webサイトのクリックストリーム（JSON）をS3に集め、Athenaで分析しています。現在はアプリが<b>1イベントごとに小さなJSONファイルをS3へ書き込んで</b>おり、クエリが遅く、スキャン料金も高くなっています。要件は (1) 数分程度の遅れで分析できればよい、(2) クエリの速度と料金を改善する、(3) 取り込みのためのサーバーは管理しない。最も適切な構成はどれですか。"],"options":[{"l":"A","html":"Kinesis Data Streamsで受け、EC2上のコンシューマーがJSONのまま1イベントずつS3へ書き込む"},{"l":"B","html":"1イベントずつ書き込む方式はそのままにし、Athenaのクエリで<code>LIMIT</code>句を使う"},{"l":"C","html":"Amazon Data Firehoseで受け、<b>バッファリングしてまとめ</b>、<b>Parquet形式へ変換</b>し、日付で<b>パーティション分割</b>してS3へ配信する"},{"l":"D","html":"RDS for PostgreSQLに1イベントずつINSERTし、分析もRDSで行う"}],"answer":["C"],"multi":false,"req":"①数分の遅れは許容＝ニアリアルタイムで十分（第3分野 3.5）／②スキャン量とファイル数を減らす（第3・第4分野）／③サーバーレスで取り込む","key":"Firehoseは受け取ったレコードを<b>バッファリングして大きなファイルにまとめ</b>、Glueデータカタログのスキーマを使って<b>列指向のParquetへ変換</b>し、パーティション分割して配信できます。小さなファイルが大量にある状態と、行指向のJSONを全列スキャンする状態の両方が解消され、Athenaの速度と料金が同時に改善します。","reasons":[{"l":"A","html":"EC2のコンシューマーを管理する必要があり要件③に反します。1イベントずつJSONで書き込むので、小さなファイルと全列スキャンの問題も残ります。"},{"l":"B","html":"<code>LIMIT</code>は返す行数を減らすだけで、Athenaがスキャンするデータ量はほとんど減りません。"},{"l":"D","html":"大量のクリックストリームを1件ずつRDSへ書き込むと書き込み負荷が高く、分析にはデータウェアハウスやAthenaが適しています。サーバーの管理も必要です。"}],"refs":"<a href=\"#analytics\" data-go=\"analytics\">第7章 7.1 Amazon Kinesis</a> ／ <a href=\"#analytics\" data-go=\"analytics\">第7章 7.3 Amazon Athena</a> ／ <a href=\"#d3\" data-go=\"d3\">第13章 13.1 ストレージとパフォーマンス</a>"},{"n":10,"topic":"全分野","level":3,"body":["オンプレミスの1台のサーバーで動くWebアプリケーションを、ALBとAuto Scalingグループの構成へ移行します。現在のアプリは (1) ログイン状態を<b>サーバーのメモリ</b>に持ち、(2) 利用者がアップロードした画像を<b>サーバーのローカルディスク</b>に保存しています。要件は、どのインスタンスに振り分けられても同じように動作し、スケールインやAZ障害でデータが失われないことです。コストと管理の手間も抑えます。<b>適切な対策を2つ選択してください。</b>"],"options":[{"l":"A","html":"ALBでスティッキーセッションを有効にし、同じ利用者を常に同じインスタンスへ振り分ける"},{"l":"B","html":"セッション情報を<b>DynamoDBまたはElastiCache</b>へ外部化する"},{"l":"C","html":"各インスタンスのインスタンスストアに画像を保存し、定期的にほかのインスタンスへコピーする"},{"l":"D","html":"アップロードされた画像を<b>S3</b>へ保存し、アプリからはS3のキーを参照する"},{"l":"E","html":"EBSのマルチアタッチで1つのボリュームを全インスタンスから共有する"}],"answer":["B","D"],"multi":true,"req":"①どのインスタンスでも同じ動作＝<b>状態をインスタンスの外へ</b>（第2分野）／②スケールインやAZ障害でもデータを失わない＝耐久性のある共有ストレージ（第1・第2分野）／③コストと管理の手間（第4分野）","key":"水平スケールする構成では、<b>インスタンスを使い捨てにできる</b>ことが前提です。セッションはDynamoDBやElastiCacheへ、ファイルは複数のAZにまたがって保存される<b>S3</b>へ移すと、どのインスタンスが終了しても利用者への影響がなくなります。","reasons":[{"l":"A","html":"振り分け先を固定するだけで、そのインスタンスが終了すればログイン状態は失われます。負荷も偏ります。"},{"l":"C","html":"インスタンスストアはインスタンスの停止や終了で消える一時ストレージです。自前のコピー処理は管理の手間が増え、コピー前に終了すれば画像が失われます。"},{"l":"E","html":"EBSのマルチアタッチはio1/io2に限られ、<b>同じAZのインスタンス</b>からしか接続できません。AZ障害に耐えられず、複数から書き込むにはクラスター対応のファイルシステムも必要です。"}],"refs":"<a href=\"#d2\" data-go=\"d2\">第12章 12.1 スケーリング戦略</a> ／ <a href=\"#storage\" data-go=\"storage\">第2章 2.1 Amazon S3</a> ／ <a href=\"#storage\" data-go=\"storage\">第2章 2.2 Amazon EBS</a> ／ <a href=\"#database\" data-go=\"database\">第4章 4.4 Amazon ElastiCache</a>"}]}];
